lessons.concept:
Inside a loop:
- `break` leaves the loop immediately.
- `continue` skips the rest of this iteration and starts the next one.

`break` also ends a switch or select. That's a gotcha: a break inside a switch that is inside a loop only leaves the switch. To leave the loop, use a label:

    outer:
    for i := range 3 {
        for j := range 3 {
            if j == 2 { continue outer }  // next i
            if i == 2 { break outer }     // leave both loops
        }
    }

lessons.code:
package main

import "fmt"

func main() {
	for i := 1; i <= 10; i++ {
		if i%2 == 0 {
			continue // skip even numbers
		}
		if i > 7 {
			break // stop completely
		}
		fmt.Println(i)
	}

outer:
	for i := range 3 {
		for j := range 3 {
			if j == 1 {
				continue outer
			}
			fmt.Println("pair", i, j)
		}
	}
}

