import (
	"fmt"
	"strings"
)

type node struct {
	val  int
	next *node
}

type List struct {
	head *node
	size int
}

func (l *List) Push(v int) {
	l.head = &node{val: v, next: l.head}
	l.size++
}

func (l *List) Reverse() {
	var prev *node
	cur := l.head
	for cur != nil {
		next := cur.next
		cur.next = prev
		prev, cur = cur, next
	}
	l.head = prev
}

func (l *List) String() string {
	var b strings.Builder
	b.WriteString("[")
	for n := l.head; n != nil; n = n.next {
		if n != l.head {
			b.WriteString(" ")
		}
		fmt.Fprint(&b, n.val)
	}
	b.WriteString("]")
	return b.String()
}

func main() {
	var l List
	for i := 1; i <= 4; i++ {
		l.Push(i)
	}
	fmt.Println(&l, l.size)
	l.Reverse()
	fmt.Println(&l)
}

