	s.Push(1)
	s.Push(2)
	fmt.Println(s.Pop())
	fmt.Println(s.Len())

	big := NewStack(100)
	big.Push(42)
	fmt.Println(big.Len(), cap(big.items))
	_, err := (&Stack{}).Pop()
	fmt.Println(err)
}

