package main

import (
	"errors"
	"fmt"
)

var ErrNotFound = errors.New("not found")

type ValidationError struct {
	Field, Reason string
}

func (e *ValidationError) Error() string { return e.Field + ": " + e.Reason }

func validate(name string, age int) error {
	var errs []error
	if name == "" {
		errs = append(errs, &ValidationError{"name", "required"})
	}
	if age < 0 {
		errs = append(errs, &ValidationError{"age", "must be >= 0"})
	}
	return errors.Join(errs...) // nil when errs is empty
}

func find(id int) error {
	if id != 1 {
		return fmt.Errorf("user %d: %w", id, ErrNotFound)
	}
	return nil
}

func main() {
	fmt.Println(errors.Is(find(2), ErrNotFound), find(1) == nil)

	err := validate("", -3)
	fmt.Println(err)
	var ve *ValidationError
	if errors.As(err, &ve) {
		fmt.Println("first bad field:", ve.Field)
	}
	fmt.Println(validate("ada", 3) == nil)
}

