func parse(sc *bufio.Scanner) (map[string]string, error) {
	cfg := map[string]string{}
	var errs []error
	n := 0
	for sc.Scan() {
		n++
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		k, v, ok := strings.Cut(line, "=")
		if !ok {
			errs = append(errs, fmt.Errorf("line %d: missing '='", n))
			continue
		}
		k = strings.TrimSpace(k)
		if k == "" {
			errs = append(errs, fmt.Errorf("line %d: empty key", n))
			continue
		}
		cfg[k] = strings.TrimSpace(v)
	}
	errs = append(errs, sc.Err())
	return cfg, errors.Join(errs...)
}

func main() {
	cfg, err := parse(bufio.NewScanner(os.Stdin))
	for _, k := range slices.Sorted(maps.Keys(cfg)) {
		fmt.Printf("%s=%q\n", k, cfg[k])
	}
	if err != nil {
		fmt.Println("errors:")
		fmt.Println(err)
	}
