import (
	"cmp"
	"fmt"
)

type node[K cmp.Ordered, V any] struct {
	key         K
	val         V
	left, right *node[K, V]
}

type Tree[K cmp.Ordered, V any] struct {
	root *node[K, V]
	size int
}

func (t *Tree[K, V]) Put(k K, v V) {
	p := &t.root
	for *p != nil {
		switch c := cmp.Compare(k, (*p).key); {
		case c < 0:
			p = &(*p).left
		case c > 0:
			p = &(*p).right
		default:
			(*p).val = v
			return
		}
	}
	*p = &node[K, V]{key: k, val: v}
	t.size++
}

func (t *Tree[K, V]) Walk(visit func(K, V)) {
	var rec func(*node[K, V])
	rec = func(n *node[K, V]) {
		if n == nil {
			return
		}
		rec(n.left)
		visit(n.key, n.val)
		rec(n.right)
	}
	rec(t.root)
}

func main() {
	var t Tree[string, int]
	for i, w := range []string{"mango", "apple", "zebra", "kiwi", "apple"} {
		t.Put(w, i)
	}
	t.Walk(func(k string, v int) { fmt.Print(k, "=", v, " ") })
	fmt.Println("| size", t.size)
}

