func search(xs []int, target int) int {
	lo, hi := 0, len(xs) // half-open [lo, hi)
	for lo < hi {
		mid := lo + (hi-lo)/2
		switch {
		case xs[mid] < target:
			lo = mid + 1
		case xs[mid] > target:
			hi = mid
		default:
			return mid
		}
	}
	return -1
}

func main() {
	ps := []Player{{"ada", 90}, {"bob", 75}, {"cy", 90}, {"dee", 60}}
	slices.SortFunc(ps, func(a, b Player) int {
		return cmp.Or(cmp.Compare(b.Score, a.Score), cmp.Compare(a.Name, b.Name))
	})
	fmt.Println(ps)

	xs := []int{1, 4, 9, 16, 25, 36}
	fmt.Println(search(xs, 16), search(xs, 5))
	fmt.Println(slices.BinarySearch(xs, 10))
}

