Breadth-first search explores a graph level by level from a start node,
so the first time it reaches a node is along a SHORTEST path (counting
edges).

▸  REPRESENTATION
An adjacency list: map[string][]string (or [][]int for numbered nodes).

▸  THE ALGORITHM
    queue := []string{start}
    dist := map[string]int{start: 0}
    for len(queue) > 0 {
        cur := queue[0]; queue = queue[1:]
        for _, next := range graph[cur] {
            if _, seen := dist[next]; !seen {
                dist[next] = dist[cur] + 1
                prev[next] = cur
                queue = append(queue, next)
