package main

import (
	"fmt"
	"slices"
	"strings"
)

func shortestPath(g map[string][]string, from, to string) []string {
	prev := map[string]string{}
	seen := map[string]bool{from: true}
	queue := []string{from}
	for len(queue) > 0 {
		cur := queue[0]
		queue = queue[1:]
		if cur == to {
			break
		}
		for _, nb := range g[cur] {
			if !seen[nb] {
				seen[nb] = true
				prev[nb] = cur
				queue = append(queue, nb)
			}
		}
	}
	if !seen[to] {
		return nil
	}
	path := []string{to}
	for at := to; at != from; at = prev[at] {
		path = append(path, prev[at])
	}
	slices.Reverse(path)
	return path
}

func main() {
	g := map[string][]string{
		"A": {"B", "C"}, "B": {"A", "D"}, "C": {"A", "D", "E"},
		"D": {"B", "C", "F"}, "E": {"C", "F"}, "F": {"D", "E"}, "G": {},
	}
	p := shortestPath(g, "A", "F")
	fmt.Println(strings.Join(p, " -> "), "hops:", len(p)-1)
	fmt.Println(shortestPath(g, "A", "G") == nil)
}

