import "fmt"

func minCoins(coins []int, amount int) int {
	const inf = 1 << 30
	dp := make([]int, amount+1)
	for a := 1; a <= amount; a++ {
		dp[a] = inf
		for _, c := range coins {
			if c <= a && dp[a-c]+1 < dp[a] {
				dp[a] = dp[a-c] + 1
			}
		}
	}
	if dp[amount] >= inf {
		return -1
	}
	return dp[amount]
}

func main() {
	coins := []int{1, 5, 10, 25}
	for _, amt := range []int{0, 7, 30, 63, 99} {
		fmt.Printf("%2d -> %d coins\n", amt, minCoins(coins, amt))
	}
	fmt.Println(minCoins([]int{4, 6}, 7))
}

