package main

import (
	"fmt"
	"strings"
)

func Map[T, U any](xs []T, f func(T) U) []U {
	out := make([]U, 0, len(xs))
	for _, x := range xs {
		out = append(out, f(x))
	}
	return out
}

func Filter[T any](xs []T, keep func(T) bool) []T {
	var out []T
	for _, x := range xs {
		if keep(x) {
			out = append(out, x)
		}
	}
	return out
}

func Reduce[T, A any](xs []T, init A, f func(A, T) A) A {
	acc := init
	for _, x := range xs {
		acc = f(acc, x)
	}
	return acc
}

func main() {
	words := []string{"go", "gopher", "channel", "map", "goroutine"}
	gWords := Filter(words, func(s string) bool { return strings.HasPrefix(s, "go") })
	lengths := Map(gWords, func(s string) int { return len(s) })
	total := Reduce(lengths, 0, func(a, n int) int { return a + n })
	fmt.Println(gWords, lengths, total)
	fmt.Println(Map([]int{1, 2, 3}, func(n int) string { return strings.Repeat("*", n) }))
}

