import (
	"cmp"
	"fmt"
)

type Number interface {
	~int | ~int64 | ~float64
}

type Celsius float64

func Sum[T Number](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

func Clamp[T cmp.Ordered](v, lo, hi T) T {
	return max(lo, min(v, hi))
}

func Count[T comparable](xs []T, target T) int {
	n := 0
	for _, x := range xs {
		if x == target {
			n++
		}
	}
	return n
}

func main() {
	fmt.Println(Sum([]int{1, 2, 3}), Sum([]Celsius{20.5, 21.5}))
	fmt.Println(Clamp(15, 0, 10), Clamp("m", "a", "k"))
	fmt.Println(Count([]string{"a", "b", "a"}, "a"))
}

lessons.concept:
Since Go 1.23 you can range over a FUNCTION with one of these shapes:

    func(yield func() bool)
    func(yield func(V) bool)            // iter.Seq[V]
    func(yield func(K, V) bool)         // iter.Seq2[K, V]

The loop body becomes 'yield'. Your iterator calls yield for each value
and must stop as soon as yield returns false (the loop did 'break').

    func Countdown(n int) iter.Seq[int] {
        return func(yield func(int) bool) {
            for i := n; i > 0; i-- {
                if !yield(i) { return }
            }
        }
    }
    for i := range Countdown(3) { fmt.Println(i) }

▸  THE STANDARD LIBRARY SPEAKS ITERATORS
    maps.Keys(m), maps.Values(m), maps.All(m)
    slices.All(s), slices.Values(s), slices.Backward(s)
    slices.Collect(seq), slices.Sorted(seq)
    strings.SplitSeq / FieldsSeq / Lines (Go 1.24) - no allocation of
    a whole []string

▸  WHY
Lazy, composable sequences (filtering, paging through an API, walking
a tree) without building intermediate slices or channels.

