package main

import (
	"fmt"
	"iter"
	"slices"
	"strings"
)

func Fib() iter.Seq[int] {
	return func(yield func(int) bool) {
		a, b := 0, 1
		for {
			if !yield(a) {
				return
			}
			a, b = b, a+b
		}
	}
}

func Take[V any](seq iter.Seq[V], n int) iter.Seq[V] {
	return func(yield func(V) bool) {
		if n <= 0 {
			return
		}
		i := 0
		for v := range seq {
			if !yield(v) {
				return
			}
			i++
			if i == n {
				return
			}
		}
	}
}

func main() {
	for f := range Fib() {
		if f > 50 {
			break // yield returns false inside Fib
		}
		fmt.Print(f, " ")
	}
	fmt.Println()
	fmt.Println(slices.Collect(Take(Fib(), 10)))
	for i, w := range slices.Backward([]string{"a", "b", "c"}) {
		fmt.Print(i, w, " ")
	}
	fmt.Println()
	for part := range strings.SplitSeq("x,y,z", ",") {
		fmt.Print("[", part, "]")
	}
	fmt.Println()
}

lessons.concept:
A closure is a function value plus the variables it captured. Three
patterns you'll use constantly:

▸  1. STATEFUL GENERATORS
    func idGen(prefix string) func() string { n := 0; return func() ... }

▸  2. CONFIGURABLE BEHAVIOUR (functional options)
    type Option func(*Server)
    func WithPort(p int) Option { return func(s *Server) { s.port = p } }
    func NewServer(opts ...Option) *Server { ... for _, o := range opts { o(s) } }
Adds optional settings without breaking callers - very common in Go
APIs (grpc, zap, ...).

▸  3. DECORATORS / MIDDLEWARE
Wrap a function to add timing, logging, retries, auth:
    func logged(f func(int) int) func(int) int {
        return func(n int) int { r := f(n); log(...); return r }
    }

▸  CAPTURE BY REFERENCE
The closure sees later changes to captured variables, and goroutines
capturing a variable share it - which needs synchronisation.

