package main

import (
	"fmt"
	"strings"
)

type Server struct {
	host    string
	port    int
	verbose bool
}

type Option func(*Server)

func WithPort(p int) Option { return func(s *Server) { s.port = p } }
func Verbose() Option       { return func(s *Server) { s.verbose = true } }

func NewServer(host string, opts ...Option) *Server {
	s := &Server{host: host, port: 80} // defaults
	for _, opt := range opts {
		opt(s)
	}
	return s
}

func traced(name string, f func(string) string) func(string) string {
	calls := 0
	return func(in string) string {
		calls++
		out := f(in)
		fmt.Printf("[%s call %d] %q -> %q\n", name, calls, in, out)
		return out
	}
}

func main() {
	fmt.Printf("%+v\n", *NewServer("localhost"))
	fmt.Printf("%+v\n", *NewServer("example.com", WithPort(8443), Verbose()))
	up := traced("upper", strings.ToUpper)
	up("go")
	up("gopher")
}

