package main

import (
	"fmt"
	"reflect"
)

type User struct {
	Name  string `json:"name" validate:"required"`
	Email string `json:"email" validate:"required"`
	Age   int    `json:"age"`
}

// validate checks every field tagged validate:"required" is non-zero.
func validate(x any) []string {
	var problems []string
	v := reflect.ValueOf(x)
	t := v.Type()
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		if f.Tag.Get("validate") == "required" && v.Field(i).IsZero() {
			problems = append(problems, f.Tag.Get("json")+" is required")
		}
	}
	return problems
}

func main() {
	u := User{Name: "Ada"}
	t := reflect.TypeOf(u)
	fmt.Println(t.Name(), t.Kind(), t.NumField())
	fmt.Println(validate(u))

	p := reflect.ValueOf(&u).Elem()
	p.FieldByName("Age").SetInt(36)
	fmt.Println(u.Age, p.CanSet(), reflect.ValueOf(u).CanSet())
}

