package main

import "fmt"

func firstNegative(grid [][]int) (int, int) {
	for i, row := range grid {
		for j, v := range row {
			if v < 0 {
				return i, j
			}
		}
	}
	return -1, -1
}

func main() {
	grid := [][]int{{1, 2}, {3, -4}, {-5, 6}}
	fmt.Println(firstNegative(grid))

	count := 0
rows:
	for _, row := range grid {
		for _, v := range row {
			if v < 0 {
				continue rows // skip the rest of this row
			}
			count++
		}
	}
	fmt.Println("non-negative before the first negative in each row:", count)

	switch n := 1; n {
	case 1:
		fmt.Print("one ")
		fallthrough
	case 2:
		fmt.Println("(and fell into two)")
	}
}

package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"strings"
)

type Set[T cmp.Ordered] struct{ m map[T]struct{} }

func NewSet[T cmp.Ordered](items ...T) *Set[T] {
	s := &Set[T]{m: make(map[T]struct{}, len(items))}
	for _, it := range items {
		s.Add(it)
	}
	return s
}

func (s *Set[T]) Add(v T)      { s.m[v] = struct{}{} }
func (s *Set[T]) Has(v T) bool { _, ok := s.m[v]; return ok }
func (s *Set[T]) Sorted() []T  { return slices.Sorted(maps.Keys(s.m)) }

func (s *Set[T]) Union(o *Set[T]) *Set[T] {
	out := NewSet(s.Sorted()...)
	for v := range o.m {
		out.Add(v)
	}
	return out
}

func (s *Set[T]) Intersect(o *Set[T]) *Set[T] {
	out := NewSet[T]()
	for v := range s.m {
		if o.Has(v) {
			out.Add(v)
		}
	}
	return out
}

func (s *Set[T]) String() string {
	parts := make([]string, 0, len(s.m))
	for _, v := range s.Sorted() {
		parts = append(parts, fmt.Sprint(v))
	}
	return "{" + strings.Join(parts, " ") + "}"
}

func main() {
	a := NewSet("go", "rust", "c")
	b := NewSet("c", "zig", "go")
	fmt.Println(a.Union(b), a.Intersect(b), a.Has("rust"), b.Has("rust"))
	nums := NewSet(5, 1, 3, 1)
	fmt.Println(nums, len(nums.m))
}

