import (
	"fmt"
	"strings"
)

func shout(in string, out chan string) {
	out <- strings.ToUpper(in) // blocks until main receives
}

func main() {
	ch := make(chan string)
	go shout("hello", ch)
	go shout("gopher", ch)
	a, b := <-ch, <-ch // two receives; order depends on scheduling
	if a > b {
		a, b = b, a // sort so the printed output is stable
	}
	fmt.Println(a, b)

	done := make(chan struct{})
	data := 0
	go func() {
		data = 99          // happens before the send...
		done <- struct{}{} // ...so main sees data == 99 after receiving
	}()
	<-done
	fmt.Println(data)
}

