import "fmt"

func main() {
	ch := make(chan string, 3)
	ch <- "a"
	ch <- "b" // no receiver needed yet: room in the buffer
	fmt.Println(len(ch), cap(ch))
	fmt.Println(<-ch, <-ch) // FIFO order
	fmt.Println(len(ch))

	// A buffer of N lets N goroutines finish without waiting.
	results := make(chan int, 4)
	for i := range 4 {
		go func() { results <- i * 10 }()
	}
	sum := 0
	for range 4 {
		sum += <-results
	}
