import "fmt"

func produce(n int) <-chan int {
	ch := make(chan int)
	go func() {
		defer close(ch) // the sender closes when done
		for i := 1; i <= n; i++ {
			ch <- i
		}
	}()
	return ch
}

func main() {
	total := 0
	for v := range produce(5) {
		total += v
		fmt.Println("got", v, "total", total)
	}
	ch := make(chan int, 1)
	ch <- 7
	close(ch)
	a, ok1 := <-ch
	b, ok2 := <-ch
	fmt.Println(a, ok1, b, ok2)
}

