import "fmt"

func producer(out chan<- int, n int) {
	for i := range n {
		out <- i * i
	}
	close(out) // allowed: the sender owns the channel
}

func consumer(in <-chan int, done chan<- int) {
	sum := 0
	for v := range in {
		sum += v
	}
	done <- sum
	// in <- 1 would not compile: in is receive-only
}

func main() {
	data := make(chan int)
	done := make(chan int)
	go producer(data, 5)
	go consumer(data, done)
	fmt.Println("sum of squares 0..4:", <-done)
}

