func slow(d time.Duration, msg string) <-chan string {
	ch := make(chan string, 1)
	go func() {
		time.Sleep(d)
		ch <- msg
	}()
	return ch
}

func main() {
	select {
	case m := <-slow(10*time.Millisecond, "fast reply"):
		fmt.Println(m)
	case <-time.After(500 * time.Millisecond):
		fmt.Println("timeout")
	}

	select {
	case m := <-slow(500*time.Millisecond, "too slow"):
		fmt.Println(m)
	case <-time.After(20 * time.Millisecond):
		fmt.Println("timeout")
	}

	queue := make(chan int, 1)
	for i := range 3 {
		select {
		case queue <- i:
			fmt.Println("queued", i)
		default:
			fmt.Println("full, dropped", i)
		}
	}
}

