package main

import (
	"fmt"
	"runtime"
	"time"
)

func fetch(i int) string {
	time.Sleep(time.Duration(i) * time.Millisecond)
	return fmt.Sprint("result ", i)
}

func firstLeaky(n int) string {
	ch := make(chan string)
	for i := range n {
		go func() { ch <- fetch(i) }()
	}
	return <-ch
}

func firstFixed(n int) string {
	ch := make(chan string, n) // room for every sender
	for i := range n {
		go func() { ch <- fetch(i) }()
	}
	return <-ch
}

func main() {
	base := runtime.NumGoroutine()
	firstLeaky(10)
	time.Sleep(50 * time.Millisecond)
	fmt.Println("leaked goroutines:", runtime.NumGoroutine()-base)

	base = runtime.NumGoroutine()
	firstFixed(10)
	time.Sleep(50 * time.Millisecond)
	fmt.Println("after fixed version:", runtime.NumGoroutine()-base)
}

package main

import "fmt"

type part struct{ idx, sum int }

func main() {
	const n, workers = 1_000_000, 4
	results := make(chan part, workers)
	chunk := n / workers
	for w := range workers {
		lo, hi := w*chunk+1, (w+1)*chunk
		go func() {
			s := 0
			for i := lo; i <= hi; i++ {
				s += i
			}
			results <- part{w, s}
		}()
	}
	var partials [workers]int
	for range workers {
		p := <-results
		partials[p.idx] = p.sum
	}
	total := 0
	for i, s := range partials {
		fmt.Printf("chunk %d: %d\n", i, s)
		total += s
	}
	fmt.Println("total:", total, total == n*(n+1)/2)
}

