func slowSquare(ctx context.Context, n int, d time.Duration) (int, error) {
	select {
	case <-time.After(d):
		return n * n, nil
	case <-ctx.Done():
		return 0, ctx.Err()
	}
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 100*time.Millisecond)
	defer cancel()

	v, err := slowSquare(ctx, 7, 10*time.Millisecond)
	fmt.Println(v, err)

	v, err = slowSquare(ctx, 8, time.Second)
	fmt.Println(v, err, errors.Is(err, context.DeadlineExceeded))

	parent, stop := context.WithCancel(context.Background())
	child, cancelChild := context.WithTimeout(parent, time.Hour)
	defer cancelChild()
	stop() // cancelling the parent cancels the child
	<-child.Done()
	fmt.Println("child:", child.Err())
}

