import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

// Group is a minimal errgroup: first error wins and cancels the rest.
type Group struct {
	wg     sync.WaitGroup
	once   sync.Once
	err    error
	cancel context.CancelCauseFunc
}

func WithContext(ctx context.Context) (*Group, context.Context) {
	ctx, cancel := context.WithCancelCause(ctx)
	return &Group{cancel: cancel}, ctx
}

func (g *Group) Go(f func() error) {
	g.wg.Add(1)
	go func() {
		defer g.wg.Done()
		if err := f(); err != nil {
			g.once.Do(func() {
				g.err = err
				g.cancel(err)
			})
		}
	}()
}

func (g *Group) Wait() error {
	g.wg.Wait()
	g.cancel(nil)
	return g.err
}

func task(ctx context.Context, name string, d time.Duration, fail bool) error {
	select {
	case <-time.After(d):
		if fail {
			return errors.New(name + " failed")
		}
		return nil
	case <-ctx.Done():
		return fmt.Errorf("%s cancelled: %w", name, context.Cause(ctx))
	}
}

func main() {
	g, ctx := WithContext(context.Background())
	g.Go(func() error { return task(ctx, "db", 10*time.Millisecond, true) })
	g.Go(func() error { return task(ctx, "cache", time.Second, false) })
	g.Go(func() error { return task(ctx, "api", time.Second, false) })
	start := time.Now()
	err := g.Wait()
	fmt.Println("first error:", err)
	fmt.Println("stopped early:", time.Since(start) < 500*time.Millisecond)
}

