import (
	"context"
	"errors"
	"fmt"
	"time"
)

var ErrTemporary = errors.New("temporary failure")

func retry(ctx context.Context, attempts int, base time.Duration, op func(int) error) error {
	delay := base
	for i := 1; ; i++ {
		err := op(i)
		if err == nil || !errors.Is(err, ErrTemporary) || i == attempts {
			return err
		}
		fmt.Printf("  attempt %d failed, retrying in %v\n", i, delay)
		select {
		case <-time.After(delay):
		case <-ctx.Done():
			return ctx.Err()
		}
		delay *= 2
	}
}

func main() {
	ctx := context.Background()
	fmt.Println("flaky:", retry(ctx, 5, time.Millisecond, func(i int) error {
		if i < 3 {
			return ErrTemporary
		}
		return nil
	}))
	fmt.Println("fatal:", retry(ctx, 5, time.Millisecond, func(int) error {
		return errors.New("bad credentials")
	}))
	fmt.Println("gave up:", retry(ctx, 3, time.Millisecond, func(int) error {
		return ErrTemporary
	}))
}

