var site = map[string][]string{
	"/":          {"/about", "/blog", "/contact"},
	"/about":     {"/", "/team"},
	"/blog":      {"/blog/go", "/blog/rust", "/"},
	"/blog/go":   {"/blog", "/about"},
	"/blog/rust": {"/blog"},
	"/team":      {"/about"},
	"/contact":   {},
}

func fetch(url string) []string {
	time.Sleep(2 * time.Millisecond)
	return site[url]
}

func main() {
	var (
		mu      sync.Mutex
		visited = map[string]bool{}
		wg      sync.WaitGroup
		sem     = make(chan struct{}, 3)
	)
	var crawl func(url string)
	crawl = func(url string) {
		defer wg.Done()
		sem <- struct{}{}
		links := fetch(url)
		<-sem
		for _, l := range links {
			mu.Lock()
			seen := visited[l]
			visited[l] = true
			mu.Unlock()
			if !seen {
				wg.Add(1)
				go crawl(l)
			}
		}
	}
	visited["/"] = true
	wg.Add(1)
	go crawl("/")
	wg.Wait()

	pages := make([]string, 0, len(visited))
	for p := range visited {
		pages = append(pages, p)
	}
	slices.Sort(pages)
	fmt.Println(pages)
	fmt.Println("pages:", len(pages))
}

