import (
	"fmt"
	"io"
	"strings"
)

// LogBuffer is a ReadWriteCloser built from a strings.Builder.
type LogBuffer struct {
	sb     strings.Builder
	read   int
	closed bool
}

func (l *LogBuffer) Write(p []byte) (int, error) {
	if l.closed {
		return 0, fmt.Errorf("write on closed buffer")
	}
	return l.sb.Write(p)
}

func (l *LogBuffer) Read(p []byte) (int, error) {
	s := l.sb.String()[l.read:]
	if s == "" {
		return 0, io.EOF
	}
	n := copy(p, s)
	l.read += n
	return n, nil
}

func (l *LogBuffer) Close() error { l.closed = true; return nil }

// consume asks only for a Reader, but closes it if it can.
func consume(r io.Reader) string {
	if c, ok := r.(io.Closer); ok {
		defer c.Close()
	}
	b, _ := io.ReadAll(r)
	return string(b)
}

func main() {
	var rwc io.ReadWriteCloser = &LogBuffer{}
	fmt.Fprint(rwc, "hello ")
	fmt.Fprint(rwc, "interfaces")
	fmt.Println(consume(rwc))
	_, err := rwc.Write([]byte("late"))
	fmt.Println(err)
}

