import (
	"fmt"
	"math/bits"
	"strings"
)

type IntSet struct{ words []uint64 }

func (s *IntSet) Add(x int) {
	w, b := x/64, uint(x%64)
	for w >= len(s.words) {
		s.words = append(s.words, 0)
	}
	s.words[w] |= 1 << b
}

func (s *IntSet) Has(x int) bool {
	w, b := x/64, uint(x%64)
	return w < len(s.words) && s.words[w]&(1<<b) != 0
}

func (s *IntSet) UnionWith(t *IntSet) {
	for i, tw := range t.words {
		if i < len(s.words) {
			s.words[i] |= tw
		} else {
			s.words = append(s.words, tw)
		}
	}
}

func (s *IntSet) Len() int {
	n := 0
	for _, w := range s.words {
		n += bits.OnesCount64(w)
	}
	return n
}

func (s *IntSet) String() string {
	var parts []string
	for i, w := range s.words {
		for b := 0; b < 64; b++ {
			if w&(1<<uint(b)) != 0 {
				parts = append(parts, fmt.Sprint(64*i+b))
			}
		}
	}
	return "{" + strings.Join(parts, " ") + "}"
}

func main() {
	var x, y IntSet
	x.Add(1)
	x.Add(144)
	x.Add(9)
	y.Add(9)
	y.Add(42)
	fmt.Println(&x, x.Len(), x.Has(9), x.Has(123))
	x.UnionWith(&y)
	fmt.Println(&x, x.Len())
	fmt.Printf("%08b %08b %08b\n", 0b1100&^0b0100, 0b1100&(0b1100-1), 0b1100&-0b1100)
}

