package main

import (
	"errors"
	"fmt"
)

func sign(x int) string {
	switch { // terminating: has default, every case returns
	case x < 0:
		return "negative"
	case x > 0:
		return "positive"
	default:
		return "zero"
	}
}

func mustPositive(x int) int {
	if x > 0 {
		return x
	}
	panic("not positive") // a terminating statement
}

func firstEven(xs []int) (int, error) {
	for _, x := range xs {
		if x%2 == 0 {
			return x, nil
		}
	}
	return 0, errors.New("none") // range loops are NOT terminating
}

func loopForever(ch chan int) int {
	for { // a for with no condition and no break: terminating
		if v := <-ch; v > 10 {
			return v
		}
	}
}

func main() {
	fmt.Println(sign(-3), sign(0), mustPositive(4))
	fmt.Println(firstEven([]int{3, 8, 5}))
	ch := make(chan int, 3)
	ch <- 1
	ch <- 20
	fmt.Println(loopForever(ch))
}

