package main

import "time"

// Session expires ttl after it was created.
type Session struct {
	created time.Time
	ttl     time.Duration
	now     func() time.Time
}

// NewSession uses now as its clock (pass time.Now in production).
func NewSession(now func() time.Time, ttl time.Duration) *Session {
	return &Session{created: now(), ttl: ttl, now: now}
}

func (s *Session) Expired() bool { return s.now().Sub(s.created) > s.ttl }

