package main

import "strings"

// JoinPlus concatenates with += (quadratic copying).
func JoinPlus(ws []string) string {
	s := ""
	for _, w := range ws {
		s += w + " "
	}
	return s
}

// JoinBuilder uses a strings.Builder (amortised appends).
func JoinBuilder(ws []string) string {
	var b strings.Builder
	for _, w := range ws {
		b.WriteString(w)
		b.WriteByte(' ')
	}
	return b.String()
}

