type roundTripFunc func(*http.Request) (*http.Response, error)

func (f roundTripFunc) RoundTrip(r *http.Request) (*http.Response, error) { return f(r) }

func respond(status int, body string) *http.Response {
	return &http.Response{StatusCode: status, Body: io.NopCloser(strings.NewReader(body)), Header: http.Header{}}
}

func TestLatestVersion(t *testing.T) {
	var gotPath, gotAuth string
	c := &VersionClient{BaseURL: "https://api.example", Token: "secret",
		HTTP: &http.Client{Transport: roundTripFunc(func(r *http.Request) (*http.Response, error) {
			gotPath, gotAuth = r.URL.Path, r.Header.Get("Authorization")
			return respond(200, `{"version":"1.26.1"}`), nil
		})}}
	v, err := c.Latest()
	if err != nil || v != "1.26.1" {
		t.Fatalf("got %q, %v", v, err)
	}
	if gotPath != "/latest" || gotAuth != "Bearer secret" {
		t.Errorf("request path %q auth %q", gotPath, gotAuth)
	}
}

func TestLatestNetworkError(t *testing.T) {
	c := &VersionClient{BaseURL: "https://api.example",
		HTTP: &http.Client{Transport: roundTripFunc(func(*http.Request) (*http.Response, error) {
			return nil, errors.New("connection reset by peer")
		})}}
	if _, err := c.Latest(); err == nil || !strings.Contains(err.Error(), "connection reset") {
		t.Errorf("err = %v", err)
	}
}

func TestLatestServerError(t *testing.T) {
	c := &VersionClient{BaseURL: "https://api.example",
		HTTP: &http.Client{Transport: roundTripFunc(func(*http.Request) (*http.Response, error) {
			return respond(503, "busy"), nil
		})}}
