package main

import (
	"encoding/json"
	"fmt"
	"net/http"
)

// VersionClient calls a release API. HTTP is injectable for tests.
type VersionClient struct {
	BaseURL string
	Token   string
	HTTP    *http.Client
}

func (c *VersionClient) Latest() (string, error) {
	req, err := http.NewRequest(http.MethodGet, c.BaseURL+"/latest", nil)
	if err != nil {
		return "", err
	}
	if c.Token != "" {
		req.Header.Set("Authorization", "Bearer "+c.Token)
	}
	resp, err := c.HTTP.Do(req)
	if err != nil {
		return "", fmt.Errorf("latest: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("latest: status %d", resp.StatusCode)
	}
	var out struct {
		Version string `json:"version"`
	}
	err = json.NewDecoder(resp.Body).Decode(&out)
	return out.Version, err
}

