)

func main() {
	tm := time.NewTimer(20 * time.Millisecond)
	stopped := tm.Stop()
	fmt.Println("stopped before firing:", stopped)

	fired := make(chan string, 1)
	time.AfterFunc(5*time.Millisecond, func() { fired <- "AfterFunc ran" })
	fmt.Println(<-fired)

	tk := time.NewTicker(5 * time.Millisecond)
	defer tk.Stop()
	ticks := 0
	for range tk.C {
		ticks++
		if ticks == 3 {
			break
		}
	}
	fmt.Println("ticks:", ticks)

	// One reusable idle timer instead of time.After in a loop.
	events := make(chan int)
	go func() {
		for i := range 3 {
			events <- i
		}
	}()
	idle := time.NewTimer(50 * time.Millisecond)
	defer idle.Stop()
	for handled := 0; ; {
		select {
		case ev := <-events:
			handled++
			fmt.Println("event", ev)
			idle.Reset(50 * time.Millisecond)
		case <-idle.C:
			fmt.Println("idle; handled", handled)
			return
		}
	}
}

