func main() {
	const w, h = 64, 32
	img := image.NewRGBA(image.Rect(0, 0, w, h))
	for y := range h {
		for x := range w {
			shade := uint8(x * 255 / (w - 1))
			img.Set(x, y, color.RGBA{R: shade, G: 0, B: 255 - shade, A: 255})
		}
	}
	for a := 0.0; a < 2*math.Pi; a += 0.01 {
		x := w/2 + int(10*math.Cos(a))
		y := h/2 + int(10*math.Sin(a))
		img.Set(x, y, color.White)
	}
	fmt.Println(img.Bounds(), img.At(0, 0), img.At(w-1, 0), img.At(w/2+10, h/2))

	var buf bytes.Buffer
	if err := png.Encode(&buf, img); err != nil {
		panic(err)
	}
	fmt.Printf("PNG signature: % x\n", buf.Bytes()[:8])

	decoded, format, err := image.Decode(&buf)
	fmt.Println(format, decoded.Bounds().Dx(), decoded.Bounds().Dy(), err)
}

