func run(args []string, out io.Writer) int {
	if len(args) < 1 {
		fmt.Fprintln(out, "usage: todo <add|list> [flags]")
		return 2
	}
	switch args[0] {
	case "add":
		fs := flag.NewFlagSet("add", flag.ContinueOnError)
		fs.SetOutput(out)
		prio := fs.Int("priority", 1, "priority 1-3")
		if err := fs.Parse(args[1:]); err != nil {
			return 2
		}
		fmt.Fprintf(out, "added %q with priority %d\n", strings.Join(fs.Args(), " "), *prio)
	case "list":
		fs := flag.NewFlagSet("list", flag.ContinueOnError)
		fs.SetOutput(out)
		done := fs.Bool("done", false, "show finished tasks")
		if err := fs.Parse(args[1:]); err != nil {
			return 2
		}
		fmt.Fprintf(out, "listing (done=%v)\n", *done)
	default:
		fmt.Fprintf(out, "unknown command %q\n", args[0])
		return 2
	}
	return 0
}

func main() {
	var sb strings.Builder
	for _, a := range [][]string{
		{"add", "-priority", "3", "buy", "milk"},
		{"list", "-done"},
		{"remove", "x"},
		{"add", "-priority", "high"},
	} {
