func createSnippet(w http.ResponseWriter, r *http.Request) {
	if err := r.ParseForm(); err != nil {
		http.Error(w, "bad form", http.StatusBadRequest)
		return
	}
	title := strings.TrimSpace(r.PostForm.Get("title"))
	expires := r.PostForm.Get("expires")
	errs := map[string]string{}
	if title == "" {
		errs["title"] = "cannot be blank"
	} else if utf8.RuneCountInString(title) > 20 {
		errs["title"] = "must be at most 20 characters"
	}
	if expires != "1" && expires != "7" && expires != "365" {
		errs["expires"] = "must be 1, 7 or 365"
	}
	if len(errs) > 0 {
		w.WriteHeader(http.StatusUnprocessableEntity)
		for _, f := range []string{"title", "expires"} {
			if e, ok := errs[f]; ok {
				fmt.Fprintf(w, "%s: %s; ", f, e)
			}
		}
		return
	}
	http.Redirect(w, r, "/snippet/1", http.StatusSeeOther) // PRG
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(createSnippet))
	defer srv.Close()
