import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
)

type User struct {
	Name  string
	Admin bool
}

type ctxKey int

const userKey ctxKey = 0

func withUser(ctx context.Context, u *User) context.Context {
	return context.WithValue(ctx, userKey, u)
}

func userFrom(ctx context.Context) (*User, bool) {
	u, ok := ctx.Value(userKey).(*User)
	return u, ok
}

var tokens = map[string]*User{"t-ada": {"ada", true}, "t-bob": {"bob", false}}

func authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if u, ok := tokens[r.Header.Get("Authorization")]; ok {
			r = r.WithContext(withUser(r.Context(), u))
		}
		next.ServeHTTP(w, r)
	})
}

func requireAdmin(next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		u, ok := userFrom(r.Context())
		switch {
		case !ok:
			http.Error(w, "log in first", http.StatusUnauthorized)
		case !u.Admin:
			http.Error(w, "admins only", http.StatusForbidden)
		default:
			next(w, r)
		}
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /admin", requireAdmin(func(w http.ResponseWriter, r *http.Request) {
		u, _ := userFrom(r.Context())
		fmt.Fprintf(w, "hello admin %s", u.Name)
	}))
	srv := httptest.NewServer(authenticate(mux))
	defer srv.Close()

	for _, tok := range []string{"t-ada", "t-bob", ""} {
		req, _ := http.NewRequest("GET", srv.URL+"/admin", nil)
		req.Header.Set("Authorization", tok)
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-6q %d %s", tok, resp.StatusCode, b)
		if resp.StatusCode == 200 {
			fmt.Println()
		}
	}
}

