import (
	"crypto/hmac"
	"crypto/sha256"
	"encoding/base64"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"strings"
)

var secretKey = []byte("demo-only-key-use-32-random-bytes")

func sign(value string) string {
	m := hmac.New(sha256.New, secretKey)
	m.Write([]byte(value))
	return value + "." + base64.RawURLEncoding.EncodeToString(m.Sum(nil))
}

func verify(cookie string) (string, error) {
	value, sig, ok := strings.Cut(cookie, ".")
	if !ok || !hmac.Equal([]byte(sign(value)), []byte(value+"."+sig)) {
		return "", errors.New("invalid signature")
	}
	return value, nil
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /login", func(w http.ResponseWriter, r *http.Request) {
		http.SetCookie(w, &http.Cookie{Name: "user", Value: sign("bob"), Path: "/",
			HttpOnly: true, SameSite: http.SameSiteLaxMode})
		fmt.Fprint(w, "logged in")
	})
	mux.HandleFunc("GET /me", func(w http.ResponseWriter, r *http.Request) {
		c, err := r.Cookie("user")
		if err != nil {
			http.Error(w, "no cookie", http.StatusUnauthorized)
			return
		}
		user, err := verify(c.Value)
		if err != nil {
			http.Error(w, err.Error(), http.StatusUnauthorized)
			return
		}
		fmt.Fprint(w, "you are "+user)
	})
	srv := httptest.NewServer(mux)
	defer srv.Close()

	jar, _ := cookiejar.New(nil)
	client := &http.Client{Jar: jar}
	show := func(req *http.Request) {
		resp, err := client.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Println(resp.StatusCode, strings.TrimSpace(string(b)))
	}
	get := func(p string) *http.Request { r, _ := http.NewRequest("GET", srv.URL+p, nil); return r }

	show(get("/me"))
	show(get("/login"))
	show(get("/me"))

	forged := get("/me")
	forged.Header.Set("Cookie", "user=admin."+strings.Split(sign("bob"), ".")[1])
	resp, _ := http.DefaultClient.Do(forged)
	b, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	fmt.Println(resp.StatusCode, strings.TrimSpace(string(b)))
}

