	Stars int    `json:"stars"`
}

var client = &http.Client{Timeout: 2 * time.Second}

func fetchRepo(ctx context.Context, url string) (Repo, error) {
	var r Repo
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return r, err
	}
	resp, err := client.Do(req)
	if err != nil {
		return r, fmt.Errorf("fetch: %w", err)
	}
	defer resp.Body.Close()
	if resp.StatusCode != http.StatusOK {
		return r, fmt.Errorf("fetch: unexpected status %s", resp.Status)
	}
	err = json.NewDecoder(io.LimitReader(resp.Body, 1<<20)).Decode(&r)
	return r, err
}

func main() {
	api := http.NewServeMux()
	api.HandleFunc("GET /repos/go", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, `{"name":"go","stars":130000}`)
	})
	api.HandleFunc("GET /slow", func(w http.ResponseWriter, r *http.Request) {
		select {
		case <-time.After(time.Second):
		case <-r.Context().Done():
		}
	})
	srv := httptest.NewServer(api)
	defer srv.Close()

	fmt.Println(fetchRepo(context.Background(), srv.URL+"/repos/go"))
	_, err := fetchRepo(context.Background(), srv.URL+"/repos/missing")
	fmt.Println(err)

	ctx, cancel := context.WithTimeout(context.Background(), 50*time.Millisecond)
	defer cancel()
	_, err = fetchRepo(ctx, srv.URL+"/slow")
	fmt.Println(errors.Is(err, context.DeadlineExceeded))
}

