	"crypto/subtle"
	"fmt"
	"io"
	"net/http"
	"net/http/cookiejar"
	"net/http/httptest"
	"net/url"
	"strings"
	"sync"
)

type user struct{ salt, hash []byte }

type app struct {
	mu       sync.Mutex
	users    map[string]user   // email -> credentials
	sessions map[string]string // token -> email
}

func hashPw(pw string, salt []byte) []byte {
	h, _ := pbkdf2.Key(sha256.New, pw, salt, 100_000, 32)
	return h
}

func (a *app) signup(w http.ResponseWriter, r *http.Request) {
	email, pw := r.PostFormValue("email"), r.PostFormValue("password")
	if !strings.Contains(email, "@") || len(pw) < 8 {
		http.Error(w, "invalid email or password too short", http.StatusUnprocessableEntity)
		return
	}
	salt := make([]byte, 16)
	rand.Read(salt)
	a.mu.Lock()
	a.users[email] = user{salt, hashPw(pw, salt)}
	a.mu.Unlock()
	fmt.Fprint(w, "account created")
}

func (a *app) login(w http.ResponseWriter, r *http.Request) {
	email, pw := r.PostFormValue("email"), r.PostFormValue("password")
	a.mu.Lock()
	u, ok := a.users[email]
	a.mu.Unlock()
	if !ok || subtle.ConstantTimeCompare(hashPw(pw, u.salt), u.hash) != 1 {
		http.Error(w, "invalid credentials", http.StatusUnauthorized) // same message for both
		return
	}
	token := rand.Text()
	a.mu.Lock()
	a.sessions[token] = email
	a.mu.Unlock()
	http.SetCookie(w, &http.Cookie{Name: "session", Value: token, Path: "/",
		HttpOnly: true, SameSite: http.SameSiteLaxMode, MaxAge: 3600})
	fmt.Fprint(w, "logged in")
}

func (a *app) currentUser(r *http.Request) (string, bool) {
	c, err := r.Cookie("session")
	if err != nil {
		return "", false
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	email, ok := a.sessions[c.Value]
	return email, ok
}

func (a *app) account(w http.ResponseWriter, r *http.Request) {
	email, ok := a.currentUser(r)
	if !ok {
		http.Error(w, "please log in", http.StatusUnauthorized)
		return
	}
	fmt.Fprint(w, "welcome back, "+email)
}

func (a *app) logout(w http.ResponseWriter, r *http.Request) {
	if c, err := r.Cookie("session"); err == nil {
		a.mu.Lock()
		delete(a.sessions, c.Value)
		a.mu.Unlock()
	}
	http.SetCookie(w, &http.Cookie{Name: "session", Value: "", Path: "/", MaxAge: -1})
	fmt.Fprint(w, "logged out")
}

func main() {
	a := &app{users: map[string]user{}, sessions: map[string]string{}}
	mux := http.NewServeMux()
	mux.HandleFunc("POST /signup", a.signup)
	mux.HandleFunc("POST /login", a.login)
	mux.HandleFunc("GET /account", a.account)
	mux.HandleFunc("POST /logout", a.logout)
	srv := httptest.NewServer(mux)
	defer srv.Close()

	jar, _ := cookiejar.New(nil)
	c := &http.Client{Jar: jar}
	do := func(method, path string, form url.Values) {
		var resp *http.Response
		var err error
		if method == "POST" {
			resp, err = c.PostForm(srv.URL+path, form)
		} else {
			resp, err = c.Get(srv.URL + path)
		}
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-4s %-8s %d %s\n", method, path, resp.StatusCode, strings.TrimSpace(string(b)))
	}
	creds := url.Values{"email": {"ada@example.com"}, "password": {"correct horse"}}
	do("POST", "/signup", url.Values{"email": {"bob"}, "password": {"short"}})
	do("POST", "/signup", creds)
	do("GET", "/account", nil)
	do("POST", "/login", url.Values{"email": {"ada@example.com"}, "password": {"wrong password"}})
	do("POST", "/login", creds)
	do("GET", "/account", nil)
	do("POST", "/logout", nil)
	do("GET", "/account", nil)
}

package main

import (
	"crypto/rand"
	"crypto/subtle"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
)

func csrfProtect(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		switch r.Method {
		case http.MethodGet, http.MethodHead, http.MethodOptions:
			if _, err := r.Cookie("csrf"); err != nil {
				http.SetCookie(w, &http.Cookie{Name: "csrf", Value: rand.Text(), Path: "/",
					HttpOnly: true, SameSite: http.SameSiteLaxMode})
			}
			next.ServeHTTP(w, r)
			return
		}
		if r.Header.Get("Sec-Fetch-Site") == "cross-site" {
			http.Error(w, "cross-site request blocked", http.StatusForbidden)
			return
		}
		c, err := r.Cookie("csrf")
		token := r.Header.Get("X-CSRF-Token")
		if err != nil || subtle.ConstantTimeCompare([]byte(c.Value), []byte(token)) != 1 {
			http.Error(w, "missing or bad CSRF token", http.StatusForbidden)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /form", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "form") })
	mux.HandleFunc("POST /transfer", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "transferred") })
	srv := httptest.NewServer(csrfProtect(mux))
	defer srv.Close()

	resp, _ := http.Get(srv.URL + "/form")
	resp.Body.Close()
	token := resp.Cookies()[0].Value

	send := func(label, tok, fetchSite string) {
		req, _ := http.NewRequest("POST", srv.URL+"/transfer", nil)
		req.AddCookie(&http.Cookie{Name: "csrf", Value: token}) // the browser always attaches it
		if tok != "" {
			req.Header.Set("X-CSRF-Token", tok)
		}
		if fetchSite != "" {
			req.Header.Set("Sec-Fetch-Site", fetchSite)
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-24s %d %s\n", label, resp.StatusCode, strings.TrimSpace(string(b)))
	}
	send("our form, with token", token, "same-origin")
	send("forged, no token", "", "")
	send("forged, guessed token", "AAAA", "")
	send("cross-site page", token, "cross-site")
}

package main

import (
	"bytes"
	"fmt"
	"html/template"
	"io/fs"
	"os"
	"path"
	"testing/fstest"
	"time"
)

var files = fstest.MapFS{
	"base.tmpl":         {Data: []byte(`{{define "base"}}<title>{{template "title" .}}</title>{{template "nav" .}}<main>{{template "main" .}}</main>{{end}}`)},
	"partials/nav.tmpl": {Data: []byte(`{{define "nav"}}<nav>Home | About</nav>{{end}}`)},
	"pages/home.tmpl":   {Data: []byte(`{{define "title"}}Home{{end}}{{define "main"}}Latest: {{.Title}} on {{humanDate .When}}{{end}}`)},
	"pages/about.tmpl":  {Data: []byte(`{{define "title"}}About{{end}}{{define "main"}}{{len .Authors}} {{plural (len .Authors) "author" "authors"}}{{end}}`)},
}

var functions = template.FuncMap{
	"humanDate": func(t time.Time) string { return t.Format("02 Jan 2006 at 15:04") },
	"plural": func(n int, one, many string) string {
		if n == 1 {
			return one
		}
		return many
	},
}

func newTemplateCache(fsys fs.FS) (map[string]*template.Template, error) {
	cache := map[string]*template.Template{}
	pages, err := fs.Glob(fsys, "pages/*.tmpl")
	if err != nil {
		return nil, err
	}
	for _, page := range pages {
		ts, err := template.New("base").Funcs(functions).ParseFS(fsys, "base.tmpl", "partials/*.tmpl", page)
		if err != nil {
			return nil, fmt.Errorf("parse %s: %w", page, err)
		}
		cache[path.Base(page)] = ts
	}
	return cache, nil
}

func render(cache map[string]*template.Template, page string, data any) error {
	ts, ok := cache[page]
	if !ok {
		return fmt.Errorf("template %s does not exist", page)
	}
	var buf bytes.Buffer
	if err := ts.ExecuteTemplate(&buf, "base", data); err != nil {
		return err // nothing half-written reaches the client
	}
	buf.WriteString("\n")
	_, err := buf.WriteTo(os.Stdout)
	return err
}

func main() {
	cache, err := newTemplateCache(files)
	if err != nil {
		fmt.Println(err)
		return
	}
	fmt.Println(len(cache), "pages cached")
	when := time.Date(2026, 11, 3, 14, 30, 0, 0, time.UTC)
	render(cache, "home.tmpl", map[string]any{"Title": "Go 1.26 released", "When": when})
	render(cache, "about.tmpl", map[string]any{"Authors": []string{"ada"}})
	fmt.Println(render(cache, "missing.tmpl", nil))
}

package main

import (
	"bufio"
	"errors"
	"fmt"
	"net"
	"strings"
)

func handle(conn net.Conn) {
	defer conn.Close()
	sc := bufio.NewScanner(conn)
	for sc.Scan() {
		line := sc.Text()
		if line == "quit" {
			fmt.Fprintln(conn, "bye")
			return
		}
		fmt.Fprintln(conn, strings.ToUpper(line))
	}
}

func main() {
	ln, err := net.Listen("tcp", "127.0.0.1:0") // port 0: pick a free one
	if err != nil {
		panic(err)
	}
	stopped := make(chan error)
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				stopped <- err
				return
			}
			go handle(conn)
		}
	}()

	conn, err := net.Dial("tcp", ln.Addr().String())
	if err != nil {
		panic(err)
	}
	defer conn.Close()
	r := bufio.NewReader(conn)
	for _, msg := range []string{"hello", "gophers", "quit"} {
		fmt.Fprintln(conn, msg)
		reply, _ := r.ReadString('\n')
		fmt.Printf("sent %-8q got %q\n", msg, reply)
	}
	ln.Close()
	fmt.Println("accept loop ended:", errors.Is(<-stopped, net.ErrClosed))
}

package main

import (
	"bufio"
	"fmt"
	"net"
	"strings"
)

type client chan<- string

var (
	entering = make(chan client)
	leaving  = make(chan client)
	messages = make(chan string)
)

func broadcaster() {
	clients := map[client]bool{}
	for {
		select {
		case msg := <-messages:
			for cli := range clients {
				cli <- msg
			}
		case cli := <-entering:
			clients[cli] = true
		case cli := <-leaving:
			delete(clients, cli)
			close(cli)
		}
	}
}

func handleConn(conn net.Conn) {
	out := make(chan string, 8)
	go func() {
		for msg := range out {
			fmt.Fprintln(conn, msg)
		}
	}()
	sc := bufio.NewScanner(conn)
	sc.Scan()
	who := sc.Text()
	entering <- out
	messages <- who + " joined"
	for sc.Scan() {
		messages <- who + ": " + sc.Text()
	}
	leaving <- out
	messages <- who + " left"
	conn.Close()
}

// user is one chat client; read waits for the next line it receives.
type user struct {
	conn   net.Conn
	in     *bufio.Scanner
	screen []string
}

func join(addr, name string) *user {
	c, err := net.Dial("tcp", addr)
	if err != nil {
		panic(err)
	}
	u := &user{conn: c, in: bufio.NewScanner(c)}
	fmt.Fprintln(c, name)
	u.read() // our own "joined" line: we're registered now
	return u
}

func (u *user) say(msg string) { fmt.Fprintln(u.conn, msg) }
func (u *user) read() {
	u.in.Scan()
	u.screen = append(u.screen, u.in.Text())
}

func main() {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	go broadcaster()
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go handleConn(conn)
		}
	}()
	addr := ln.Addr().String()

	ada := join(addr, "ada")
	bob := join(addr, "bob")
	ada.read() // bob joined
	bob.say("hi ada!")
	bob.read()
	ada.read()
	ada.say("hello bob")
	ada.read()
	bob.read()
	bob.conn.Close()
	ada.read() // bob left
	ada.conn.Close()

	fmt.Println("ada's screen:\n  " + strings.Join(ada.screen, "\n  "))
	fmt.Println("bob's screen:\n  " + strings.Join(bob.screen, "\n  "))
}

