import (
	"fmt"
	"net"
	"net/netip"
	"strings"
	"time"
)

func main() {
	pc, err := net.ListenPacket("udp", "127.0.0.1:0")
	if err != nil {
		panic(err)
	}
	defer pc.Close()
	go func() {
		buf := make([]byte, 1500)
		for {
			n, addr, err := pc.ReadFrom(buf)
			if err != nil {
				return
			}
			pc.WriteTo([]byte(strings.Repeat(string(buf[:n]), 2)), addr)
		}
	}()

	conn, err := net.Dial("udp", pc.LocalAddr().String())
	if err != nil {
		panic(err)
	}
	defer conn.Close()
	buf := make([]byte, 1500)
	for _, msg := range []string{"ping", "go!"} {
		conn.Write([]byte(msg))
		conn.SetReadDeadline(time.Now().Add(time.Second))
		n, err := conn.Read(buf)
		fmt.Printf("%s -> %s %v\n", msg, buf[:n], err)
	}

	ap := netip.MustParseAddrPort(pc.LocalAddr().String())
	seen := map[netip.Addr]int{ap.Addr(): 1}
	fmt.Println(ap.Addr(), ap.Addr().IsLoopback(), seen[netip.MustParseAddr("127.0.0.1")])
}

package main

import (
	"bufio"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"net"
)

const maxFrame = 1 << 16

var ErrTooLarge = errors.New("frame too large")

func writeFrame(w *bufio.Writer, payload []byte) error {
	var hdr [4]byte
	binary.BigEndian.PutUint32(hdr[:], uint32(len(payload)))
	w.Write(hdr[:])
	w.Write(payload)
	return w.Flush()
}

func readFrame(r io.Reader) ([]byte, error) {
	var hdr [4]byte
	if _, err := io.ReadFull(r, hdr[:]); err != nil {
		return nil, err
	}
	n := binary.BigEndian.Uint32(hdr[:])
	if n > maxFrame {
		return nil, fmt.Errorf("%w: %d bytes", ErrTooLarge, n)
	}
	buf := make([]byte, n)
	_, err := io.ReadFull(r, buf)
	return buf, err
}

func main() {
	client, server := net.Pipe()
	go func() {
		w := bufio.NewWriter(client)
		for _, msg := range []string{"hello", "binary\x00safe\npayload", ""} {
			writeFrame(w, []byte(msg))
		}
		var evil [4]byte
		binary.BigEndian.PutUint32(evil[:], 1<<31) // a lying length header
		client.Write(evil[:])
		client.Close()
	}()
	for {
		msg, err := readFrame(server)
		if err != nil {
			fmt.Println("stop:", err)
			return
		}
		fmt.Printf("frame %d bytes: %q\n", len(msg), msg)
	}
}

package main

import (
	"bufio"
	"fmt"
	"net/http"
	"net/http/httptest"
	"strings"
	"time"
)

func events(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	rc := http.NewResponseController(w)
	for i := 1; i <= 3; i++ {
		select {
		case <-r.Context().Done():
			return // the client went away
		case <-time.After(10 * time.Millisecond):
		}
		fmt.Fprintf(w, "event: progress\ndata: step %d of 3\n\n", i)
		rc.Flush() // send it now, not at the end
	}
}

func main() {
	srv := httptest.NewServer(http.HandlerFunc(events))
	defer srv.Close()

	resp, err := http.Get(srv.URL)
	if err != nil {
		panic(err)
	}
	defer resp.Body.Close()
	fmt.Println(resp.Header.Get("Content-Type"))
	sc := bufio.NewScanner(resp.Body)
	for sc.Scan() {
		if data, ok := strings.CutPrefix(sc.Text(), "data: "); ok {
			fmt.Println("received:", data)
		}
	}
}

