package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
)

var ErrInsufficient = errors.New("insufficient funds")

func balance(db *sql.DB, name string) int {
	var b int
	db.QueryRow("SELECT balance FROM accounts WHERE name = ?", name).Scan(&b)
	return b
}

func transfer(ctx context.Context, db *sql.DB, from, to string, amount int) error {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return err
	}
	defer tx.Rollback() // harmless after Commit

	var fromBal int
	if err := tx.QueryRowContext(ctx, "SELECT balance FROM accounts WHERE name = ?", from).Scan(&fromBal); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, "UPDATE accounts SET balance = ? WHERE name = ?", fromBal-amount, from); err != nil {
		return err
	}
	if fromBal < amount { // checked late on purpose: the debit must be undone
		return ErrInsufficient
	}
	var toBal int
	if err := tx.QueryRowContext(ctx, "SELECT balance FROM accounts WHERE name = ?", to).Scan(&toBal); err != nil {
		return err
	}
	if _, err := tx.ExecContext(ctx, "UPDATE accounts SET balance = ? WHERE name = ?", toBal+amount, to); err != nil {
		return err
	}
	return tx.Commit()
}

func main() {
	db, _ := sql.Open("memdb", "bank")
	defer db.Close()
	db.SetMaxOpenConns(1)
	db.Exec("CREATE TABLE accounts (id, name, balance)")
	db.Exec("INSERT INTO accounts (name, balance) VALUES (?, ?)", "ada", 100)
	db.Exec("INSERT INTO accounts (name, balance) VALUES (?, ?)", "bob", 20)
	ctx := context.Background()

	fmt.Println(transfer(ctx, db, "ada", "bob", 30), balance(db, "ada"), balance(db, "bob"))
	fmt.Println(transfer(ctx, db, "bob", "ada", 500), balance(db, "ada"), balance(db, "bob"))
	err := transfer(ctx, db, "ada", "zoe", 10)
	fmt.Println(errors.Is(err, sql.ErrNoRows), balance(db, "ada"))
}

