package main

// memdb: a tiny in-memory SQL driver for the course, so database/sql
// lessons run offline with no server. It understands a small subset:
//   CREATE TABLE t (c1, c2, ...)          -- a column named id auto-increments
//   INSERT INTO t (c1, c2) VALUES (?, ?)
//   SELECT * | c1, c2 | COUNT(*) FROM t [WHERE a = b [OR c = d ...]] [ORDER BY c [DESC]]
//   UPDATE t SET c1 = ?, c2 = ? [WHERE ...]
//   DELETE FROM t [WHERE ...]
// Values may be ?, 'text' or numbers. A real database does far more.

import (
	"database/sql"
	"database/sql/driver"
	"errors"
	"fmt"
	"io"
	"sort"
	"strconv"
	"strings"
	"sync"
	"unicode"
)

func init() { sql.Register("memdb", &memDriver{dbs: map[string]*memStore{}}) }

type memDriver struct {
	mu  sync.Mutex
	dbs map[string]*memStore
}

type memTable struct {
	cols   []string
	rows   [][]driver.Value
	nextID int64
}

type memStore struct {
	mu     sync.Mutex
	tables map[string]*memTable
}

func (s *memStore) snapshot() map[string]*memTable {
	cp := map[string]*memTable{}
	for n, t := range s.tables {
		nt := &memTable{cols: t.cols, nextID: t.nextID}
		for _, r := range t.rows {
			nt.rows = append(nt.rows, append([]driver.Value(nil), r...))
		}
		cp[n] = nt
	}
	return cp
}

func (d *memDriver) Open(name string) (driver.Conn, error) {
	d.mu.Lock()
	defer d.mu.Unlock()
	s, ok := d.dbs[name]
	if !ok {
		s = &memStore{tables: map[string]*memTable{}}
		d.dbs[name] = s
	}
	return &memConn{s: s}, nil
}

type memConn struct {
	s    *memStore
	save map[string]*memTable
}

func (c *memConn) Prepare(q string) (driver.Stmt, error) { return &memStmt{c: c, q: q}, nil }
func (c *memConn) Close() error                          { return nil }
func (c *memConn) Begin() (driver.Tx, error) {
	c.s.mu.Lock()
	c.save = c.s.snapshot()
	c.s.mu.Unlock()
	return c, nil
}
func (c *memConn) Commit() error { c.save = nil; return nil }
func (c *memConn) Rollback() error {
	c.s.mu.Lock()
	if c.save != nil {
		c.s.tables = c.save
	}
	c.save = nil
	c.s.mu.Unlock()
	return nil
}

type memStmt struct {
	c *memConn
	q string
}

func (s *memStmt) Close() error  { return nil }
func (s *memStmt) NumInput() int { return -1 }

type memResult struct{ id, n int64 }

func (r memResult) LastInsertId() (int64, error) { return r.id, nil }
func (r memResult) RowsAffected() (int64, error) { return r.n, nil }

func (s *memStmt) Exec(args []driver.Value) (driver.Result, error) {
	res, _, err := s.run(args)
	return res, err
}

func (s *memStmt) Query(args []driver.Value) (driver.Rows, error) {
	_, rows, err := s.run(args)
	if rows == nil && err == nil {
		rows = &memRows{}
	}
	return rows, err
}

// ---- tokenizer ----
type tok struct {
	kind byte // 'w' word, 'n' number, 's' string, 'p' punctuation
	v    string
}

func lex(q string) ([]tok, error) {
	var out []tok
	r := []rune(q)
	for i := 0; i < len(r); {
		ch := r[i]
		switch {
		case unicode.IsSpace(ch):
			i++
		case ch == '\'':
			var b strings.Builder
			i++
			for {
				if i >= len(r) {
					return nil, errors.New("memdb: unterminated string")
				}
				if r[i] == '\'' {
					if i+1 < len(r) && r[i+1] == '\'' {
						b.WriteRune('\'')
						i += 2
						continue
					}
					i++
					break
				}
				b.WriteRune(r[i])
				i++
			}
			out = append(out, tok{'s', b.String()})
		case unicode.IsDigit(ch) || (ch == '-' && i+1 < len(r) && unicode.IsDigit(r[i+1])):
			j := i + 1
			for j < len(r) && (unicode.IsDigit(r[j]) || r[j] == '.') {
				j++
			}
			out = append(out, tok{'n', string(r[i:j])})
			i = j
		case unicode.IsLetter(ch) || ch == '_':
			j := i
			for j < len(r) && (unicode.IsLetter(r[j]) || unicode.IsDigit(r[j]) || r[j] == '_') {
				j++
			}
			out = append(out, tok{'w', string(r[i:j])})
			i = j
		default:
			out = append(out, tok{'p', string(ch)})
			i++
		}
	}
	return out, nil
}

type parser struct {
	t    []tok
	i    int
	args []driver.Value
	ai   int
}

func (p *parser) peek() tok {
	if p.i < len(p.t) {
		return p.t[p.i]
	}
	return tok{}
}
func (p *parser) next() tok { t := p.peek(); p.i++; return t }
func (p *parser) isKw(k string) bool {
	t := p.peek()
	return t.kind == 'w' && strings.EqualFold(t.v, k)
}
func (p *parser) expect(v string) error {
	t := p.next()
	if !strings.EqualFold(t.v, v) {
		return fmt.Errorf("memdb: syntax error: expected %q, got %q", v, t.v)
	}
	return nil
}

// operand: ('c', name) for a column, ('v', value) for a literal/placeholder.
type operand struct {
	col string
	val driver.Value
	lit bool
}

func (p *parser) operand() (operand, error) {
	t := p.next()
	switch {
	case t.kind == 'p' && t.v == "?":
		if p.ai >= len(p.args) {
			return operand{}, errors.New("memdb: not enough arguments for placeholders")
		}
		v := p.args[p.ai]
		p.ai++
		return operand{val: v, lit: true}, nil
	case t.kind == 's':
		return operand{val: t.v, lit: true}, nil
	case t.kind == 'n':
		if strings.Contains(t.v, ".") {
			f, _ := strconv.ParseFloat(t.v, 64)
			return operand{val: f, lit: true}, nil
		}
		n, _ := strconv.ParseInt(t.v, 10, 64)
		return operand{val: n, lit: true}, nil
	case t.kind == 'w' && strings.EqualFold(t.v, "NULL"):
		return operand{val: nil, lit: true}, nil
	case t.kind == 'w':
		return operand{col: t.v}, nil
	}
	return operand{}, fmt.Errorf("memdb: syntax error near %q", t.v)
}

func norm(v driver.Value) string {
	switch x := v.(type) {
	case nil:
		return "\x00NULL"
	case []byte:
		return string(x)
	case float64:
		if x == float64(int64(x)) {
			return strconv.FormatInt(int64(x), 10)
		}
	}
	return fmt.Sprint(v)
}

type cond [][2]operand // OR of equalities

func (p *parser) where() (cond, error) {
	if !p.isKw("WHERE") {
		return nil, nil
	}
	p.next()
	var c cond
	for {
		a, err := p.operand()
		if err != nil {
			return nil, err
		}
		if err := p.expect("="); err != nil {
			return nil, err
		}
		b, err := p.operand()
		if err != nil {
			return nil, err
		}
		c = append(c, [2]operand{a, b})
		if !p.isKw("OR") {
			return c, nil
		}
		p.next()
	}
}

func colIndex(t *memTable, name string) (int, error) {
	for i, c := range t.cols {
		if strings.EqualFold(c, name) {
			return i, nil
		}
	}
	return 0, fmt.Errorf("memdb: no such column: %s", name)
}

func (c cond) match(t *memTable, row []driver.Value) (bool, error) {
	if c == nil {
		return true, nil
	}
	val := func(o operand) (driver.Value, error) {
		if o.lit {
			return o.val, nil
		}
		i, err := colIndex(t, o.col)
		if err != nil {
			return nil, err
		}
		return row[i], nil
	}
	for _, eq := range c {
		a, err := val(eq[0])
		if err != nil {
			return false, err
		}
		b, err := val(eq[1])
		if err != nil {
			return false, err
		}
		if a != nil && b != nil && norm(a) == norm(b) {
			return true, nil
		}
	}
	return false, nil
}

func (s *memStmt) table(name string) (*memTable, error) {
	t, ok := s.c.s.tables[strings.ToLower(name)]
	if !ok {
		return nil, fmt.Errorf("memdb: no such table: %s", name)
	}
	return t, nil
}

func (s *memStmt) run(args []driver.Value) (driver.Result, driver.Rows, error) {
	toks, err := lex(s.q)
	if err != nil {
		return nil, nil, err
	}
	p := &parser{t: toks, args: args}
	st := s.c.s
	st.mu.Lock()
	defer st.mu.Unlock()
	switch kw := strings.ToUpper(p.next().v); kw {
	case "CREATE":
		if err := p.expect("TABLE"); err != nil {
			return nil, nil, err
		}
		name := strings.ToLower(p.next().v)
		if _, dup := st.tables[name]; dup {
			return nil, nil, fmt.Errorf("memdb: table %s already exists", name)
		}
		var cols []string
		if err := p.expect("("); err != nil {
			return nil, nil, err
		}
		for {
			t := p.next()
			if t.v == ")" || t.v == "" {
				break
			}
			if t.kind == 'w' && (len(cols) == 0 || p.t[p.i-2].v == "," || p.t[p.i-2].v == "(") {
				cols = append(cols, t.v)
			}
		}
		st.tables[name] = &memTable{cols: cols, nextID: 1}
		return memResult{}, nil, nil
	case "INSERT":
		if err := p.expect("INTO"); err != nil {
			return nil, nil, err
		}
		t, err := s.table(p.next().v)
		if err != nil {
			return nil, nil, err
		}
		var names []string
		if err := p.expect("("); err != nil {
			return nil, nil, err
		}
		for tk := p.next(); tk.v != ")"; tk = p.next() {
			if tk.v == "" {
				return nil, nil, errors.New("memdb: syntax error in INSERT")
			}
			if tk.kind == 'w' {
				names = append(names, tk.v)
			}
		}
		if err := p.expect("VALUES"); err != nil {
			return nil, nil, err
		}
		if err := p.expect("("); err != nil {
			return nil, nil, err
		}
		row := make([]driver.Value, len(t.cols))
		set := map[int]bool{}
		for k := range names {
			o, err := p.operand()
			if err != nil {
				return nil, nil, err
			}
			ci, err := colIndex(t, names[k])
			if err != nil {
				return nil, nil, err
			}
			row[ci], set[ci] = o.val, true
			if p.peek().v == "," {
				p.next()
			}
		}
		var id int64
		if ci, err := colIndex(t, "id"); err == nil {
			if !set[ci] {
				row[ci] = t.nextID
			}
			if n, ok := row[ci].(int64); ok {
				id = n
				if n >= t.nextID {
					t.nextID = n + 1
				}
			}
			for _, r := range t.rows {
				if norm(r[ci]) == norm(row[ci]) {
					return nil, nil, fmt.Errorf("memdb: UNIQUE constraint failed: %s.id", strings.ToLower(names[0]))
				}
			}
		}
		t.rows = append(t.rows, row)
		return memResult{id: id, n: 1}, nil, nil
	case "SELECT":
		var sel []string
		count := false
		for !p.isKw("FROM") {
			tk := p.next()
			switch {
			case tk.v == "":
				return nil, nil, errors.New("memdb: SELECT without FROM")
			case tk.kind == 'w' && strings.EqualFold(tk.v, "COUNT"):
				count = true
			case tk.v == "*" && !count:
				sel = append(sel, "*")
			case tk.kind == 'w':
				sel = append(sel, tk.v)
			}
		}
		p.next()
		t, err := s.table(p.next().v)
		if err != nil {
			return nil, nil, err
		}
		c, err := p.where()
		if err != nil {
			return nil, nil, err
		}
		var out [][]driver.Value
		for _, r := range t.rows {
			ok, err := c.match(t, r)
			if err != nil {
				return nil, nil, err
			}
			if ok {
				out = append(out, r)
			}
		}
		if p.isKw("ORDER") {
			p.next()
			if err := p.expect("BY"); err != nil {
				return nil, nil, err
			}
			ci, err := colIndex(t, p.next().v)
			if err != nil {
				return nil, nil, err
			}
			desc := p.isKw("DESC")
			sort.SliceStable(out, func(i, j int) bool {
				a, b := out[i][ci], out[j][ci]
				less := false
				if x, ok := a.(int64); ok {
					if y, ok := b.(int64); ok {
						less = x < y
					}
				} else {
					less = norm(a) < norm(b)
				}
				if desc {
					return !less && norm(a) != norm(b)
				}
				return less
			})
		}
		if count {
			return nil, &memRows{cols: []string{"count"}, data: [][]driver.Value{{int64(len(out))}}}, nil
		}
		var idx []int
		var cols []string
		for _, name := range sel {
			if name == "*" {
				for i, cn := range t.cols {
					idx, cols = append(idx, i), append(cols, cn)
				}
				continue
			}
			ci, err := colIndex(t, name)
			if err != nil {
				return nil, nil, err
			}
			idx, cols = append(idx, ci), append(cols, name)
		}
		rows := &memRows{cols: cols}
		for _, r := range out {
			vals := make([]driver.Value, len(idx))
			for k, ci := range idx {
				vals[k] = r[ci]
			}
			rows.data = append(rows.data, vals)
		}
		return nil, rows, nil
	case "UPDATE":
		t, err := s.table(p.next().v)
		if err != nil {
			return nil, nil, err
		}
		if err := p.expect("SET"); err != nil {
			return nil, nil, err
		}
		type asg struct {
			ci int
			v  driver.Value
		}
		var sets []asg
		for {
			ci, err := colIndex(t, p.next().v)
			if err != nil {
				return nil, nil, err
			}
			if err := p.expect("="); err != nil {
				return nil, nil, err
			}
			o, err := p.operand()
			if err != nil {
				return nil, nil, err
			}
			sets = append(sets, asg{ci, o.val})
			if p.peek().v != "," {
				break
			}
			p.next()
		}
		c, err := p.where()
		if err != nil {
			return nil, nil, err
		}
		var n int64
		for _, r := range t.rows {
			ok, err := c.match(t, r)
			if err != nil {
				return nil, nil, err
			}
			if ok {
				for _, a := range sets {
					r[a.ci] = a.v
				}
				n++
			}
		}
		return memResult{n: n}, nil, nil
	case "DELETE":
		if err := p.expect("FROM"); err != nil {
			return nil, nil, err
		}
		t, err := s.table(p.next().v)
		if err != nil {
			return nil, nil, err
		}
		c, err := p.where()
		if err != nil {
			return nil, nil, err
		}
		var keep [][]driver.Value
		var n int64
		for _, r := range t.rows {
			ok, err := c.match(t, r)
			if err != nil {
				return nil, nil, err
			}
			if ok {
				n++
			} else {
				keep = append(keep, r)
			}
		}
		t.rows = keep
		return memResult{n: n}, nil, nil
	default:
		return nil, nil, fmt.Errorf("memdb: unsupported statement %q", kw)
	}
}

type memRows struct {
	cols []string
	data [][]driver.Value
	i    int
}

func (r *memRows) Columns() []string { return r.cols }
func (r *memRows) Close() error      { return nil }
func (r *memRows) Next(dest []driver.Value) error {
	if r.i >= len(r.data) {
		return io.EOF
	}
	copy(dest, r.data[r.i])
	r.i++
	return nil
}

