package main

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
)

type User struct {
	ID    int
	Name  string
	Email sql.Null[string]
}

type UserModel struct{ DB *sql.DB }

func (m *UserModel) Insert(ctx context.Context, name string, email *string) (int, error) {
	var e any // nil -> NULL
	if email != nil {
		e = *email
	}
	res, err := m.DB.ExecContext(ctx, "INSERT INTO users (name, email) VALUES (?, ?)", name, e)
	if err != nil {
		return 0, err
	}
	id, err := res.LastInsertId()
	return int(id), err
}

func (m *UserModel) Get(ctx context.Context, id int) (User, error) {
	u := User{}
	err := m.DB.QueryRowContext(ctx, "SELECT id, name, email FROM users WHERE id = ?", id).
		Scan(&u.ID, &u.Name, &u.Email)
	return u, err
}

func main() {
	db, _ := sql.Open("memdb", "models")
	defer db.Close()
	db.Exec("CREATE TABLE users (id, name, email)")
	users := &UserModel{DB: db}
	ctx := context.Background()

	addr := "ada@example.com"
	a, _ := users.Insert(ctx, "ada", &addr)
	b, _ := users.Insert(ctx, "bob", nil)
	for _, id := range []int{a, b} {
		u, err := users.Get(ctx, id)
		if u.Email.Valid {
			fmt.Println(u.Name, "email:", u.Email.V, err)
		} else {
			fmt.Println(u.Name, "has no email", err)
		}
	}

	var plain string
	err := db.QueryRow("SELECT email FROM users WHERE id = ?", b).Scan(&plain)
	fmt.Println(err != nil, errors.Is(err, sql.ErrNoRows))
}

