package main

import (
	"context"
	"database/sql"
	"fmt"
)

type Event struct {
	Kind string
	Ms   int
}

func importEvents(ctx context.Context, db *sql.DB, events []Event) (int, error) {
	tx, err := db.BeginTx(ctx, nil)
	if err != nil {
		return 0, err
	}
	defer tx.Rollback()
	stmt, err := tx.PrepareContext(ctx, "INSERT INTO events (kind, ms) VALUES (?, ?)")
	if err != nil {
		return 0, err
	}
	defer stmt.Close()
	n := 0
	for _, e := range events {
		if _, err := stmt.ExecContext(ctx, e.Kind, e.Ms); err != nil {
			return 0, fmt.Errorf("event %d: %w", n, err)
		}
		n++
	}
	return n, tx.Commit()
}

func main() {
	db, _ := sql.Open("memdb", "prepared")
	defer db.Close()
	db.Exec("CREATE TABLE events (id, kind, ms)")
	ctx := context.Background()

	events := []Event{{"click", 12}, {"view", 40}, {"click", 9}, {"buy", 300}}
	fmt.Println(importEvents(ctx, db, events))

	count, _ := db.Prepare("SELECT COUNT(*) FROM events WHERE kind = ?")
	defer count.Close()
	for _, k := range []string{"click", "view", "refund"} {
		var n int
		count.QueryRowContext(ctx, k).Scan(&n)
		fmt.Println(k, n)
	}
}

