package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

type Config struct{ Name string }

func main() {
	// 1. Publish through a channel: the send happens-before the receive.
	var data string
	done := make(chan struct{})
	go func() {
		data = "written before close"
		close(done)
	}()
	<-done
	fmt.Println(data)

	// 2. Publish through an atomic pointer: Store happens-before a Load
	//    that observes it.
	var cfg atomic.Pointer[Config]
	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		cfg.Store(&Config{Name: "v2"})
	}()
	wg.Wait() // Done happens-before Wait returns
	fmt.Println(cfg.Load().Name)

	// 3. A race CONDITION with no data race: check-then-act on a locked
	//    counter still oversells, because check and act are separate.
	var mu sync.Mutex
	stock, sold := 1, 0
	var buyers sync.WaitGroup
	start := make(chan struct{})
	for range 2 {
		buyers.Add(1)
		go func() {
			defer buyers.Done()
			<-start
			mu.Lock()
			available := stock > 0
			mu.Unlock()
			if available { // another buyer can slip in here
				mu.Lock()
				stock--
				sold++
				mu.Unlock()
			}
		}()
	}
	close(start)
	buyers.Wait()
	fmt.Println("never negative?", stock >= 0, "| fix: check and act under ONE lock")
}

package main

import (
	"fmt"
	"sync"
)

type readOp struct {
	key  string
	resp chan int
}

type incOp struct {
	key  string
	resp chan int
}

// counterService owns its map; nothing else can touch it.
func counterService(reads chan readOp, incs chan incOp, quit chan struct{}) {
	state := map[string]int{}
	for {
		select {
		case r := <-reads:
			r.resp <- state[r.key]
		case in := <-incs:
			state[in.key]++
			in.resp <- state[in.key]
		case <-quit:
			return
		}
	}
}

func main() {
	reads, incs, quit := make(chan readOp), make(chan incOp), make(chan struct{})
	go counterService(reads, incs, quit)
	defer close(quit)

	var wg sync.WaitGroup
	for i := range 100 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			key := []string{"go", "rust", "zig"}[i%3]
			op := incOp{key, make(chan int)}
			incs <- op
			<-op.resp
		}()
	}
	wg.Wait()
	for _, k := range []string{"go", "rust", "zig"} {
		r := readOp{k, make(chan int)}
		reads <- r
		fmt.Println(k, <-r.resp)
	}
}

package main

import (
	"fmt"
	"sync"
)

// BoundedQueue blocks producers when full and consumers when empty.
type BoundedQueue struct {
	mu       sync.Mutex
	notFull  *sync.Cond
	notEmpty *sync.Cond
	items    []int
	cap      int
}

func NewBoundedQueue(capacity int) *BoundedQueue {
	q := &BoundedQueue{cap: capacity}
	q.notFull = sync.NewCond(&q.mu)
	q.notEmpty = sync.NewCond(&q.mu)
	return q
}

func (q *BoundedQueue) Put(v int) {
	q.mu.Lock()
	for len(q.items) == q.cap {
		q.notFull.Wait()
	}
	q.items = append(q.items, v)
	q.mu.Unlock()
	q.notEmpty.Signal()
}

func (q *BoundedQueue) Get() int {
	q.mu.Lock()
	for len(q.items) == 0 {
		q.notEmpty.Wait()
	}
	v := q.items[0]
	q.items = q.items[1:]
	q.mu.Unlock()
	q.notFull.Signal()
	return v
}

func main() {
	q := NewBoundedQueue(2)
	var wg sync.WaitGroup
	for p := range 3 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range 4 {
				q.Put(p*100 + i)
			}
		}()
	}
	sum, count := 0, 0
	for range 12 {
		sum += q.Get()
		count++
	}
	wg.Wait()
	fmt.Println("received", count, "items, sum", sum, "queue now", len(q.items))
}

