import (
	"bytes"
	"fmt"
	"sync"
	"sync/atomic"
)

var created atomic.Int64

var bufPool = sync.Pool{
	New: func() any {
		created.Add(1)
		return new(bytes.Buffer)
	},
}

func render(name string, n int) string {
	buf := bufPool.Get().(*bytes.Buffer)
	buf.Reset() // pooled objects come back dirty
	defer func() {
		if buf.Cap() <= 64<<10 { // don't keep huge buffers alive
			bufPool.Put(buf)
		}
	}()
	fmt.Fprintf(buf, "<li>%s #%d</li>", name, n)
	return buf.String()
}

func main() {
	fmt.Println(render("ada", 1))
	fmt.Println(render("bob", 2))

	var wg sync.WaitGroup
	for i := range 1000 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			render("user", i)
		}()
	}
	wg.Wait()
	fmt.Println("1002 renders, buffers allocated far fewer:", created.Load() < 1002)
}

