type ShardedMap struct {
	seed   maphash.Seed
	shards [8]struct {
		sync.Mutex
		m map[string]int
	}
}

func NewShardedMap() *ShardedMap {
	s := &ShardedMap{seed: maphash.MakeSeed()}
	for i := range s.shards {
		s.shards[i].m = map[string]int{}
	}
	return s
}

func (s *ShardedMap) Inc(key string) {
	sh := &s.shards[maphash.String(s.seed, key)%8]
	sh.Lock()
	sh.m[key]++
	sh.Unlock()
}

func (s *ShardedMap) Get(key string) int {
	sh := &s.shards[maphash.String(s.seed, key)%8]
	sh.Lock()
	defer sh.Unlock()
	return sh.m[key]
}

func main() {
	var sessions sync.Map
	var wg sync.WaitGroup
	winners := make([]string, 5)
	for i := range 5 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			actual, _ := sessions.LoadOrStore("user-1", fmt.Sprint("session-", i))
			winners[i] = actual.(string)
		}()
	}
	wg.Wait()
	slices.Sort(winners)
	fmt.Println("all goroutines agree:", len(slices.Compact(winners)) == 1)

	sessions.Store("user-2", "session-x")
	n := 0
	sessions.Range(func(k, v any) bool { n++; return true })
	fmt.Println("entries:", n)

	sm := NewShardedMap()
	for i := range 1000 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			sm.Inc([]string{"a", "b", "c", "d"}[i%4])
		}()
	}
	wg.Wait()
	fmt.Println(sm.Get("a"), sm.Get("b"), sm.Get("c"), sm.Get("d"))
}

lessons.concept:
The workhorse of concurrent Go is a loop around a select
(Concurrency in Go ch.4):

    for {
        select {
        case <-ctx.Done():
            return                    // always have a way out
        case v, ok := <-in:
            if !ok { ... }            // closed
            ...
        }
    }

▸  NIL CHANNELS DISABLE A CASE (100 Go Mistakes #66)
Sends and receives on a nil channel block forever, so a select never
picks that case. Setting a channel variable to nil 'switches off' its
case:

    for a != nil || b != nil {
        select {
        case v, ok := <-a:
            if !ok { a = nil; continue }   // a is done: stop selecting it
            ...
        case v, ok := <-b:
            if !ok { b = nil; continue }
            ...
        }
    }

Without the nil trick, a closed channel is ALWAYS ready (returning
zero values), so the loop would spin at 100% CPU.

▸  NOTIFICATION CHANNELS (100 Go Mistakes #65)
For 'something happened' with no data, use chan struct{} - it
documents intent and carries zero bytes.

