package main

import "fmt"

func source(prefix string, n int) <-chan string {
	ch := make(chan string)
	go func() {
		defer close(ch)
		for i := range n {
			ch <- fmt.Sprint(prefix, i)
		}
	}()
	return ch
}

func main() {
	a, b := source("a", 2), source("b", 3)
	var got []string
	spins := 0
	for a != nil || b != nil {
		select {
		case v, ok := <-a:
			if !ok {
				a = nil // switch this case off
				continue
			}
			got = append(got, v)
		case v, ok := <-b:
			if !ok {
				b = nil
				continue
			}
			got = append(got, v)
		}
		spins++
	}
	fmt.Println(len(got), "values in", spins, "useful iterations")

	var never chan int // nil
	select {
	case v := <-never:
		fmt.Println("impossible", v)
	default:
		fmt.Println("a nil channel is never ready")
	}
}

package main

import (
	"fmt"
	"sync"
	"time"
)

func repeat(done <-chan struct{}, vals ...int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for {
			for _, v := range vals {
				select {
				case out <- v:
				case <-done:
					return
				}
			}
		}
	}()
	return out
}

func take(done <-chan struct{}, in <-chan int, n int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for range n {
			select {
			case v := <-in:
				out <- v
			case <-done:
				return
			}
		}
	}()
	return out
}

func orDone(done <-chan struct{}, in <-chan int) <-chan int {
	out := make(chan int)
	go func() {
		defer close(out)
		for {
			select {
			case <-done:
				return
			case v, ok := <-in:
				if !ok {
					return
				}
				select {
				case out <- v:
				case <-done:
					return
				}
			}
		}
	}()
	return out
}

func or(chans ...<-chan struct{}) <-chan struct{} {
	out := make(chan struct{})
	var once sync.Once
	for _, c := range chans {
		go func() {
			select {
			case <-c: // this input fired first: close out (once)
				once.Do(func() { close(out) })
			case <-out: // another input won; stop waiting
			}
		}()
	}
	return out
}

func after(d time.Duration) <-chan struct{} {
	c := make(chan struct{})
	go func() { time.Sleep(d); close(c) }()
	return c
}

func main() {
	done := make(chan struct{})
	var got []int
	for v := range take(done, repeat(done, 1, 2, 3), 7) {
		got = append(got, v)
	}
	fmt.Println(got)

	n := 0
	stop := make(chan struct{})
	for range orDone(stop, repeat(done, 9)) {
		n++
		if n == 4 {
			close(stop) // the consumer's way out
		}
	}
	fmt.Println("orDone stopped after", n)
	close(done)

	start := time.Now()
	<-or(after(time.Hour), after(20*time.Millisecond), after(time.Minute))
	fmt.Println("or closed on the fastest signal:", time.Since(start) < time.Second)
}

package main

import "fmt"

func gen(done <-chan struct{}, vals ...string) <-chan string {
	out := make(chan string)
	go func() {
		defer close(out)
		for _, v := range vals {
			select {
			case out <- v:
			case <-done:
				return
			}
		}
	}()
	return out
}

func tee(done <-chan struct{}, in <-chan string) (<-chan string, <-chan string) {
	out1, out2 := make(chan string), make(chan string)
	go func() {
		defer close(out1)
		defer close(out2)
		for v := range in {
			o1, o2 := out1, out2 // local copies we can nil out
			for range 2 {
				select {
				case <-done:
					return
				case o1 <- v:
					o1 = nil
				case o2 <- v:
					o2 = nil
				}
			}
		}
	}()
	return out1, out2
}

func bridge(done <-chan struct{}, chans <-chan (<-chan string)) <-chan string {
	out := make(chan string)
	go func() {
		defer close(out)
		for c := range chans {
			for v := range c {
				select {
				case out <- v:
				case <-done:
					return
				}
			}
		}
	}()
	return out
}

func main() {
	done := make(chan struct{})
	defer close(done)

	a, b := tee(done, gen(done, "order-1", "order-2", "order-3"))
	for v := range a {
		fmt.Printf("process %s | audit %s\n", v, <-b)
	}

	pages := make(chan (<-chan string))
	go func() {
		defer close(pages)
		pages <- gen(done, "p1-a", "p1-b")
		pages <- gen(done, "p2-a")
		pages <- gen(done, "p3-a", "p3-b", "p3-c")
	}()
	for v := range bridge(done, pages) {
		fmt.Print(v, " ")
	}
	fmt.Println()
}

package main

import (
	"context"
	"fmt"
	"time"
)

// worker processes jobs and pulses after each one. Job 4 hangs.
func worker(ctx context.Context, jobs []int) <-chan int {
	heartbeat := make(chan int, 1)
	go func() {
		for _, j := range jobs {
			if j == 4 {
				<-ctx.Done() // simulates a hang until cancelled
				return
			}
			time.Sleep(5 * time.Millisecond) // the work
			select {
			case heartbeat <- j:
			default: // never block on a pulse
			}
		}
	}()
	return heartbeat
}

func main() {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()
	pulses := worker(ctx, []int{1, 2, 3, 4, 5})

	const timeout = 100 * time.Millisecond
	for {
		select {
		case j := <-pulses:
			fmt.Println("pulse: finished job", j)
			continue
		case <-time.After(timeout):
			fmt.Println("no heartbeat for", timeout, "- worker is stuck; restarting")
			cancel()
		}
		break
	}
	ctx2, cancel2 := context.WithCancel(context.Background())
	defer cancel2()
	fmt.Println("new worker pulse: job", <-worker(ctx2, []int{4 + 1}))
}

package main

import (
	"context"
	"fmt"
	"sync"
	"time"
)

func query(ctx context.Context, replica int, delay time.Duration) (string, error) {
	select {
	case <-time.After(delay):
		return fmt.Sprintf("answer from replica %d", replica), nil
	case <-ctx.Done():
		return "", ctx.Err()
	}
}

func main() {
	delays := []time.Duration{80, 15, 300, 45, 120} // milliseconds
	ctx, cancel := context.WithCancel(context.Background())

	type result struct {
		val string
		err error
	}
	results := make(chan result, len(delays))
	var wg sync.WaitGroup
	for i, d := range delays {
		wg.Add(1)
		go func() {
			defer wg.Done()
			v, err := query(ctx, i, d*time.Millisecond)
			results <- result{v, err}
		}()
	}
	start := time.Now()
	first := <-results
	cancel() // tell the slower replicas to stop
	fmt.Println(first.val, "| fast:", time.Since(start) < 70*time.Millisecond)

	wg.Wait()
	close(results)
	cancelled := 0
	for r := range results {
		if r.err != nil {
			cancelled++
		}
	}
	fmt.Println("losers cancelled:", cancelled)
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
	"time"
)

type result struct {
	value string
	err   error
}

type entry struct {
	res   result
	ready chan struct{}
}

type Memo struct {
	f     func(string) (string, error)
	mu    sync.Mutex
	cache map[string]*entry
}

func New(f func(string) (string, error)) *Memo {
	return &Memo{f: f, cache: map[string]*entry{}}
}

func (m *Memo) Get(key string) (string, error) {
	m.mu.Lock()
	e := m.cache[key]
	if e == nil {
		e = &entry{ready: make(chan struct{})}
		m.cache[key] = e
		m.mu.Unlock()
		e.res.value, e.res.err = m.f(key) // slow, without the lock
		close(e.ready)
	} else {
		m.mu.Unlock()
		<-e.ready
	}
	return e.res.value, e.res.err
}

var calls atomic.Int64

func slowFetch(url string) (string, error) {
	calls.Add(1)
	time.Sleep(50 * time.Millisecond)
	return "content of " + url, nil
}

func main() {
	m := New(slowFetch)
	var wg sync.WaitGroup
	start := time.Now()
	for i := range 20 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			url := []string{"go.dev", "pkg.go.dev"}[i%2]
			if v, _ := m.Get(url); v == "" {
				fmt.Println("empty!")
			}
		}()
	}
	wg.Wait()
	fmt.Println("20 requests, slow calls made:", calls.Load())
	fmt.Println("keys fetched in parallel:", time.Since(start) < 90*time.Millisecond)
	v, _ := m.Get("go.dev")
	fmt.Println(v, "| calls still", calls.Load())
}

