	"slices"
	"sync"
)

type Scores struct {
	mu sync.Mutex
	m  map[string]int
}

func (s *Scores) Add(k string, v int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.m[k] += v
}

// Snapshot returns a COPY, so callers never read the map unlocked.
func (s *Scores) Snapshot() map[string]int {
	s.mu.Lock()
	defer s.mu.Unlock()
	return maps.Clone(s.m)
}

func main() {
	base := make([]int, 0, 10)
	base = append(base, 0)
	results := make([][]int, 2)
	var wg sync.WaitGroup
	for i := range 2 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			mine := append(slices.Clone(base), i+1) // never shares base's spare slot
			results[i] = mine
		}()
	}
	wg.Wait()
	fmt.Println(results[0], results[1])

	s := &Scores{m: map[string]int{}}
	for i := range 50 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			s.Add([]string{"red", "blue"}[i%2], 1)
		}()
	}
	wg.Wait()
	snap := s.Snapshot()
	snap["red"] = 999 // changes the copy only
	for _, k := range slices.Sorted(maps.Keys(s.Snapshot())) {
		fmt.Println(k, s.Snapshot()[k])
	}
}

