import (
	"fmt"
	"os"
	"path/filepath"
	"sync"
)

var sema = make(chan struct{}, 4)

func walk(dir string, wg *sync.WaitGroup, sizes chan<- int64) {
	defer wg.Done()
	sema <- struct{}{}
	entries, err := os.ReadDir(dir)
	<-sema
	if err != nil {
		return
	}
	for _, e := range entries {
		if e.IsDir() {
			wg.Add(1)
			go walk(filepath.Join(dir, e.Name()), wg, sizes)
			continue
		}
		if info, err := e.Info(); err == nil {
			sizes <- info.Size()
		}
	}
}

func main() {
	root, _ := os.MkdirTemp("", "du-*")
	defer os.RemoveAll(root)
	for i := range 6 {
		for j := range 5 {
			dir := filepath.Join(root, fmt.Sprint("d", i), fmt.Sprint("sub", j))
			os.MkdirAll(dir, 0o755)
			for k := range 3 {
				os.WriteFile(filepath.Join(dir, fmt.Sprint("f", k)), make([]byte, 100*(k+1)), 0o644)
			}
		}
	}

	sizes := make(chan int64)
	var wg sync.WaitGroup
	wg.Add(1)
	go walk(root, &wg, sizes)
	go func() {
		wg.Wait()
		close(sizes)
	}()
	var files, total int64
	for s := range sizes {
		files++
		total += s
	}
	fmt.Printf("%d files, %d bytes (%.1f KB)\n", files, total, float64(total)/1024)
}

