import (
	"fmt"
	"sync"
)

type Account struct {
	ID      int
	mu      sync.Mutex
	Balance int
}

// transfer always locks the account with the smaller ID first,
// so two opposite transfers can never wait on each other in a circle.
func transfer(from, to *Account, amount int) {
	first, second := from, to
	if to.ID < from.ID {
		first, second = to, from
	}
	first.mu.Lock()
	defer first.mu.Unlock()
	second.mu.Lock()
	defer second.mu.Unlock()
	from.Balance -= amount
	to.Balance += amount
}

func main() {
	a := &Account{ID: 1, Balance: 1000}
	b := &Account{ID: 2, Balance: 1000}
	var wg sync.WaitGroup
	for i := range 1000 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			if i%2 == 0 {
				transfer(a, b, 1) // locks a then b
			} else {
				transfer(b, a, 1) // ALSO locks a then b: same order
			}
		}()
	}
	wg.Wait()
	fmt.Println(a.Balance, b.Balance, a.Balance+b.Balance)

	var mu sync.Mutex
	mu.Lock()
	fmt.Println("TryLock while held:", mu.TryLock())
	mu.Unlock()
	fmt.Println("TryLock when free:", mu.TryLock())
}

