	"sync"
)

func main() {
	// Guarantee: the send completes only once the worker has received.
	work := make(chan string)
	done := make(chan struct{})
	go func() {
		task := <-work
		fmt.Println("worker got", task)
		close(done)
	}()
	work <- "invoice-1" // returns after the hand-off
	<-done

	// Broadcast without data: one close wakes every waiter.
	start := make(chan struct{})
	var wg sync.WaitGroup
	ready := make([]bool, 3)
	for i := range 3 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			<-start
			ready[i] = true
		}()
	}
	close(start)
	wg.Wait()
	fmt.Println("all started:", ready)

	// Drop pattern: a full buffer means shed the load, not block.
	queue := make(chan int, 2)
	dropped := 0
	for i := range 5 {
		select {
		case queue <- i:
		default:
			dropped++
		}
	}
	fmt.Println("queued", len(queue), "dropped", dropped)
}

