import (
	"errors"
	"fmt"
	"strconv"
	"sync"
)

type Result struct {
	Input string
	Value int
	Err   error
}

func parseAll(inputs []string) <-chan Result {
	out := make(chan Result)
	var wg sync.WaitGroup
	for _, in := range inputs {
		wg.Add(1)
		go func() {
			defer wg.Done()
			n, err := strconv.Atoi(in)
			if err != nil {
				err = fmt.Errorf("parse %q: %w", in, err)
			}
			out <- Result{in, n, err}
		}()
	}
	go func() { wg.Wait(); close(out) }()
	return out
}

func main() {
	inputs := []string{"10", "x", "20", "3.5", "40", "?"}
	sum, errs := 0, []error{}
	for r := range parseAll(inputs) {
		if r.Err != nil {
			errs = append(errs, r.Err)
			continue
		}
		sum += r.Value
	}
	fmt.Println("sum of valid inputs:", sum)
	fmt.Println("failures:", len(errs))
	if len(errs) >= 3 {
		fmt.Println("too many failures - the consumer decides to abort")
	}
	fmt.Println(errors.Is(errors.Join(errs...), strconv.ErrSyntax))
}

