func race2(pa, pb *int64) time.Duration {
	var wg sync.WaitGroup
	start := time.Now()
	for _, p := range []*int64{pa, pb} {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for range 20_000_000 {
				*p++ // each goroutine touches only its own field
			}
		}()
	}
	wg.Wait()
	return time.Since(start)
}

