var keep [][]byte

func churn(mb int) {
	for range mb * 16 {
		b := make([]byte, 64<<10)
		keep = append(keep[:0], b) // keeps only the latest buffer alive
	}
}

func gcCount(f func()) uint32 {
	var before, after runtime.MemStats
	runtime.GC()
	runtime.ReadMemStats(&before)
	f()
	runtime.ReadMemStats(&after)
	return after.NumGC - before.NumGC
}

func main() {
	old := debug.SetGCPercent(100)
	fmt.Println("default GOGC:", old)

	normal := gcCount(func() { churn(256) })
	debug.SetGCPercent(800) // collect less often
	relaxed := gcCount(func() { churn(256) })
	debug.SetGCPercent(100)
	fmt.Println("GOGC=800 ran fewer collections:", relaxed < normal)

	prev := debug.SetMemoryLimit(512 << 20) // 512 MiB soft limit
	fmt.Println("memory limit was unlimited:", prev == 1<<63-1)
	fmt.Println("GOMAXPROCS:", runtime.GOMAXPROCS(0) >= 1)
}

