import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"errors"
	"fmt"
)

func encrypt(key, plaintext, aad []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	nonce := make([]byte, gcm.NonceSize())
	rand.Read(nonce)
	return gcm.Seal(nonce, nonce, plaintext, aad), nil // nonce is prepended
}

func decrypt(key, sealed, aad []byte) ([]byte, error) {
	block, err := aes.NewCipher(key)
	if err != nil {
		return nil, err
	}
	gcm, err := cipher.NewGCM(block)
	if err != nil {
		return nil, err
	}
	if len(sealed) < gcm.NonceSize() {
		return nil, errors.New("ciphertext too short")
	}
	nonce, ct := sealed[:gcm.NonceSize()], sealed[gcm.NonceSize():]
	return gcm.Open(nil, nonce, ct, aad)
}

func main() {
	key := make([]byte, 32) // AES-256
	rand.Read(key)
	secret := []byte("card 4111 1111 1111 1111")

	sealed, _ := encrypt(key, secret, []byte("user:42"))
	fmt.Println("plaintext", len(secret), "bytes -> sealed", len(sealed), "bytes (12 nonce + 16 tag)")

	plain, err := decrypt(key, sealed, []byte("user:42"))
	fmt.Printf("%q %v\n", plain, err)

	_, err = decrypt(key, sealed, []byte("user:43"))
	fmt.Println("wrong context:", err)

	sealed[20] ^= 1 // flip one bit
	_, err = decrypt(key, sealed, []byte("user:42"))
	fmt.Println("tampered:", err)
}

