	var s Signup
	var errs []error
	u := form.Get("username")
	if !utf8.ValidString(u) || !usernameRE.MatchString(u) {
		errs = append(errs, errors.New("username: 3-20 of a-z, 0-9, _"))
	}
	age, err := strconv.Atoi(form.Get("age"))
	if err != nil || age < 13 || age > 130 {
		errs = append(errs, errors.New("age: a number from 13 to 130"))
	}
	next := form.Get("next")
	if p, err := url.Parse(next); err != nil || p.IsAbs() || p.Host != "" || len(next) > 0 && next[0] != '/' {
		errs = append(errs, errors.New("next: must be a local path"))
	}
	s = Signup{u, age, next}
	return s, errors.Join(errs...)
}

func main() {
	for _, q := range []string{
		"username=ada_l&age=36&next=/dashboard",
		"username=Robert'+OR+1&age=abc&next=https://evil.example",
		"username=al&age=200&next=//evil.example/login",
	} {
		form, _ := url.ParseQuery(q)
		s, err := parseSignup(form)
		if err != nil {
			fmt.Printf("REJECTED:\n%v\n", err)
			continue
		}
		fmt.Printf("accepted %+v\n", s)
	}
}

