func main() {
	srv := httptest.NewUnstartedServer(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Strict-Transport-Security", "max-age=31536000")
		fmt.Fprintf(w, "secure hello over %s", tlsName(r.TLS.Version))
	}))
	srv.Config.ErrorLog = log.New(io.Discard, "", 0) // hide the expected handshake error
	srv.StartTLS()
	defer srv.Close()

	resp, err := srv.Client().Get(srv.URL) // trusts the test certificate
	if err != nil {
		panic(err)
	}
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	fmt.Println(string(body), "| HSTS:", resp.Header.Get("Strict-Transport-Security") != "")

	_, err = http.Get(srv.URL) // the default client does NOT trust it
	var certErr *tls.CertificateVerificationError
	fmt.Println("untrusted certificate rejected:", errors.As(err, &certErr))
}

func tlsName(v uint16) string {
	switch v {
	case tls.VersionTLS13:
		return "TLS 1.3"
	case tls.VersionTLS12:
		return "TLS 1.2"
	}
	return "old TLS"
}

package main

import (
	"fmt"
	"sync"
	"time"
)

type bucket struct {
	tokens float64
	last   time.Time
}

type Limiter struct {
	mu      sync.Mutex
	rate    float64 // tokens per second
	burst   float64
	clients map[string]*bucket
	now     func() time.Time
}

func NewLimiter(rate, burst float64, now func() time.Time) *Limiter {
	return &Limiter{rate: rate, burst: burst, clients: map[string]*bucket{}, now: now}
}

func (l *Limiter) Allow(client string) bool {
	l.mu.Lock()
	defer l.mu.Unlock()
	t := l.now()
	b, ok := l.clients[client]
	if !ok {
		b = &bucket{tokens: l.burst, last: t}
		l.clients[client] = b
	}
	b.tokens = min(l.burst, b.tokens+t.Sub(b.last).Seconds()*l.rate) // refill
	b.last = t
	if b.tokens < 1 {
		return false
	}
	b.tokens--
	return true
}

func main() {
	clock := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
	lim := NewLimiter(2, 3, func() time.Time { return clock }) // 2/s, bursts of 3

	var burst []int
	for range 5 {
		if lim.Allow("10.0.0.7") {
			burst = append(burst, 200)
		} else {
			burst = append(burst, 429)
		}
	}
	fmt.Println("burst of 5:   ", burst)
	fmt.Println("other client: ", lim.Allow("10.0.0.8"))

	clock = clock.Add(500 * time.Millisecond) // refills one token
	fmt.Println("after 0.5s:   ", lim.Allow("10.0.0.7"), lim.Allow("10.0.0.7"))
	clock = clock.Add(10 * time.Second) // refills, capped at the burst size
	n := 0
	for lim.Allow("10.0.0.7") {
		n++
	}
	fmt.Println("after 10s idle:", n, "requests allowed")
}

