package main

import (
	"errors"
	"fmt"
)

var (
	errEmpty   = errors.New("empty input")
	errTooLong = errors.New("result too long")
)

func joinNested(a, b string, max int) (string, error) {
	if a != "" {
		if b != "" {
			s := a + b
			if len(s) <= max {
				return s, nil
			} else {
				return "", errTooLong
			}
		} else {
			return "", errEmpty
		}
	} else {
		return "", errEmpty
	}
}

func joinFlat(a, b string, max int) (string, error) {
	if a == "" || b == "" {
		return "", errEmpty
	}
	s := a + b
	if len(s) > max {
		return "", errTooLong
	}
	return s, nil
}

func main() {
	for _, in := range [][2]string{{"go", "pher"}, {"", "x"}, {"long", "string"}} {
		r1, e1 := joinNested(in[0], in[1], 8)
		r2, e2 := joinFlat(in[0], in[1], 8)
		fmt.Printf("%q %v | %q %v | same: %v\n", r1, e1, r2, e2, r1 == r2 && e1 == e2)
	}
}

