import (
	"cmp"
	"fmt"
	"math"
)

// Generic: identical code for every element type.
func MaxOf[T cmp.Ordered](xs []T) (T, bool) {
	var best T
	if len(xs) == 0 {
		return best, false
	}
	best = xs[0]
	for _, x := range xs[1:] {
		best = max(best, x)
	}
	return best, true
}

// Interface: different behaviour per type.
type Shape interface{ Area() float64 }
type Square struct{ S float64 }
type Circle struct{ R float64 }

func (s Square) Area() float64 { return s.S * s.S }
func (c Circle) Area() float64 { return math.Pi * c.R * c.R }

func Largest(shapes []Shape) Shape {
	var best Shape
	for _, s := range shapes {
		if best == nil || s.Area() > best.Area() {
			best = s
		}
	}
	return best
}

func main() {
	fmt.Println(MaxOf([]int{3, 9, 2}))
	fmt.Println(MaxOf([]string{"kiwi", "apple", "pear"}))
	fmt.Println(MaxOf([]float64{}))
	fmt.Printf("%+v\n", Largest([]Shape{Square{3}, Circle{2}, Square{1}}))
}

lessons.concept:
Go apps wire dependencies by hand - explicitly, in main (Let's Go
3.3). No container or reflection-based framework is needed.

▸  THE APPLICATION STRUCT
    type application struct {
        logger *slog.Logger
        users  UserStore          // an interface: real DB or a fake
        mailer Mailer
        cfg    config
    }
    func (app *application) signup(w http.ResponseWriter, r *http.Request) {
        ... app.users.Insert(...) ... app.logger.Info(...)
    }
Handlers are METHODS on the struct, so they reach their dependencies
without globals.

▸  WIRING IN main
    func main() {
        cfg := loadConfig()
        db := openDB(cfg.DSN)
        app := &application{logger: newLogger(), users: &UserModel{DB: db}, ...}
        srv := &http.Server{Handler: app.routes(), ...}
        ...
    }

▸  WHY EXPLICIT IS GOOD
Reading main tells you exactly what the program uses. Tests build an
application with fakes in two lines. No package-level variables means
no hidden coupling and no ordering problems with init().

▸  CLOSURES WORK TOO
func handler(store UserStore) http.HandlerFunc { return func(...) {...} }
is equally valid for small apps.

