// Errors from two unrelated "packages" share one behaviour.
type netError struct{ op string }

func (e *netError) Error() string   { return e.op + ": connection reset" }
func (e *netError) Temporary() bool { return true }

type quotaError struct{ user string }

func (e *quotaError) Error() string   { return "quota exceeded for " + e.user }
func (e *quotaError) Temporary() bool { return false }

// The caller depends only on the behaviour.
func shouldRetry(err error) bool {
	var t interface{ Temporary() bool }
	return errors.As(err, &t) && t.Temporary()
}

