package main

import (
	"errors"
	"fmt"
	"math"
	"strconv"
	"strings"
	"unicode"
)

type Env map[string]float64

type Expr interface {
	Eval(env Env) (float64, error)
}

type num float64
type varRef string
type unary struct {
	op byte
	x  Expr
}
type binary struct {
	op   byte
	l, r Expr
}
type call struct {
	fn   string
	args []Expr
}

func (n num) Eval(Env) (float64, error) { return float64(n), nil }

func (v varRef) Eval(env Env) (float64, error) {
	if x, ok := env[string(v)]; ok {
		return x, nil
	}
	return 0, fmt.Errorf("undefined variable %q", string(v))
}

func (u unary) Eval(env Env) (float64, error) {
	x, err := u.x.Eval(env)
	return -x, err
}

func (b binary) Eval(env Env) (float64, error) {
	l, err := b.l.Eval(env)
	if err != nil {
		return 0, err
	}
	r, err := b.r.Eval(env)
	if err != nil {
		return 0, err
	}
	switch b.op {
	case '+':
		return l + r, nil
	case '-':
		return l - r, nil
	case '*':
		return l * r, nil
	case '/':
		if r == 0 {
			return 0, errors.New("division by zero")
		}
		return l / r, nil
	case '^':
		return math.Pow(l, r), nil
	}
	return 0, fmt.Errorf("bad operator %q", b.op)
}

func (c call) Eval(env Env) (float64, error) {
	vals := make([]float64, len(c.args))
	for i, a := range c.args {
		v, err := a.Eval(env)
		if err != nil {
			return 0, err
		}
		vals[i] = v
	}
	switch {
	case c.fn == "sqrt" && len(vals) == 1:
		return math.Sqrt(vals[0]), nil
	case (c.fn == "min" || c.fn == "max") && len(vals) > 0:
		best := vals[0]
		for _, v := range vals[1:] {
			if c.fn == "min" {
				best = min(best, v)
			} else {
				best = max(best, v)
			}
		}
		return best, nil
	}
	return 0, fmt.Errorf("unknown function %s/%d", c.fn, len(vals))
}

// ---- lexer and parser ----

type parser struct {
	toks []string
	pos  int
}

func lex(s string) ([]string, error) {
	var toks []string
	for i := 0; i < len(s); {
		c := rune(s[i])
		switch {
		case unicode.IsSpace(c):
			i++
		case unicode.IsDigit(c) || c == '.':
			j := i
			for j < len(s) && (unicode.IsDigit(rune(s[j])) || s[j] == '.') {
				j++
			}
			toks, i = append(toks, s[i:j]), j
		case unicode.IsLetter(c):
			j := i
			for j < len(s) && unicode.IsLetter(rune(s[j])) {
				j++
			}
			toks, i = append(toks, s[i:j]), j
		case strings.ContainsRune("+-*/^(),", c):
			toks, i = append(toks, string(c)), i+1
		default:
			return nil, fmt.Errorf("unexpected character %q", c)
		}
	}
	return toks, nil
}

func (p *parser) peek() string {
	if p.pos < len(p.toks) {
		return p.toks[p.pos]
	}
	return ""
}

func (p *parser) next() string { t := p.peek(); p.pos++; return t }

func (p *parser) expr() (Expr, error) {
	l, err := p.term()
	for err == nil && (p.peek() == "+" || p.peek() == "-") {
		op := p.next()[0]
		var r Expr
		if r, err = p.term(); err == nil {
			l = binary{op, l, r}
		}
	}
	return l, err
}

func (p *parser) term() (Expr, error) {
	l, err := p.unary()
	for err == nil && (p.peek() == "*" || p.peek() == "/") {
		op := p.next()[0]
		var r Expr
		if r, err = p.unary(); err == nil {
			l = binary{op, l, r}
		}
	}
	return l, err
}

func (p *parser) unary() (Expr, error) {
	if p.peek() == "-" {
		p.next()
		x, err := p.unary()
		return unary{'-', x}, err
	}
	return p.power()
}

func (p *parser) power() (Expr, error) {
	base, err := p.atom()
	if err != nil || p.peek() != "^" {
		return base, err
	}
	p.next()
	exp, err := p.unary() // right-associative
	return binary{'^', base, exp}, err
}

func (p *parser) atom() (Expr, error) {
	t := p.next()
	switch {
	case t == "":
		return nil, errors.New("unexpected end of input")
	case t == "(":
		e, err := p.expr()
		if err == nil && p.next() != ")" {
			err = errors.New("missing )")
		}
		return e, err
	case unicode.IsDigit(rune(t[0])) || t[0] == '.':
		f, err := strconv.ParseFloat(t, 64)
		return num(f), err
	case unicode.IsLetter(rune(t[0])):
		if p.peek() != "(" {
			return varRef(t), nil
		}
		p.next()
		var args []Expr
		for p.peek() != ")" {
			a, err := p.expr()
			if err != nil {
				return nil, err
			}
			args = append(args, a)
			if p.peek() == "," {
				p.next()
			}
		}
		p.next()
		return call{t, args}, nil
	}
	return nil, fmt.Errorf("unexpected %q", t)
}

func Parse(s string) (Expr, error) {
	toks, err := lex(s)
	if err != nil {
		return nil, err
	}
	p := &parser{toks: toks}
	e, err := p.expr()
	if err == nil && p.pos < len(p.toks) {
		err = fmt.Errorf("unexpected %q", p.peek())
	}
	return e, err
}

func main() {
	env := Env{"x": 3, "pi": math.Pi, "r": 2}
	for _, src := range []string{
		"1 + 2 * 3",
		"(1 + 2) * 3",
		"2 ^ 3 ^ 2",
		"-2 ^ 2",
		"pi * r ^ 2",
		"sqrt(x*x + 16)",
		"max(1, x, min(10, 7)) / 2",
		"y + 1",
		"10 / (x - 3)",
		"2 * (3 + 4",
		"5 $ 2",
	} {
		e, err := Parse(src)
		if err != nil {
			fmt.Printf("%-28s parse error: %v\n", src, err)
			continue
		}
		v, err := e.Eval(env)
		if err != nil {
			fmt.Printf("%-28s eval error: %v\n", src, err)
			continue
		}
		fmt.Printf("%-28s = %.6g\n", src, v)
	}
}

package main

import (
	"cmp"
	"encoding/json"
	"errors"
	"flag"
	"fmt"
	"io"
	"io/fs"
	"os"
	"path/filepath"
	"slices"
	"strconv"
	"strings"
)

type Task struct {
	ID       int    `json:"id"`
	Text     string `json:"text"`
	Priority int    `json:"priority"`
	Done     bool   `json:"done"`
}

type Store struct{ path string }

func (s Store) Load() ([]Task, error) {
	b, err := os.ReadFile(s.path)
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	var tasks []Task
	return tasks, json.Unmarshal(b, &tasks)
}

func (s Store) Save(tasks []Task) error {
	b, err := json.MarshalIndent(tasks, "", "  ")
	if err != nil {
		return err
	}
	tmp, err := os.CreateTemp(filepath.Dir(s.path), ".todo-*")
	if err != nil {
		return err
	}
	defer os.Remove(tmp.Name()) // no-op after a successful rename
	if _, err := tmp.Write(b); err != nil {
		tmp.Close()
		return err
	}
	if err := tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), s.path) // atomic replace
}

func run(args []string, store Store, out io.Writer) int {
	if len(args) == 0 {
		fmt.Fprintln(out, "usage: todo <add|list|done|rm> ...")
		return 2
	}
	tasks, err := store.Load()
	if err != nil {
		fmt.Fprintln(out, "error:", err)
		return 1
	}
	find := func(arg string) int {
		id, err := strconv.Atoi(arg)
		if err != nil {
			return -1
		}
		return slices.IndexFunc(tasks, func(t Task) bool { return t.ID == id })
	}
	switch args[0] {
	case "add":
		fs := flag.NewFlagSet("add", flag.ContinueOnError)
		fs.SetOutput(io.Discard)
		prio := fs.Int("p", 2, "priority 1-3")
		if err := fs.Parse(args[1:]); err != nil || fs.NArg() == 0 || *prio < 1 || *prio > 3 {
			fmt.Fprintln(out, "usage: todo add [-p 1-3] TEXT...")
			return 2
		}
		next := 1
		for _, t := range tasks {
			next = max(next, t.ID+1)
		}
		tasks = append(tasks, Task{ID: next, Text: strings.Join(fs.Args(), " "), Priority: *prio})
		fmt.Fprintf(out, "added #%d\n", next)
	case "list":
		all := len(args) > 1 && args[1] == "-all"
		shown := slices.Clone(tasks)
		slices.SortFunc(shown, func(a, b Task) int {
			return cmp.Or(cmp.Compare(b.Priority, a.Priority), cmp.Compare(a.ID, b.ID))
		})
		for _, t := range shown {
			if t.Done && !all {
				continue
			}
			mark := " "
			if t.Done {
				mark = "x"
			}
			fmt.Fprintf(out, "[%s] #%d p%d %s\n", mark, t.ID, t.Priority, t.Text)
		}
		return 0
	case "done", "rm":
		if len(args) < 2 {
			fmt.Fprintf(out, "usage: todo %s ID\n", args[0])
			return 2
		}
		i := find(args[1])
		if i < 0 {
			fmt.Fprintf(out, "error: no task %s\n", args[1])
			return 1
		}
		if args[0] == "done" {
			tasks[i].Done = true
			fmt.Fprintf(out, "finished #%d\n", tasks[i].ID)
		} else {
			fmt.Fprintf(out, "removed #%d\n", tasks[i].ID)
			tasks = slices.Delete(tasks, i, i+1)
		}
	default:
		fmt.Fprintf(out, "error: unknown command %q\n", args[0])
		return 1
	}
	if err := store.Save(tasks); err != nil {
		fmt.Fprintln(out, "error:", err)
		return 1
	}
	return 0
}

func main() {
	dir, _ := os.MkdirTemp("", "todo-*")
	defer os.RemoveAll(dir)
	store := Store{filepath.Join(dir, "todo.json")}
	for _, line := range []string{
		"add buy milk",
		"add -p 3 fix prod bug",
		"add -p 1 read gopl chapter 8",
		"list",
		"done 2",
		"rm 1",
		"list -all",
		"done 42",
		"add -p 9 oops",
		"launch rockets",
	} {
		code := run(strings.Fields(line), store, os.Stdout)
		if code != 0 {
			fmt.Println("  (exit", code, ")")
		}
	}
	b, _ := os.ReadFile(store.path)
	fmt.Println("saved tasks:", strings.Count(string(b), `"id"`))
}

package main

import (
	"cmp"
	"fmt"
	"maps"
	"slices"
	"strconv"
	"strings"
	"sync"
)

const logData = `GET /home 200 12
GET /api/users 200 48
POST /api/users 201 95
GET /api/users/7 404 8
GET /home 200 15
GET /report 500 900
GET /report 200 700
broken line here
GET /api/users 200 52
DELETE /api/users/7 403 5
GET /search 200 300
GET /search 503 1200
GET /home 304 2
PUT /api/users/7 200 abc
GET /report 200 650`

type record struct {
	path   string
	status int
	ms     int
}

type result struct {
	rec record
	ok  bool
}

func parse(line string) (record, bool) {
	f := strings.Fields(line)
	if len(f) != 4 {
		return record{}, false
	}
	status, err1 := strconv.Atoi(f[2])
	ms, err2 := strconv.Atoi(f[3])
	if err1 != nil || err2 != nil {
		return record{}, false
	}
	return record{f[1], status, ms}, true
}

func main() {
	lines := make(chan string)
	results := make(chan result)
	go func() {
		defer close(lines)
		for _, l := range strings.Split(logData, "\n") {
			lines <- l
		}
	}()
	var wg sync.WaitGroup
	for range 4 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for l := range lines {
				r, ok := parse(l)
				results <- result{r, ok}
			}
		}()
	}
	go func() {
		wg.Wait()
		close(results)
	}()

	total, bad := 0, 0
	classes := map[string]int{}
	sum, count := map[string]int{}, map[string]int{}
	for res := range results {
		if !res.ok {
			bad++
			continue
		}
		total++
		classes[fmt.Sprintf("%dxx", res.rec.status/100)]++
		sum[res.rec.path] += res.rec.ms
		count[res.rec.path]++
	}

	fmt.Printf("requests: %d, malformed: %d\n", total, bad)
	for _, c := range slices.Sorted(maps.Keys(classes)) {
		fmt.Printf("  %s: %d\n", c, classes[c])
	}
	paths := slices.Collect(maps.Keys(sum))
	avg := func(p string) float64 { return float64(sum[p]) / float64(count[p]) }
	slices.SortFunc(paths, func(a, b string) int {
		return cmp.Or(cmp.Compare(avg(b), avg(a)), cmp.Compare(a, b))
	})
	fmt.Println("slowest paths (avg ms):")
	for _, p := range paths[:3] {
		fmt.Printf("  %-10s %7.1f\n", p, avg(p))
	}
	fmt.Printf("error rate: %.1f%%\n", 100*float64(classes["5xx"])/float64(total))
}

