import (
	"bufio"
	"fmt"
	"maps"
	"net"
	"slices"
	"strconv"
	"strings"
	"sync"
)

type store struct {
	mu sync.RWMutex
	m  map[string]string
}

func (s *store) exec(line string) string {
	f := strings.Fields(line)
	if len(f) == 0 {
		return "ERR empty command"
	}
	switch cmd := strings.ToUpper(f[0]); {
	case cmd == "SET" && len(f) >= 3:
		s.mu.Lock()
		s.m[f[1]] = strings.Join(f[2:], " ")
		s.mu.Unlock()
		return "OK"
	case cmd == "GET" && len(f) == 2:
		s.mu.RLock()
		defer s.mu.RUnlock()
		if v, ok := s.m[f[1]]; ok {
			return v
		}
		return "(nil)"
	case cmd == "DEL" && len(f) == 2:
		s.mu.Lock()
		defer s.mu.Unlock()
		if _, ok := s.m[f[1]]; ok {
			delete(s.m, f[1])
			return "(integer) 1"
		}
		return "(integer) 0"
	case cmd == "INCR" && len(f) == 2:
		s.mu.Lock() // read-modify-write under ONE lock
		defer s.mu.Unlock()
		n, err := strconv.Atoi(orDefault(s.m[f[1]], "0"))
		if err != nil {
			return "ERR value is not an integer"
		}
		s.m[f[1]] = strconv.Itoa(n + 1)
		return "(integer) " + s.m[f[1]]
	case cmd == "KEYS" && len(f) == 1:
		s.mu.RLock()
		defer s.mu.RUnlock()
		return strings.Join(slices.Sorted(maps.Keys(s.m)), " ")
	}
	return fmt.Sprintf("ERR unknown command '%s'", f[0])
}

func orDefault(v, def string) string {
	if v == "" {
		return def
	}
	return v
}

func serve(ln net.Listener, s *store, conns *sync.WaitGroup) {
	for {
		conn, err := ln.Accept()
		if err != nil {
			return // listener closed
		}
		conns.Add(1)
		go func() {
			defer conns.Done()
			defer conn.Close()
			sc := bufio.NewScanner(conn)
			for sc.Scan() {
				fmt.Fprintln(conn, s.exec(sc.Text()))
			}
		}()
	}
}

type client struct {
	name string
	conn net.Conn
	r    *bufio.Reader
}

func (c *client) do(cmd string) {
	fmt.Fprintln(c.conn, cmd)
	reply, _ := c.r.ReadString('\n')
	fmt.Printf("%s> %-22s %s", c.name, cmd, reply)
}

func dial(name, addr string) *client {
	conn, err := net.Dial("tcp", addr)
	if err != nil {
		panic(err)
	}
	return &client{name, conn, bufio.NewReader(conn)}
}

func main() {
	ln, _ := net.Listen("tcp", "127.0.0.1:0")
	s := &store{m: map[string]string{}}
	var conns sync.WaitGroup
	go serve(ln, s, &conns)

	a, b := dial("A", ln.Addr().String()), dial("B", ln.Addr().String())
	a.do("SET greeting hello gophers")
	b.do("GET greeting")
	a.do("INCR visits")
	b.do("INCR visits")
	b.do("INCR greeting")
	a.do("KEYS")
	b.do("DEL greeting")
	a.do("GET greeting")
	a.do("FLY away")

	ln.Close()
	a.conn.Close()
	b.conn.Close()
	conns.Wait()
	fmt.Println("server stopped; keys left:", len(s.m))
}

