const alphabet = "0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ"

func base62(n int) string {
	if n == 0 {
		return "0"
	}
	var b []byte
	for ; n > 0; n /= 62 {
		b = append([]byte{alphabet[n%62]}, b...)
	}
	return string(b)
}

type Store interface {
	Save(long string) string
	Lookup(code string) (string, bool)
	Len() int
}

type memStore struct {
	mu    sync.Mutex
	next  int
	links map[string]string
}

func (s *memStore) Save(long string) string {
	s.mu.Lock()
	defer s.mu.Unlock()
	s.next++
	code := base62(s.next)
	s.links[code] = long
	return code
}

func (s *memStore) Lookup(code string) (string, bool) {
	s.mu.Lock()
	defer s.mu.Unlock()
	u, ok := s.links[code]
	return u, ok
}

func (s *memStore) Len() int { s.mu.Lock(); defer s.mu.Unlock(); return len(s.links) }

type app struct {
	store     Store
	redirects atomic.Int64
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func (a *app) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("POST /shorten", a.shorten)
	mux.HandleFunc("GET /r/{code}", a.redirect)
	mux.HandleFunc("GET /stats", func(w http.ResponseWriter, r *http.Request) {
		writeJSON(w, http.StatusOK, map[string]int64{"links": int64(a.store.Len()), "redirects": a.redirects.Load()})
	})
	return mux
}

func (a *app) shorten(w http.ResponseWriter, r *http.Request) {
	var in struct {
		URL string `json:"url"`
	}
	r.Body = http.MaxBytesReader(w, r.Body, 4096)
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "invalid JSON"})
		return
	}
	u, err := url.Parse(in.URL)
	if err != nil || (u.Scheme != "http" && u.Scheme != "https") || u.Host == "" {
		writeJSON(w, http.StatusBadRequest, map[string]string{"error": "url must be http(s) with a host"})
		return
	}
	code := a.store.Save(u.String())
	writeJSON(w, http.StatusCreated, map[string]string{"code": code, "short": "/r/" + code})
}

func (a *app) redirect(w http.ResponseWriter, r *http.Request) {
	long, ok := a.store.Lookup(r.PathValue("code"))
	if !ok {
		http.NotFound(w, r)
		return
	}
	a.redirects.Add(1)
	http.Redirect(w, r, long, http.StatusFound)
}

func main() {
	a := &app{store: &memStore{links: map[string]string{}}}
	srv := httptest.NewServer(a.routes())
	defer srv.Close()
	client := &http.Client{CheckRedirect: func(*http.Request, []*http.Request) error {
		return http.ErrUseLastResponse
	}}
	call := func(method, path, body string) {
		req, _ := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
		resp, err := client.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		out := strings.TrimSpace(string(b))
		if loc := resp.Header.Get("Location"); loc != "" {
			out = "-> " + loc
		}
		fmt.Printf("%-4s %-9s %d %s\n", method, path, resp.StatusCode, out)
	}
	call("POST", "/shorten", `{"url":"https://go.dev/doc/effective_go"}`)
	call("POST", "/shorten", `{"url":"https://pkg.go.dev/net/http"}`)
	call("POST", "/shorten", `{"url":"javascript:alert(1)"}`)
	call("POST", "/shorten", `not json`)
	call("GET", "/r/2", "")
	call("GET", "/r/1", "")
	call("GET", "/r/1", "")
	call("GET", "/r/zz", "")
	call("GET", "/stats", "")
	fmt.Println(base62(61), base62(62), base62(3843))
}

