package main

import (
	"cmp"
	"fmt"
	"net/url"
	"slices"
	"strconv"
	"strings"
)

type Movie struct {
	ID    int
	Title string
	Year  int
	Genre string
}

type Filters struct {
	Genre    string
	Sort     string
	Page     int
	PageSize int
}

func readInt(q url.Values, key string, def, lo, hi int, errs map[string]string) int {
	s := q.Get(key)
	if s == "" {
		return def
	}
	n, err := strconv.Atoi(s)
	if err != nil || n < lo || n > hi {
		errs[key] = fmt.Sprintf("must be an integer from %d to %d", lo, hi)
	}
	return n
}

func parseFilters(q url.Values) (Filters, map[string]string) {
	errs := map[string]string{}
	f := Filters{Genre: q.Get("genre"), Sort: cmp.Or(q.Get("sort"), "id")}
	f.Page = readInt(q, "page", 1, 1, 10_000_000, errs)
	f.PageSize = readInt(q, "page_size", 3, 1, 100, errs)
	if !slices.Contains([]string{"id", "title", "year", "-id", "-title", "-year"}, f.Sort) {
		errs["sort"] = "invalid sort value"
	}
	return f, errs
}

func list(all []Movie, f Filters) ([]Movie, string) {
	var out []Movie
	for _, m := range all {
		if f.Genre == "" || m.Genre == f.Genre {
			out = append(out, m)
		}
	}
	key, desc := strings.CutPrefix(f.Sort, "-")
	slices.SortFunc(out, func(a, b Movie) int {
		var c int
		switch key {
		case "title":
			c = cmp.Compare(a.Title, b.Title)
		case "year":
			c = cmp.Compare(a.Year, b.Year)
		}
		if desc {
			c = -c
		}
		return cmp.Or(c, cmp.Compare(a.ID, b.ID)) // tiebreaker
	})
	total := len(out)
	start := min((f.Page-1)*f.PageSize, total)
	end := min(start+f.PageSize, total)
	last := (total + f.PageSize - 1) / f.PageSize
	return out[start:end], fmt.Sprintf("page %d/%d of %d records", f.Page, last, total)
}

func main() {
	movies := []Movie{
		{1, "Casablanca", 1942, "drama"}, {2, "Alien", 1979, "scifi"},
		{3, "Heat", 1995, "crime"}, {4, "Arrival", 2016, "scifi"},
		{5, "Moonlight", 2016, "drama"}, {6, "Dune", 2021, "scifi"},
		{7, "Up", 2009, "family"},
	}
	for _, raw := range []string{"", "sort=-year", "sort=-year&page=2", "genre=scifi&sort=title", "page=0&sort=rating"} {
		q, _ := url.ParseQuery(raw)
		f, errs := parseFilters(q)
		if len(errs) > 0 {
			fmt.Printf("%-25q 422 %v\n", raw, errs)
			continue
		}
		page, meta := list(movies, f)
		var titles []string
		for _, m := range page {
			titles = append(titles, fmt.Sprintf("%s(%d)", m.Title, m.Year))
		}
		fmt.Printf("%-25q %s | %s\n", raw, strings.Join(titles, ", "), meta)
	}
}

package main

import (
	"encoding/json"
	"errors"
	"fmt"
	"strings"
)

type Movie struct {
	Title   string   `json:"title"`
	Year    int      `json:"year"`
	Runtime int      `json:"runtime"`
	Genres  []string `json:"genres"`
}

type moviePatch struct {
	Title   *string  `json:"title"`
	Year    *int     `json:"year"`
	Runtime *int     `json:"runtime"`
	Genres  []string `json:"genres"`
}

func applyPatch(m Movie, body string) (Movie, error) {
	var p moviePatch
	dec := json.NewDecoder(strings.NewReader(body))
	dec.DisallowUnknownFields()
	if err := dec.Decode(&p); err != nil {
		return m, err
	}
	if p.Title != nil {
		m.Title = *p.Title
	}
	if p.Year != nil {
		m.Year = *p.Year
	}
	if p.Runtime != nil {
		m.Runtime = *p.Runtime
	}
	if p.Genres != nil {
		m.Genres = p.Genres
	}
	var errs []error // validate the WHOLE result
	if m.Title == "" {
		errs = append(errs, errors.New("title must be provided"))
	}
	if m.Runtime <= 0 {
		errs = append(errs, errors.New("runtime must be positive"))
	}
	return m, errors.Join(errs...)
}

func main() {
	stored := Movie{"Black Panther", 2018, 134, []string{"action"}}
	for _, body := range []string{
		`{"year": 2019}`,
		`{"genres": ["action", "adventure"], "title": "Black Panther II"}`,
		`{"runtime": 0}`,
		`{"title": ""}`,
		`{"rating": 5}`,
	} {
		m, err := applyPatch(stored, body)
		if err != nil {
			fmt.Printf("%-55s -> rejected: %v\n", body, strings.ReplaceAll(err.Error(), "\n", "; "))
			continue
		}
		fmt.Printf("%-55s -> %+v\n", body, m)
	}
}

