package main

import (
	"errors"
	"fmt"
	"sync"
)

var ErrEditConflict = errors.New("edit conflict")

type Movie struct {
	ID      int
	Title   string
	Version int
}

type Store struct {
	mu     sync.Mutex
	movies map[int]Movie
}

func (s *Store) Get(id int) Movie {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.movies[id]
}

// Update succeeds only if the stored version still matches m.Version.
func (s *Store) Update(m Movie) (Movie, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	cur := s.movies[m.ID]
	if cur.Version != m.Version { // "WHERE version = $3" matched 0 rows
		return Movie{}, ErrEditConflict
	}
	m.Version++
	s.movies[m.ID] = m
	return m, nil
}

func main() {
	s := &Store{movies: map[int]Movie{1: {1, "Heat", 3}}}

	alice := s.Get(1) // both read version 3
	bob := s.Get(1)

	alice.Title = "Heat (1995)"
	fmt.Println(s.Update(alice))

	bob.Title = "HEAT"
	_, err := s.Update(bob)
	fmt.Println("bob:", err, "-> 409 Conflict")

	bob = s.Get(1) // re-read and re-apply
	bob.Title = bob.Title + " [remastered]"
	fmt.Println(s.Update(bob))
}

package main

import (
	"fmt"
	"net/http"
	"net/http/httptest"
	"slices"
)

var trusted = []string{"https://app.example.com", "https://admin.example.com"}

func enableCORS(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Add("Vary", "Origin")
		w.Header().Add("Vary", "Access-Control-Request-Method")
		origin := r.Header.Get("Origin")
		if origin != "" && slices.Contains(trusted, origin) {
			w.Header().Set("Access-Control-Allow-Origin", origin)
			if r.Method == http.MethodOptions && r.Header.Get("Access-Control-Request-Method") != "" {
				w.Header().Set("Access-Control-Allow-Methods", "OPTIONS, PUT, PATCH, DELETE")
				w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
				w.WriteHeader(http.StatusOK) // preflight answered
				return
			}
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	api := http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, `{"status":"ok"}`)
	})
	srv := httptest.NewServer(enableCORS(api))
	defer srv.Close()

	try := func(label, method, origin, reqMethod string) {
		req, _ := http.NewRequest(method, srv.URL, nil)
		req.Header.Set("Origin", origin)
		if reqMethod != "" {
			req.Header.Set("Access-Control-Request-Method", reqMethod)
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		resp.Body.Close()
		fmt.Printf("%-18s %d allow-origin=%q allow-methods=%q\n", label, resp.StatusCode,
			resp.Header.Get("Access-Control-Allow-Origin"), resp.Header.Get("Access-Control-Allow-Methods"))
	}
	try("trusted GET", "GET", "https://app.example.com", "")
	try("trusted preflight", "OPTIONS", "https://app.example.com", "PUT")
	try("unknown origin", "GET", "https://evil.example", "")
}

lessons.concept:
Some work shouldn't block the response: sending a welcome email,
resizing an image, warming a cache (Let's Go Further ch.13).

▸  THE NAIVE VERSION AND ITS PROBLEMS
    go sendWelcomeEmail(user)
    1. A panic in that goroutine CRASHES THE WHOLE SERVER (net/http only
       recovers panics in handler goroutines).
    2. On shutdown, main returns and in-flight emails are lost.
    3. It uses r.Context(), which is cancelled when the response is sent.

▸  A background HELPER
    func (app *application) background(fn func()) {
        app.wg.Add(1)
        go func() {
            defer app.wg.Done()
            defer func() {
                if err := recover(); err != nil {
                    app.logger.Error(fmt.Sprint(err))
                }
            }()
            fn()
        }()
    }
And in graceful shutdown, AFTER srv.Shutdown: app.wg.Wait().

▸  WHEN TO USE A REAL QUEUE
In-process goroutines are lost if the process crashes. Jobs that must
not be lost (payments, important emails) belong in a durable queue (a
database table, Redis, a message broker) processed by workers.

