package main

import (
	"fmt"
	"sort"
	"sync"
	"time"
)

type application struct {
	wg   sync.WaitGroup
	mu   sync.Mutex
	logs []string
}

func (app *application) log(s string) {
	app.mu.Lock()
	app.logs = append(app.logs, s)
	app.mu.Unlock()
}

func (app *application) background(fn func()) {
	app.wg.Add(1)
	go func() {
		defer app.wg.Done()
		defer func() {
			if err := recover(); err != nil {
				app.log(fmt.Sprint("recovered background panic: ", err))
			}
		}()
		fn()
	}()
}

func (app *application) registerUser(email string) string {
	app.background(func() {
		time.Sleep(20 * time.Millisecond) // pretend to talk to an SMTP server
		if email == "bad@example.com" {
			panic("smtp: invalid recipient")
		}
		app.log("welcome email sent to " + email)
	})
	return "201 Created " + email // respond immediately
}

func main() {
	app := &application{}
	start := time.Now()
	fmt.Println(app.registerUser("ada@example.com"))
	fmt.Println(app.registerUser("bad@example.com"))
	fmt.Println("responses sent quickly:", time.Since(start) < 15*time.Millisecond)

	app.wg.Wait() // graceful shutdown: let background work finish
	sort.Strings(app.logs)
	for _, l := range app.logs {
		fmt.Println(l)
	}
	fmt.Println("server still alive after the panic")
}

package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"slices"
	"strings"
)

type User struct {
	Name  string
	Perms []string
}

var anonymous = &User{Name: "anonymous"}

type ctxKey int

const userKey ctxKey = 0

var tokens = map[string]*User{
	"tok-reader": {"reader", []string{"movies:read"}},
	"tok-editor": {"editor", []string{"movies:read", "movies:write"}},
}

func authenticate(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		user := anonymous
		if h := r.Header.Get("Authorization"); h != "" {
			tok, ok := strings.CutPrefix(h, "Bearer ")
			u, found := tokens[tok]
			if !ok || !found {
				w.Header().Set("WWW-Authenticate", "Bearer")
				http.Error(w, "invalid or missing authentication token", http.StatusUnauthorized)
				return
			}
			user = u
		}
		next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), userKey, user)))
	})
}

func requirePermission(perm string, next http.HandlerFunc) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		user := r.Context().Value(userKey).(*User)
		switch {
		case user == anonymous:
			http.Error(w, "you must be authenticated", http.StatusUnauthorized)
		case !slices.Contains(user.Perms, perm):
			http.Error(w, "your account lacks the necessary permissions", http.StatusForbidden)
		default:
			next(w, r)
		}
	}
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/movies", requirePermission("movies:read", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "list of movies")
	}))
	mux.HandleFunc("POST /v1/movies", requirePermission("movies:write", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "movie created")
	}))
	srv := httptest.NewServer(authenticate(mux))
	defer srv.Close()

	for _, c := range [][3]string{
		{"GET", "", "no token"},
		{"GET", "Bearer tok-reader", "reader"},
		{"POST", "Bearer tok-reader", "reader"},
		{"POST", "Bearer tok-editor", "editor"},
		{"GET", "Bearer forged", "forged"},
		{"GET", "Basic dXNlcjpwYXNz", "wrong scheme"},
	} {
		req, _ := http.NewRequest(c[0], srv.URL+"/v1/movies", nil)
		if c[1] != "" {
			req.Header.Set("Authorization", c[1])
		}
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%-4s %-13s %d %s\n", c[0], c[2], resp.StatusCode, strings.TrimSpace(string(b)))
	}
}

package main

import (
	"encoding/json"
	"fmt"
	"io"
	"maps"
	"net/http"
	"net/http/httptest"
	"slices"
	"strconv"
	"strings"
	"sync"
)

type Movie struct {
	ID      int    `json:"id"`
	Title   string `json:"title"`
	Genre   string `json:"genre"`
	Version int    `json:"version"`
}

type envelope map[string]any

type api struct {
	mu     sync.Mutex
	movies map[int]Movie
}

func writeJSON(w http.ResponseWriter, status int, v envelope) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	json.NewEncoder(w).Encode(v)
}

func fail(w http.ResponseWriter, status int, msg any) { writeJSON(w, status, envelope{"error": msg}) }

func (a *api) list(w http.ResponseWriter, r *http.Request) {
	q := r.URL.Query()
	page, err1 := strconv.Atoi(q.Get("page"))
	size, err2 := strconv.Atoi(q.Get("page_size"))
	if q.Get("page") == "" {
		page, err1 = 1, nil
	}
	if q.Get("page_size") == "" {
		size, err2 = 2, nil
	}
	errs := map[string]string{}
	if err1 != nil || page < 1 {
		errs["page"] = "must be a positive integer"
	}
	if err2 != nil || size < 1 || size > 5 {
		errs["page_size"] = "must be between 1 and 5"
	}
	if len(errs) > 0 {
		fail(w, http.StatusUnprocessableEntity, errs)
		return
	}
	a.mu.Lock()
	var out []Movie
	for _, id := range slices.Sorted(maps.Keys(a.movies)) {
		if m := a.movies[id]; q.Get("genre") == "" || m.Genre == q.Get("genre") {
			out = append(out, m)
		}
	}
	a.mu.Unlock()
	total := len(out)
	start := min((page-1)*size, total)
	end := min(start+size, total)
	writeJSON(w, http.StatusOK, envelope{"movies": out[start:end],
		"metadata": map[string]int{"current_page": page, "total_records": total}})
}

func (a *api) show(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.Atoi(r.PathValue("id"))
	a.mu.Lock()
	m, ok := a.movies[id]
	a.mu.Unlock()
	if !ok {
		fail(w, http.StatusNotFound, "the requested resource could not be found")
		return
	}
	writeJSON(w, http.StatusOK, envelope{"movie": m})
}

func (a *api) patch(w http.ResponseWriter, r *http.Request) {
	id, _ := strconv.Atoi(r.PathValue("id"))
	var in struct {
		Title   *string `json:"title"`
		Version int     `json:"version"`
	}
	if err := json.NewDecoder(r.Body).Decode(&in); err != nil {
		fail(w, http.StatusBadRequest, "body must be valid JSON")
		return
	}
	a.mu.Lock()
	defer a.mu.Unlock()
	m, ok := a.movies[id]
	switch {
	case !ok:
		fail(w, http.StatusNotFound, "the requested resource could not be found")
	case m.Version != in.Version:
		fail(w, http.StatusConflict, "edit conflict, please retry")
	default:
		if in.Title != nil {
			m.Title = *in.Title
		}
		m.Version++
		a.movies[id] = m
		writeJSON(w, http.StatusOK, envelope{"movie": m})
	}
}

func main() {
	a := &api{movies: map[int]Movie{
		1: {1, "Alien", "scifi", 1}, 2: {2, "Heat", "crime", 1},
		3: {3, "Dune", "scifi", 1}, 4: {4, "Arrival", "scifi", 1},
	}}
	mux := http.NewServeMux()
	mux.HandleFunc("GET /v1/movies", a.list)
	mux.HandleFunc("GET /v1/movies/{id}", a.show)
	mux.HandleFunc("PATCH /v1/movies/{id}", a.patch)
	srv := httptest.NewServer(mux)
	defer srv.Close()

	call := func(method, path, body string) {
		req, _ := http.NewRequest(method, srv.URL+path, strings.NewReader(body))
		resp, err := http.DefaultClient.Do(req)
		if err != nil {
			panic(err)
		}
		b, _ := io.ReadAll(resp.Body)
		resp.Body.Close()
		fmt.Printf("%s %s -> %d %s\n", method, path, resp.StatusCode, strings.TrimSpace(string(b)))
	}
	call("GET", "/v1/movies", "")
	call("GET", "/v1/movies?genre=scifi&page=2", "")
	call("GET", "/v1/movies?page=0&page_size=9", "")
	call("GET", "/v1/movies/3", "")
	call("PATCH", "/v1/movies/3", `{"title":"Dune: Part One","version":1}`)
	call("PATCH", "/v1/movies/3", `{"title":"Dune 2021","version":1}`)
	call("GET", "/v1/movies/9", "")
}

