	for _, decl := range f.Decls {
		fn, ok := decl.(*ast.FuncDecl)
		if !ok {
			continue
		}
		kind := "func"
		if fn.Recv != nil {
			kind = "method"
		}
		start, end := fset.Position(fn.Pos()), fset.Position(fn.End())
		fmt.Printf("%-6s %-9s exported=%-5v params=%d lines %d-%d doc=%q\n",
			kind, fn.Name.Name, fn.Name.IsExported(), fn.Type.Params.NumFields(),
			start.Line, end.Line, fn.Doc.Text())
	}
	calls := 0
	ast.Inspect(f, func(n ast.Node) bool {
		if _, ok := n.(*ast.CallExpr); ok {
			calls++
		}
		return true
	})
