const src = `package app

import (
	"fmt"
	"os"
)

func cleanup(path string) {
	os.Remove(path)
	fmt.Println("removed", path)
}

func process(items []string) int {
	n := 0
	for _, it := range items {
		if it == "" {
			continue
		}
		n++
		if n > 100 {
			break
		}
	}
	return n
}
`

var mustCheck = map[string]bool{"os.Remove": true, "os.Close": true, "os.WriteFile": true}

func main() {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "app.go", src, 0)
	report := func(n ast.Node, msg string) {
		fmt.Printf("%s: %s\n", fset.Position(n.Pos()), msg)
	}
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.ExprStmt: // a call whose results are thrown away
			if call, ok := n.X.(*ast.CallExpr); ok {
				if sel, ok := call.Fun.(*ast.SelectorExpr); ok {
					if pkg, ok := sel.X.(*ast.Ident); ok {
						name := pkg.Name + "." + sel.Sel.Name
						if mustCheck[name] {
							report(n, name+" error is ignored")
						}
						if name == "fmt.Println" {
							report(n, "debug print left in code")
						}
					}
				}
			}
		case *ast.FuncDecl:
			lines := fset.Position(n.End()).Line - fset.Position(n.Pos()).Line
			if lines > 10 {
				report(n, fmt.Sprintf("function %s is %d lines long", n.Name.Name, lines))
			}
		}
		return true
	})
}

