const src = `package demo

import "fmt"

// GetUserName returns the name. "GetUserName" in strings is untouched.
func GetUserName(id int) string { return fmt.Sprint("user-",id) }

func main(){fmt.Println(GetUserName(7), "GetUserName")
}
`

func main() {
	fset := token.NewFileSet()
	f, err := parser.ParseFile(fset, "demo.go", src, parser.ParseComments)
	if err != nil {
		fmt.Println(err)
		return
	}
	renamed := 0
	ast.Inspect(f, func(n ast.Node) bool {
		switch n := n.(type) {
		case *ast.Ident:
			if n.Name == "GetUserName" { // identifiers only: not strings or comments
				n.Name = "UserName"
				renamed++
			}
		case *ast.BasicLit:
			if n.Kind == token.INT {
				v, _ := strconv.Atoi(n.Value)
				n.Value = strconv.Itoa(v * 6) // rewrite a literal too
			}
		}
		return true
	})
	var buf bytes.Buffer
	format.Node(&buf, fset, f)
	fmt.Print(buf.String())
	fmt.Println("// identifiers renamed:", renamed)
}

