package main

import (
	"fmt"
	"go/ast"
	"go/parser"
	"go/token"
	"go/types"
	"sort"
)

const src = `package calc

const Big = 1 << 40

type Celsius float64

func half(x Celsius) Celsius { return x / 2 }

var ratio = 3 / 2.0
var temp = half(100)
var bad int = "oops"
`

func main() {
	fset := token.NewFileSet()
	f, _ := parser.ParseFile(fset, "calc.go", src, 0)

	var errs []string
	conf := types.Config{Error: func(err error) { errs = append(errs, err.Error()) }}
	info := &types.Info{Types: map[ast.Expr]types.TypeAndValue{}, Defs: map[*ast.Ident]types.Object{}}
	pkg, _ := conf.Check("calc", fset, []*ast.File{f}, info)

	fmt.Println("errors:", errs)
	var names []string
	for id, obj := range info.Defs {
		if obj != nil && obj.Parent() == pkg.Scope() {
			names = append(names, fmt.Sprintf("%s: %s", id.Name, obj.Type()))
		}
	}
	sort.Strings(names)
	for _, n := range names {
		fmt.Println(" ", n)
	}
	big := pkg.Scope().Lookup("Big").(*types.Const)
	fmt.Println("Big =", big.Val())
}

package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"strings"
	"sync/atomic"
	"time"
)

type app struct {
	ready  atomic.Bool
	dbPing func(context.Context) error
}

func (a *app) routes() http.Handler {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /livez", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprint(w, "ok") // no dependencies here
	})
	mux.HandleFunc("GET /readyz", func(w http.ResponseWriter, r *http.Request) {
		if !a.ready.Load() {
			http.Error(w, "not ready", http.StatusServiceUnavailable)
			return
		}
		ctx, cancel := context.WithTimeout(r.Context(), 200*time.Millisecond)
		defer cancel()
		if err := a.dbPing(ctx); err != nil {
			http.Error(w, "dependency unavailable", http.StatusServiceUnavailable)
			return
		}
		fmt.Fprint(w, "ready")
	})
	return mux
}

func main() {
	var dbDown atomic.Bool // shared with handler goroutines: must be synchronised
	a := &app{dbPing: func(context.Context) error {
		if dbDown.Load() {
			return errors.New("connection refused")
		}
		return nil
	}}
	srv := httptest.NewServer(a.routes())
	defer srv.Close()
	probe := func(stage string) {
		var parts []string
		for _, p := range []string{"/livez", "/readyz"} {
			resp, err := http.Get(srv.URL + p)
			if err != nil {
				panic(err)
			}
			b, _ := io.ReadAll(resp.Body)
			resp.Body.Close()
			parts = append(parts, fmt.Sprintf("%s=%d(%s)", p, resp.StatusCode, strings.TrimSpace(string(b))))
		}
		fmt.Printf("%-16s %s %s\n", stage, parts[0], parts[1])
	}
	probe("starting up")
	a.ready.Store(true)
	probe("serving")
	dbDown.Store(true)
	probe("db outage")
	dbDown.Store(false)
	a.ready.Store(false) // SIGTERM received: drain first
	probe("shutting down")
}

package main

import (
	"encoding/json"
	"expvar"
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"time"
)

var (
	totalRequests  = expvar.NewInt("total_requests")
	totalErrors    = expvar.NewInt("total_errors")
	statusCounts   = expvar.NewMap("responses_by_status")
	processingTime = expvar.NewInt("total_processing_time_us")
)

type statusRecorder struct {
	http.ResponseWriter
	status int
}

func (s *statusRecorder) WriteHeader(code int) { s.status = code; s.ResponseWriter.WriteHeader(code) }

func metrics(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		rec := &statusRecorder{w, http.StatusOK}
		next.ServeHTTP(rec, r)
		totalRequests.Add(1)
		statusCounts.Add(fmt.Sprint(rec.status), 1)
		if rec.status >= 500 {
			totalErrors.Add(1)
		}
		processingTime.Add(time.Since(start).Microseconds())
	})
}

func main() {
	app := http.NewServeMux()
	app.HandleFunc("GET /ok", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") })
	app.HandleFunc("GET /fail", func(w http.ResponseWriter, r *http.Request) { http.Error(w, "boom", 500) })
	srv := httptest.NewServer(metrics(app))
	defer srv.Close()
	admin := httptest.NewServer(expvar.Handler()) // internal-only port
	defer admin.Close()

	for _, p := range []string{"/ok", "/ok", "/fail", "/nope", "/ok"} {
		resp, _ := http.Get(srv.URL + p)
		resp.Body.Close()
	}
	resp, _ := http.Get(admin.URL)
	body, _ := io.ReadAll(resp.Body)
	resp.Body.Close()
	var vars map[string]json.RawMessage
	json.Unmarshal(body, &vars)
	for _, k := range []string{"total_requests", "total_errors", "responses_by_status"} {
		fmt.Println(k, string(vars[k]))
	}
	_, hasMem := vars["memstats"]
	fmt.Println("runtime memstats published too:", hasMem)
}

package main

import (
	"context"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"log/slog"
	"net/http"
	"net/http/httptest"
	"strings"
)

type ctxKey int

const loggerKey ctxKey = 0

func loggerFrom(ctx context.Context) *slog.Logger {
	if l, ok := ctx.Value(loggerKey).(*slog.Logger); ok {
		return l
	}
	return slog.Default()
}

func requestID(base *slog.Logger) func(http.Handler) http.Handler {
	return func(next http.Handler) http.Handler {
		return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			id := r.Header.Get("X-Request-ID")
			if id == "" {
				b := make([]byte, 8)
				rand.Read(b)
				id = hex.EncodeToString(b)
			}
			w.Header().Set("X-Request-ID", id)
			l := base.With("request_id", id)
			next.ServeHTTP(w, r.WithContext(context.WithValue(r.Context(), loggerKey, l)))
		})
	}
}

func chargeCard(ctx context.Context, cents int) {
	loggerFrom(ctx).Info("charging card", "cents", cents) // a library sees the same id
}

func checkout(w http.ResponseWriter, r *http.Request) {
	log := loggerFrom(r.Context())
	log.Info("checkout started", "user", "ada")
	chargeCard(r.Context(), 4999)
	log.Info("checkout finished")
}

func main() {
	var out strings.Builder
	base := slog.New(slog.NewTextHandler(&out, &slog.HandlerOptions{
		ReplaceAttr: func(_ []string, a slog.Attr) slog.Attr {
			if a.Key == slog.TimeKey {
				return slog.Attr{}
			}
			return a
		}}))
	srv := httptest.NewServer(requestID(base)(http.HandlerFunc(checkout)))
	defer srv.Close()

	req, _ := http.NewRequest("POST", srv.URL, nil)
	req.Header.Set("X-Request-ID", "req-7f3a")
	resp, _ := http.DefaultClient.Do(req)
	resp.Body.Close()
	fmt.Println("response header:", resp.Header.Get("X-Request-ID"))

	resp, _ = http.Post(srv.URL, "text/plain", nil)
	resp.Body.Close()
	fmt.Println("generated id length:", len(resp.Header.Get("X-Request-ID")))
	for _, line := range strings.Split(strings.TrimSpace(out.String()), "\n")[:3] {
		fmt.Println(line)
	}
}

