import (
	"context"
	"errors"
	"fmt"
	"sync"
	"time"
)

type Worker struct {
	name     string
	interval time.Duration
	job      func(context.Context, int) error
}

func (w *Worker) Run(ctx context.Context) error {
	t := time.NewTicker(w.interval)
	defer t.Stop()
	for run := 1; ; run++ {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-t.C:
			func() {
				defer func() {
					if r := recover(); r != nil {
						fmt.Printf("%s run %d panicked: %v (worker keeps going)\n", w.name, run, r)
					}
				}()
				if err := w.job(ctx, run); err != nil {
					fmt.Printf("%s run %d failed: %v\n", w.name, run, err)
					return
				}
				fmt.Printf("%s run %d ok\n", w.name, run)
			}()
		}
	}
}

func main() {
	ctx, stop := context.WithCancel(context.Background())
	fourthRun := make(chan struct{})
	w := &Worker{name: "purge-sessions", interval: 15 * time.Millisecond,
		job: func(ctx context.Context, run int) error {
			switch run {
			case 4:
				close(fourthRun)
			case 2:
				return errors.New("db timeout")
			case 3:
				panic("nil map")
			}
			return nil
		}}

	var wg sync.WaitGroup
	wg.Add(1)
	go func() {
		defer wg.Done()
		fmt.Println("worker stopped:", w.Run(ctx))
	}()
	<-fourthRun // the server runs for a while...
	stop()      // ...then SIGTERM: cancel the root context
	wg.Wait()
}

