import (
	"fmt"
	"strings"
)

type List[T any] struct{ items []T }

func (l *List[T]) Push(vs ...T) { l.items = append(l.items, vs...) }
func (l *List[T]) Len() int     { return len(l.items) }

func (l *List[T]) First() (T, bool) {
	if len(l.items) == 0 {
		var zero T
		return zero, false
	}
	return l.items[0], true
}

func (l *List[T]) Filter(keep func(T) bool) *List[T] { // same T: allowed
	out := &List[T]{}
	for _, v := range l.items {
		if keep(v) {
			out.Push(v)
		}
	}
	return out
}

// Map needs a NEW type parameter U, so it must be a function, not a method.
func Map[T, U any](l *List[T], f func(T) U) *List[U] {
	out := &List[U]{}
	for _, v := range l.items {
		out.Push(f(v))
	}
	return out
}

func main() {
	words := &List[string]{}
	words.Push("go", "generics", "are", "great")
	long := words.Filter(func(s string) bool { return len(s) > 2 })
	lengths := Map(long, func(s string) int { return len(s) })
	upper := Map(long, strings.ToUpper)
	fmt.Println(long.items, lengths.items, upper.items)

	var empty List[float64]
	v, ok := empty.First()
	fmt.Println(v, ok)
	fmt.Printf("%T %T\n", words, lengths)
}

