import (
	"fmt"
	"strconv"
)

type Enum interface {
	~int | ~uint8
	String() string
}

type Weekday int

const (
	Sun Weekday = iota
	Mon
	Tue
)

func (d Weekday) String() string { return [...]string{"Sun", "Mon", "Tue"}[d] }

type Level uint8

func (l Level) String() string { return "L" + strconv.Itoa(int(l)) }

// Describe uses BOTH the type set (conversion to int, +) and the method.
func Describe[E Enum](vals []E) []string {
	var out []string
	for _, v := range vals {
		out = append(out, fmt.Sprintf("%s=%d", v.String(), int(v)+0))
	}
	return out
}

func Sum[T ~int | ~float64](xs []T) T {
	var total T
	for _, x := range xs {
		total += x
	}
	return total
}

func main() {
	fmt.Println(Describe([]Weekday{Sun, Tue}))
	fmt.Println(Describe([]Level{3, 7}))
	fmt.Println(Sum([]int{1, 2, 3}), Sum([]float64{0.5, 0.25}), Sum([]Weekday{Mon, Mon})) // Weekday + Weekday is a Weekday
	// Describe([]int{1}) would not compile: int has no String method
}

