import (
	"fmt"
	"iter"
	"maps"
	"slices"
	"strings"
)

type OrderedMap[K comparable, V any] struct {
	keys []K
	vals map[K]V
}

func New[K comparable, V any]() *OrderedMap[K, V] {
	return &OrderedMap[K, V]{vals: map[K]V{}}
}

func (m *OrderedMap[K, V]) Set(k K, v V) {
	if _, ok := m.vals[k]; !ok {
		m.keys = append(m.keys, k)
	}
	m.vals[k] = v
}

func (m *OrderedMap[K, V]) Delete(k K) {
	if _, ok := m.vals[k]; !ok {
		return
	}
	delete(m.vals, k)
	m.keys = slices.DeleteFunc(m.keys, func(x K) bool { return x == k })
}

func (m *OrderedMap[K, V]) All() iter.Seq2[K, V] {
	return func(yield func(K, V) bool) {
		for _, k := range m.keys {
			if !yield(k, m.vals[k]) {
				return
			}
		}
	}
}

func (m *OrderedMap[K, V]) Keys() iter.Seq[K] {
	return func(yield func(K) bool) {
		for k := range m.All() {
			if !yield(k) {
				return
			}
		}
	}
}

func main() {
	m := New[string, int]()
	for _, w := range []string{"zebra", "apple", "mango", "apple"} {
		m.Set(w, len(w))
	}
	m.Delete("mango")
	m.Set("kiwi", 4)
	var parts []string
	for k, v := range m.All() {
		parts = append(parts, fmt.Sprint(k, "=", v))
	}
	fmt.Println(strings.Join(parts, "; "))
	fmt.Println(slices.Collect(m.Keys()))
	copied := maps.Collect(m.All())
	fmt.Println(len(copied), copied["kiwi"])
	for k := range m.Keys() {
		fmt.Println("first key:", k)
		break // early exit works
	}
}

