import (
	"context"
	"errors"
	"fmt"
	"strings"
	"sync"
)

func ParallelMap[T, R any](ctx context.Context, in []T, workers int,
	f func(context.Context, T) (R, error)) ([]R, error) {
	ctx, cancel := context.WithCancelCause(ctx)
	defer cancel(nil)
	out := make([]R, len(in))
	idx := make(chan int)
	var wg sync.WaitGroup
	for range workers {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for i := range idx {
				r, err := f(ctx, in[i])
				if err != nil {
					cancel(fmt.Errorf("item %d: %w", i, err))
					continue
				}
				out[i] = r // each index written by exactly one worker
			}
		}()
	}
feed:
	for i := range in {
		select {
		case idx <- i:
		case <-ctx.Done():
			break feed
		}
	}
	close(idx)
	wg.Wait()
	if err := context.Cause(ctx); err != nil {
		return nil, err
	}
	return out, nil
}

func main() {
	ctx := context.Background()
	words := []string{"alpha", "beta", "gamma", "delta", "epsilon"}
	upper, err := ParallelMap(ctx, words, 3, func(_ context.Context, s string) (string, error) {
		return strings.ToUpper(s), nil
	})
	fmt.Println(upper, err)

	lengths, err := ParallelMap(ctx, words, 2, func(_ context.Context, s string) (int, error) {
		return len(s), nil
	})
	fmt.Println(lengths, err)

	_, err = ParallelMap(ctx, []int{1, 2, -3, 4}, 2, func(_ context.Context, n int) (int, error) {
		if n < 0 {
			return 0, errors.New("negative input")
		}
		return n * n, nil
	})
	fmt.Println(err)
}

