import (
	"fmt"
	"reflect"
	"sort"
)

func display(path string, v reflect.Value, depth int) {
	if depth > 5 {
		fmt.Printf("%s = ... (too deep)\n", path)
		return
	}
	switch v.Kind() {
	case reflect.Invalid:
		fmt.Printf("%s = invalid\n", path)
	case reflect.Slice, reflect.Array:
		for i := range v.Len() {
			display(fmt.Sprintf("%s[%d]", path, i), v.Index(i), depth+1)
		}
	case reflect.Struct:
		for i := range v.NumField() {
			display(path+"."+v.Type().Field(i).Name, v.Field(i), depth+1)
		}
	case reflect.Map:
		keys := v.MapKeys()
		sort.Slice(keys, func(i, j int) bool { return fmt.Sprint(keys[i]) < fmt.Sprint(keys[j]) })
		for _, k := range keys {
			display(fmt.Sprintf("%s[%v]", path, k), v.MapIndex(k), depth+1)
		}
	case reflect.Pointer:
		if v.IsNil() {
			fmt.Printf("%s = nil\n", path)
			return
		}
		display("(*"+path+")", v.Elem(), depth+1)
	case reflect.Interface:
		if v.IsNil() {
			fmt.Printf("%s = nil\n", path)
			return
		}
		fmt.Printf("%s.type = %s\n", path, v.Elem().Type())
		display(path+".value", v.Elem(), depth+1)
	default:
		fmt.Printf("%s = %v\n", path, v)
	}
}

