package main

import (
	"errors"
	"fmt"
	"reflect"
	"strconv"
	"strings"
	"time"
)

type Config struct {
	Port    int           `env:"PORT" default:"8080"`
	Debug   bool          `env:"DEBUG"`
	Timeout time.Duration `env:"TIMEOUT" default:"5s"`
	Hosts   []string      `env:"HOSTS"`
	secret  string        `env:"SECRET"`
}

var durationType = reflect.TypeOf(time.Duration(0))

func load(dst any, env map[string]string) error {
	v := reflect.ValueOf(dst)
	if v.Kind() != reflect.Pointer || v.Elem().Kind() != reflect.Struct {
		return errors.New("load: need a pointer to a struct")
	}
	v = v.Elem()
	var errs []error
	for i := range v.NumField() {
		f, fv := v.Type().Field(i), v.Field(i)
		key, ok := f.Tag.Lookup("env")
		if !ok {
			continue
		}
		raw, found := env[key]
		if !found {
			raw = f.Tag.Get("default")
		}
		if raw == "" {
			continue
		}
		if !fv.CanSet() {
			errs = append(errs, fmt.Errorf("%s: unexported field cannot be set", f.Name))
			continue
		}
		var err error
		switch {
		case f.Type == durationType: // check before Kind: Duration is an int64
			var d time.Duration
			d, err = time.ParseDuration(raw)
			fv.SetInt(int64(d))
		case f.Type.Kind() == reflect.Int:
			var n int
			n, err = strconv.Atoi(raw)
			fv.SetInt(int64(n))
		case f.Type.Kind() == reflect.Bool:
			var b bool
			b, err = strconv.ParseBool(raw)
			fv.SetBool(b)
		case f.Type.Kind() == reflect.Slice && f.Type.Elem().Kind() == reflect.String:
			fv.Set(reflect.ValueOf(strings.Split(raw, ",")))
		default:
			err = fmt.Errorf("unsupported type %s", f.Type)
		}
		if err != nil {
			errs = append(errs, fmt.Errorf("%s (%s=%q): %w", f.Name, key, raw, err))
		}
	}
	return errors.Join(errs...)
}

func main() {
	var c Config
	err := load(&c, map[string]string{"DEBUG": "true", "HOSTS": "a.example,b.example"})
	fmt.Printf("%+v %v\n", c, err)

	var c2 Config
	err = load(&c2, map[string]string{"PORT": "eighty", "TIMEOUT": "fast", "SECRET": "x"})
	fmt.Println(err)
	fmt.Println(load(c2, nil))
}

package main

import (
	"fmt"
	"reflect"
	"sort"
	"strings"
)

type Shell struct{ cwd string }

func (s *Shell) Pwd() string              { return s.cwd }
func (s *Shell) Cd(dir string) string     { s.cwd = dir; return "ok" }
func (s *Shell) Echo(words string) string { return words }
func (s Shell) Help() string              { return "commands: cd, echo, help, pwd" }
func (s *Shell) internal()                {}

// dispatch maps a command line onto a method: "cd /tmp" -> s.Cd("/tmp").
func dispatch(target any, line string) string {
	name, arg, _ := strings.Cut(line, " ")
	m := reflect.ValueOf(target).MethodByName(strings.ToUpper(name[:1]) + name[1:])
	if !m.IsValid() {
		return "unknown command: " + name
	}
	var args []reflect.Value
	if m.Type().NumIn() == 1 {
		args = append(args, reflect.ValueOf(arg))
	}
	return m.Call(args)[0].String()
}

func main() {
	sh := &Shell{cwd: "/home/ada"}
	var names []string
	t := reflect.TypeOf(sh)
	for i := range t.NumMethod() {
		names = append(names, t.Method(i).Name)
	}
	sort.Strings(names)
	fmt.Println("pointer method set:", names)
	fmt.Println("value method set:", reflect.TypeOf(*sh).NumMethod(), "method(s)")

	for _, line := range []string{"pwd", "cd /tmp", "pwd", "echo hello reflect", "help", "rm -rf /"} {
		fmt.Printf("$ %-18s %s\n", line, dispatch(sh, line))
	}
}

