import (
	"fmt"
	"iter"
	"maps"
	"slices"
	"sync"
)

type Entity interface {
	comparable
	GetID() int
}

type Repo[T Entity] struct {
	mu    sync.RWMutex
	items map[int]T
}

func NewRepo[T Entity]() *Repo[T] { return &Repo[T]{items: map[int]T{}} }

func (r *Repo[T]) Save(v T) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.items[v.GetID()] = v
}

func (r *Repo[T]) Get(id int) (T, bool) {
	r.mu.RLock()
	defer r.mu.RUnlock()
	v, ok := r.items[id]
	return v, ok
}

func (r *Repo[T]) Delete(id int) bool {
	r.mu.Lock()
	defer r.mu.Unlock()
	_, ok := r.items[id]
	delete(r.items, id)
	return ok
}

func (r *Repo[T]) snapshot() []T {
	r.mu.RLock()
	defer r.mu.RUnlock()
	out := make([]T, 0, len(r.items))
	for _, id := range slices.Sorted(maps.Keys(r.items)) {
		out = append(out, r.items[id])
	}
	return out
}

func (r *Repo[T]) Find(pred func(T) bool) []T {
	var out []T
	for _, v := range r.snapshot() {
		if pred(v) {
			out = append(out, v)
		}
	}
	return out
}

func (r *Repo[T]) All() iter.Seq[T] {
	return func(yield func(T) bool) {
		for _, v := range r.snapshot() { // no lock held while yielding
			if !yield(v) {
				return
			}
		}
	}
}

