import (
	"bytes"
	"encoding/binary"
	"fmt"
	"io"
	"os"
	"sync"
)

type Record struct {
	ID    uint32
	Score int32
	Name  [8]byte
}

const recSize = 16 // 4 + 4 + 8 bytes

func main() {
	f, _ := os.CreateTemp("", "records-*.bin")
	defer os.Remove(f.Name())
	defer f.Close()

	for i, name := range []string{"ada", "bob", "cy", "dee", "eve"} {
		r := Record{ID: uint32(100 + i), Score: int32(i*i - 3)}
		copy(r.Name[:], name)
		binary.Write(f, binary.LittleEndian, r)
	}
	info, _ := f.Stat()
	fmt.Println("file size:", info.Size(), "records:", info.Size()/recSize)

	readRec := func(i int64) Record {
		buf := make([]byte, recSize)
		f.ReadAt(buf, i*recSize) // no shared offset: concurrency safe
		var r Record
		binary.Read(bytes.NewReader(buf), binary.LittleEndian, &r)
		return r
	}
	r := readRec(3)
	fmt.Println(r.ID, r.Score, string(bytes.TrimRight(r.Name[:], "\x00")))

	// Many goroutines reading different records at once.
	scores := make([]int32, 5)
	var wg sync.WaitGroup
	for i := range 5 {
		wg.Add(1)
		go func() { defer wg.Done(); scores[i] = readRec(int64(i)).Score }()
	}
	wg.Wait()
	fmt.Println(scores)

	// A SectionReader over records 1..2 behaves like its own small file.
	sec := io.NewSectionReader(f, 1*recSize, 2*recSize)
	data, _ := io.ReadAll(sec)
	fmt.Println(len(data), sec.Size())

	// Seek to the last record and overwrite its score in place.
	f.Seek(-recSize+4, io.SeekEnd)
	binary.Write(f, binary.LittleEndian, int32(99))
	fmt.Println(readRec(4).Score)
}

