import (
	"archive/tar"
	"archive/zip"
	"bytes"
	"compress/gzip"
	"errors"
	"fmt"
	"io"
	"io/fs"
	"path/filepath"
	"strings"
)

func main() {
	files := map[string]string{
		"README.md":   strings.Repeat("Go archives are easy. ", 40),
		"src/main.go": "package main\n",
	}
	order := []string{"README.md", "src/main.go"}

	// ---- zip ----
	var zbuf bytes.Buffer
	zw := zip.NewWriter(&zbuf)
	for _, name := range order {
		w, _ := zw.Create(name)
		io.WriteString(w, files[name])
	}
	zw.Close() // forgetting this produces a corrupt archive

	zr, _ := zip.NewReader(bytes.NewReader(zbuf.Bytes()), int64(zbuf.Len()))
	for _, f := range zr.File { // tiny files can GROW when compressed
		fmt.Printf("zip %-12s %4d -> %3d bytes\n", f.Name, f.UncompressedSize64, f.CompressedSize64)
	}
	b, _ := fs.ReadFile(zr, "src/main.go") // zip.Reader is an fs.FS
	fmt.Printf("%q\n", b)

	// ---- tar.gz ----
	var tbuf bytes.Buffer
	gz := gzip.NewWriter(&tbuf)
	tw := tar.NewWriter(gz)
	for _, name := range append(order, "../../etc/evil") {
		body := files[name]
		tw.WriteHeader(&tar.Header{Name: name, Mode: 0o644, Size: int64(len(body))})
		io.WriteString(tw, body)
	}
	tw.Close() // inner writer first
	gz.Close()

	gr, _ := gzip.NewReader(&tbuf)
	tr := tar.NewReader(gr)
	for {
		h, err := tr.Next()
		if errors.Is(err, io.EOF) {
			break
		}
		if !filepath.IsLocal(h.Name) { // zip-slip guard
			fmt.Println("REJECTED unsafe path:", h.Name)
			continue
		}
		n, _ := io.Copy(io.Discard, tr)
		fmt.Println("tar", h.Name, n)
	}
}

