// countWords works on ANY filesystem: disk, embed, zip, or in-memory.
func countWords(fsys fs.FS, pattern string) (map[string]int, error) {
	matches, err := fs.Glob(fsys, pattern)
	if err != nil {
		return nil, err
	}
	out := map[string]int{}
	for _, m := range matches {
		b, err := fs.ReadFile(fsys, m)
		if err != nil {
			return nil, err
		}
		out[m] = len(strings.Fields(string(b)))
	}
	return out, nil
}

func main() {
	fsys := fstest.MapFS{
		"docs/intro.md":     {Data: []byte("Go is a small language")},
		"docs/advanced.md":  {Data: []byte("generics iterators and more")},
		"docs/img/logo.png": {Data: []byte{0x89, 'P', 'N', 'G'}},
		"main.go":           {Data: []byte("package main")},
	}
	counts, _ := countWords(fsys, "docs/*.md")
	fmt.Println(counts)

	docs, _ := fs.Sub(fsys, "docs")
	fs.WalkDir(docs, ".", func(p string, d fs.DirEntry, err error) error {
		if !d.IsDir() {
			info, _ := d.Info()
			fmt.Println(p, info.Size())
