import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"path/filepath"
)

// WriteFileAtomic replaces path with data so readers see either the old
// or the new content, never a mixture - even if we crash halfway.
func WriteFileAtomic(path string, data []byte, write func(*bufio.Writer, []byte) error) (err error) {
	tmp, err := os.CreateTemp(filepath.Dir(path), "."+filepath.Base(path)+".tmp-*")
	if err != nil {
		return err
	}
	defer func() {
		if err != nil {
			tmp.Close()
			os.Remove(tmp.Name()) // never leave temp files behind
		}
	}()
	bw := bufio.NewWriter(tmp)
	if err = write(bw, data); err != nil {
		return err
	}
	if err = bw.Flush(); err != nil { // forgetting Flush loses the tail
		return err
	}
	if err = tmp.Sync(); err != nil {
		return err
	}
	if err = tmp.Close(); err != nil {
		return err
	}
	return os.Rename(tmp.Name(), path)
}

func plain(w *bufio.Writer, b []byte) error { _, err := w.Write(b); return err }

func failing(w *bufio.Writer, b []byte) error {
	w.Write(b[:3])
	return errors.New("simulated crash while writing")
}

func main() {
	dir, _ := os.MkdirTemp("", "atomic-*")
	defer os.RemoveAll(dir)
	cfg := filepath.Join(dir, "config.json")

	fmt.Println(WriteFileAtomic(cfg, []byte(`{"version":1}`), plain))
	b, _ := os.ReadFile(cfg)
	fmt.Println(string(b))

	err := WriteFileAtomic(cfg, []byte(`{"version":2}`), failing)
	fmt.Println("error:", err)
	b, _ = os.ReadFile(cfg)
	fmt.Println("after failure:", string(b)) // old content intact

	entries, _ := os.ReadDir(dir)
	fmt.Println("files in dir:", len(entries))

	// The lost-tail bug: buffered data never flushed.
	f, _ := os.Create(filepath.Join(dir, "lost.txt"))
	w := bufio.NewWriter(f)
	fmt.Fprint(w, "this text stays in the buffer")
	f.Close() // no w.Flush()!
	info, _ := os.Stat(f.Name())
	fmt.Println("lost.txt size:", info.Size())
}

