import (
	"encoding/binary"
	"fmt"
	"io/fs"
	"testing/fstest"
)

func Pack(fsys fs.FS) ([]byte, error) {
	var out []byte
	err := fs.WalkDir(fsys, ".", func(p string, d fs.DirEntry, err error) error {
		if err != nil || !d.Type().IsRegular() {
			return err
		}
		data, err := fs.ReadFile(fsys, p)
		if err != nil {
			return err
		}
		out = binary.BigEndian.AppendUint16(out, uint16(len(p)))
		out = append(out, p...)
		out = binary.BigEndian.AppendUint32(out, uint32(len(data)))
		out = append(out, data...)
		return nil
	})
	return out, err
}

func Unpack(b []byte) (fstest.MapFS, error) {
	out := fstest.MapFS{}
	take := func(n int) ([]byte, error) {
		if len(b) < n {
			return nil, fmt.Errorf("truncated: need %d bytes, have %d", n, len(b))
		}
		chunk := b[:n]
		b = b[n:]
		return chunk, nil
	}
	for len(b) > 0 {
		h, err := take(2)
		if err != nil {
			return nil, err
		}
		name, err := take(int(binary.BigEndian.Uint16(h)))
		if err != nil {
			return nil, err
		}
		if !fs.ValidPath(string(name)) {
			return nil, fmt.Errorf("invalid name %q", name)
		}
		h, err = take(4)
		if err != nil {
			return nil, err
		}
		data, err := take(int(binary.BigEndian.Uint32(h)))
		if err != nil {
			return nil, err
		}
		out[string(name)] = &fstest.MapFile{Data: data}
	}
	return out, nil
}

func main() {
	src := fstest.MapFS{
		"a.txt":       {Data: []byte("alpha")},
		"dir/b.txt":   {Data: []byte("bravo!")},
		"dir/c/d.txt": {Data: []byte("")},
	}
	packed, _ := Pack(src)
	fmt.Println("packed bytes:", len(packed))

	back, err := Unpack(packed)
	fmt.Println(err, len(back))
	for _, name := range []string{"a.txt", "dir/b.txt", "dir/c/d.txt"} {
		b, _ := fs.ReadFile(back, name)
		fmt.Printf("%s=%q\n", name, b)
	}

	_, err = Unpack(packed[:len(packed)-3])
	fmt.Println(err)

	evil := binary.BigEndian.AppendUint16(nil, 6)
	evil = append(evil, "../etc"...)
	evil = binary.BigEndian.AppendUint32(evil, 0)
	_, err = Unpack(evil)
	fmt.Println(err)
}

