import (
	"fmt"
	"unicode"
)

func PairSum(a []int, target int) (int, int, bool) {
	i, j := 0, len(a)-1
	for i < j {
		switch s := a[i] + a[j]; {
		case s == target:
			return i, j, true
		case s < target:
			i++
		default:
			j--
		}
	}
	return -1, -1, false
}

func Dedup(a []int) []int {
	if len(a) == 0 {
		return a
	}
	w := 1
	for r := 1; r < len(a); r++ {
		if a[r] != a[w-1] {
			a[w] = a[r]
			w++
		}
	}
	return a[:w]
}

func IsPalindrome(s string) bool {
	r := []rune(s)
	i, j := 0, len(r)-1
	for i < j {
		if !unicode.IsLetter(r[i]) {
			i++
			continue
		}
		if !unicode.IsLetter(r[j]) {
			j--
			continue
		}
		if unicode.ToLower(r[i]) != unicode.ToLower(r[j]) {
			return false
		}
		i++
		j--
	}
	return true
}

func main() {
	a := []int{1, 3, 4, 6, 8, 11}
	for _, t := range []int{10, 14, 2} {
		fmt.Println(PairSum(a, t))
	}
	fmt.Println(Dedup([]int{1, 1, 2, 3, 3, 3, 7, 7}))
	fmt.Println(IsPalindrome("A man, a plan, a canal: Panama"), IsPalindrome("Gopher"))
}

