import "fmt"

func MaxWindowSum(a []int, k int) int {
	sum, best := 0, 0
	for r, v := range a {
		sum += v
		if r >= k {
			sum -= a[r-k]
		}
		if r >= k-1 && (r == k-1 || sum > best) {
			best = sum
		}
	}
	return best
}

func LongestUnique(s string) (int, string) {
	last := map[byte]int{}
	left, best, start := 0, 0, 0
	for r := 0; r < len(s); r++ {
		if p, ok := last[s[r]]; ok && p >= left {
			left = p + 1
		}
		last[s[r]] = r
		if r-left+1 > best {
			best, start = r-left+1, left
		}
	}
	return best, s[start : start+best]
}

func main() {
	fmt.Println(MaxWindowSum([]int{2, 1, 5, 1, 3, 2, 9, 1}, 3))
	for _, s := range []string{"abcabcbb", "bbbbb", "pwwkew"} {
		fmt.Println(LongestUnique(s))
	}
}

