import "fmt"

func Prefix(a []int) []int {
	p := make([]int, len(a)+1)
	for i, v := range a {
		p[i+1] = p[i] + v
	}
	return p
}

func CountSubarrays(a []int, k int) int {
	seen := map[int]int{0: 1}
	cur, count := 0, 0
	for _, v := range a {
		cur += v
		count += seen[cur-k]
		seen[cur]++
	}
	return count
}

func main() {
