	rangeSum := func(l, r int) int { return p[r+1] - p[l] }
	fmt.Println(rangeSum(0, 2), rangeSum(2, 5), rangeSum(0, 6))
	fmt.Println(CountSubarrays([]int{1, 2, 3, -2, 2, 1}, 3), CountSubarrays([]int{1, 1, 1}, 2))
}

