import "fmt"

func Balanced(s string) bool {
	pairs := map[rune]rune{')': '(', ']': '[', '}': '{'}
	var st []rune
	for _, c := range s {
		switch c {
		case '(', '[', '{':
			st = append(st, c)
		case ')', ']', '}':
			if len(st) == 0 || st[len(st)-1] != pairs[c] {
				return false
			}
			st = st[:len(st)-1]
		}
	}
	return len(st) == 0
}

func NextGreater(a []int) []int {
	res := make([]int, len(a))
	for i := range res {
		res[i] = -1
	}
	var st []int // indexes awaiting an answer
	for i, v := range a {
		for len(st) > 0 && a[st[len(st)-1]] < v {
			res[st[len(st)-1]] = v
			st = st[:len(st)-1]
		}
		st = append(st, i)
	}
	return res
}

func main() {
	fmt.Println(Balanced("{[()()]}"), Balanced("([)]"), Balanced("(("), Balanced(""))
	fmt.Println(NextGreater([]int{4, 5, 2, 25, 7, 3, 8}))
}

