import (
	"fmt"
	"strings"
)

type point struct{ r, c int }

func main() {
	maze := []string{
		"S.#.....",
		".##.###.",
		"......#.",
		"##.#.##.",
		"...#...E",
	}
	grid := make([][]byte, len(maze))
	var start, end point
	for r, row := range maze {
		grid[r] = []byte(row)
		if c := strings.IndexByte(row, 'S'); c >= 0 {
			start = point{r, c}
		}
		if c := strings.IndexByte(row, 'E'); c >= 0 {
			end = point{r, c}
		}
	}
	dist := map[point]int{start: 0}
	prev := map[point]point{}
	queue := []point{start}
	dirs := []point{{-1, 0}, {1, 0}, {0, -1}, {0, 1}}
	for len(queue) > 0 {
		p := queue[0]
		queue = queue[1:]
		if p == end {
			break
		}
		for _, d := range dirs {
			n := point{p.r + d.r, p.c + d.c}
			if n.r < 0 || n.r >= len(grid) || n.c < 0 || n.c >= len(grid[0]) || grid[n.r][n.c] == '#' {
				continue
			}
			if _, seen := dist[n]; seen {
				continue
			}
			dist[n] = dist[p] + 1
			prev[n] = p
			queue = append(queue, n)
		}
	}
	steps, ok := dist[end]
	if !ok {
		fmt.Println("no path")
		return
	}
	fmt.Println("steps:", steps)
	for p := prev[end]; p != start; p = prev[p] {
		grid[p.r][p.c] = '*'
	}
	for _, row := range grid {
		fmt.Println(string(row))
	}
}

package main

import (
	"container/heap"
	"fmt"
	"slices"
	"strings"
)

type edge struct {
	to string
	w  int
}

type item struct {
	node string
	dist int
}

type pq []item

func (q pq) Len() int           { return len(q) }
func (q pq) Less(i, j int) bool { return q[i].dist < q[j].dist }
func (q pq) Swap(i, j int)      { q[i], q[j] = q[j], q[i] }
func (q *pq) Push(x any)        { *q = append(*q, x.(item)) }
func (q *pq) Pop() any {
	old := *q
	x := old[len(old)-1]
	*q = old[:len(old)-1]
	return x
}

func dijkstra(g map[string][]edge, src string) (map[string]int, map[string]string) {
	dist := map[string]int{src: 0}
	prev := map[string]string{}
	h := &pq{{src, 0}}
	for h.Len() > 0 {
		it := heap.Pop(h).(item)
		if it.dist > dist[it.node] {
			continue // stale entry
		}
		for _, e := range g[it.node] {
			nd := it.dist + e.w
			if d, ok := dist[e.to]; !ok || nd < d {
				dist[e.to] = nd
				prev[e.to] = it.node
				heap.Push(h, item{e.to, nd})
			}
		}
	}
	return dist, prev
}

func main() {
	g := map[string][]edge{}
	for _, s := range strings.Split("A B 4,A C 2,C B 1,B D 5,C D 8,C E 10,D E 2,E F 3,D F 6", ",") {
		var a, b string
		var w int
		fmt.Sscan(s, &a, &b, &w)
		g[a] = append(g[a], edge{b, w})
	}
	dist, prev := dijkstra(g, "A")
	nodes := make([]string, 0, len(dist))
	for n := range dist {
		nodes = append(nodes, n)
	}
	slices.Sort(nodes)
	for _, n := range nodes {
		fmt.Printf("%s: %d\n", n, dist[n])
	}
	path := []string{"F"}
	for n := "F"; n != "A"; n = prev[n] {
		path = append(path, prev[n])
	}
	slices.Reverse(path)
	fmt.Printf("path: %s (%d)\n", strings.Join(path, " -> "), dist["F"])
}

