import (
	"fmt"
	"slices"
	"strings"
)

func topo(deps [][2]string) ([]string, []string) {
	indeg := map[string]int{}
	out := map[string][]string{}
	for _, d := range deps {
		course, pre := d[0], d[1]
		out[pre] = append(out[pre], course)
		indeg[course]++
		if _, ok := indeg[pre]; !ok {
			indeg[pre] = 0
		}
	}
	var ready []string
	for n, d := range indeg {
		if d == 0 {
			ready = append(ready, n)
		}
	}
	var order []string
	for len(ready) > 0 {
		slices.Sort(ready)
		n := ready[0]
		ready = ready[1:]
		order = append(order, n)
		for _, m := range out[n] {
			indeg[m]--
			if indeg[m] == 0 {
				ready = append(ready, m)
			}
		}
	}
	var stuck []string
	for n, d := range indeg {
		if d > 0 {
			stuck = append(stuck, n)
		}
	}
	slices.Sort(stuck)
	return order, stuck
}

func main() {
	deps := [][2]string{
		{"algorithms", "datastructures"}, {"datastructures", "programming"},
		{"databases", "programming"}, {"webdev", "databases"},
		{"webdev", "programming"}, {"compilers", "algorithms"},
		{"compilers", "theory"},
	}
	order, _ := topo(deps)
	fmt.Println("order:", strings.Join(order, " "))
	_, stuck := topo(append(deps, [2]string{"programming", "compilers"}))
	fmt.Println("cycle among:", strings.Join(stuck, " "))
}

