import (
	"fmt"
	"slices"
)

type UF struct{ parent, size []int }

func NewUF(n int) *UF {
	u := &UF{make([]int, n), make([]int, n)}
	for i := range n {
		u.parent[i], u.size[i] = i, 1
	}
	return u
}

func (u *UF) Find(x int) int {
	for u.parent[x] != x {
		u.parent[x] = u.parent[u.parent[x]]
		x = u.parent[x]
	}
	return x
}

func (u *UF) Union(a, b int) bool {
	ra, rb := u.Find(a), u.Find(b)
	if ra == rb {
		return false
	}
	if u.size[ra] < u.size[rb] {
		ra, rb = rb, ra
	}
	u.parent[rb] = ra
	u.size[ra] += u.size[rb]
	return true
}

func main() {
	u := NewUF(10)
	cables := [][2]int{{0, 1}, {1, 2}, {3, 4}, {5, 6}, {6, 7}, {7, 5}, {2, 0}, {8, 9}, {4, 8}}
	for _, c := range cables {
		if !u.Union(c[0], c[1]) {
			fmt.Printf("redundant: %d-%d\n", c[0], c[1])
		}
	}
	groups := map[int][]int{}
	var roots []int
	for i := range 10 {
		r := u.Find(i)
		if _, ok := groups[r]; !ok {
			roots = append(roots, r)
		}
		groups[r] = append(groups[r], i)
	}
	fmt.Println("groups:", len(roots))
	for _, r := range roots {
		g := groups[r]
		slices.Sort(g)
		fmt.Println(g)
	}
}

