import (
	"fmt"
	"slices"
)

type node struct {
	children map[rune]*node
	end      bool
}

type Trie struct{ root *node }

func NewTrie() *Trie { return &Trie{&node{children: map[rune]*node{}}} }

func (t *Trie) Insert(w string) {
	n := t.root
	for _, c := range w {
		next, ok := n.children[c]
		if !ok {
			next = &node{children: map[rune]*node{}}
			n.children[c] = next
		}
		n = next
	}
	n.end = true
}

func (t *Trie) find(prefix string) *node {
	n := t.root
	for _, c := range prefix {
		n = n.children[c]
		if n == nil {
			return nil
		}
	}
	return n
}

func (t *Trie) Contains(w string) bool {
	n := t.find(w)
	return n != nil && n.end
}

func (t *Trie) Complete(prefix string) []string {
	out := []string{}
	var walk func(n *node, word []rune)
	walk = func(n *node, word []rune) {
		if n.end {
			out = append(out, string(word))
		}
		keys := make([]rune, 0, len(n.children))
		for k := range n.children {
			keys = append(keys, k)
		}
		slices.Sort(keys)
		for _, k := range keys {
			walk(n.children[k], append(word, k))
		}
	}
	if n := t.find(prefix); n != nil {
		walk(n, []rune(prefix))
	}
	return out
}

func (t *Trie) CountPrefix(p string) int { return len(t.Complete(p)) }

func main() {
	t := NewTrie()
	for _, w := range []string{"go", "gopher", "golang", "google", "gone", "good", "grpc", "graph", "rust"} {
		t.Insert(w)
	}
	fmt.Println(t.Contains("gone"), t.Contains("gon"))
	fmt.Println(t.Complete("go"))
	fmt.Println(t.Complete("gr"))
	fmt.Println(t.Complete("java"))
	fmt.Println(t.CountPrefix("goo"))
}

