import (
	"fmt"
	"math"
)

func EditDistance(a, b string) int {
	dp := make([][]int, len(a)+1)
	for i := range dp {
		dp[i] = make([]int, len(b)+1)
		dp[i][0] = i
	}
	for j := range dp[0] {
		dp[0][j] = j
	}
	for i := 1; i <= len(a); i++ {
		for j := 1; j <= len(b); j++ {
			if a[i-1] == b[j-1] {
				dp[i][j] = dp[i-1][j-1]
			} else {
				dp[i][j] = 1 + min(dp[i-1][j], dp[i][j-1], dp[i-1][j-1])
			}
		}
	}
	return dp[len(a)][len(b)]
}

func MinCoins(coins []int, amount int) int {
	dp := make([]int, amount+1)
	for x := 1; x <= amount; x++ {
		dp[x] = math.MaxInt
		for _, c := range coins {
			if c <= x && dp[x-c] != math.MaxInt {
				dp[x] = min(dp[x], dp[x-c]+1)
			}
		}
	}
	if dp[amount] == math.MaxInt {
		return -1
	}
	return dp[amount]
}

func main() {
	fmt.Println(EditDistance("kitten", "sitting"), EditDistance("flaw", "lawn"), EditDistance("gopher", "gopher"))
	best, bestD := "", math.MaxInt
	for _, c := range []string{"build", "test", "run", "vet", "fmt", "mod", "get"} {
		if d := EditDistance("tset", c); d < bestD {
			best, bestD = c, d
		}
	}
	fmt.Printf("did you mean: %s?\n", best)
	fmt.Println(MinCoins([]int{1, 5, 10, 25}, 63), MinCoins([]int{2}, 3), MinCoins([]int{1, 3, 4}, 6))
}

