import (
	"fmt"
	"slices"
	"strings"
)

func Permutations(nums []int) [][]int {
	var out [][]int
	var cur []int
	used := make([]bool, len(nums))
	var rec func()
	rec = func() {
		if len(cur) == len(nums) {
			out = append(out, slices.Clone(cur)) // copy!
			return
		}
		for i, v := range nums {
			if used[i] {
				continue
			}
			used[i] = true
			cur = append(cur, v)
			rec()
			cur = cur[:len(cur)-1]
			used[i] = false
		}
	}
	rec()
	return out
}

func Queens(n int) (count int, first []int) {
	cols := make([]bool, n)
	d1 := make([]bool, 2*n) // r+c
	d2 := make([]bool, 2*n) // r-c+n
	pos := make([]int, n)
	var place func(r int)
	place = func(r int) {
		if r == n {
			if count == 0 {
				first = slices.Clone(pos)
			}
			count++
			return
		}
		for c := range n {
			if cols[c] || d1[r+c] || d2[r-c+n] {
				continue
			}
			cols[c], d1[r+c], d2[r-c+n] = true, true, true
			pos[r] = c
			place(r + 1)
			cols[c], d1[r+c], d2[r-c+n] = false, false, false
		}
	}
	place(0)
	return
}

func main() {
	fmt.Println(Permutations([]int{1, 2, 3}))
	var counts []string
	for n := 1; n <= 8; n++ {
		c, _ := Queens(n)
		counts = append(counts, fmt.Sprint(c))
	}
	fmt.Println(strings.Join(counts, " "))
	_, sol := Queens(6)
	for _, c := range sol {
		fmt.Println(strings.Repeat(".", c) + "Q" + strings.Repeat(".", 6-c-1))
	}
}

