func Merge(iv [][2]int) [][2]int {
	slices.SortFunc(iv, func(a, b [2]int) int { return cmp.Compare(a[0], b[0]) })
	var out [][2]int
	for _, x := range iv {
		if n := len(out); n > 0 && x[0] <= out[n-1][1] {
			out[n-1][1] = max(out[n-1][1], x[1])
		} else {
			out = append(out, x)
		}
	}
	return out
}

type entry struct {
	key string
	val int
}

type LRU struct {
	cap   int
	ll    *list.List
	items map[string]*list.Element
}

func NewLRU(n int) *LRU { return &LRU{n, list.New(), map[string]*list.Element{}} }

func (c *LRU) Get(k string) (int, bool) {
	e, ok := c.items[k]
	if !ok {
		return 0, false
	}
	c.ll.MoveToFront(e)
	return e.Value.(*entry).val, true
}

func (c *LRU) Put(k string, v int) {
	if e, ok := c.items[k]; ok {
		e.Value.(*entry).val = v
		c.ll.MoveToFront(e)
		return
	}
	c.items[k] = c.ll.PushFront(&entry{k, v})
	if c.ll.Len() > c.cap {
		old := c.ll.Back()
		c.ll.Remove(old)
		delete(c.items, old.Value.(*entry).key)
	}
}

func main() {
	fmt.Println(Merge([][2]int{{8, 10}, {1, 3}, {2, 6}, {15, 18}, {17, 20}, {6, 7}}))

	c := NewLRU(2)
	get := func(k string) {
		v, ok := c.Get(k)
		fmt.Printf("get %s: %d %v\n", k, v, ok)
	}
	c.Put("a", 1)
	c.Put("b", 2)
	get("a")
	c.Put("c", 3) // evicts b
	get("b")
	c.Put("d", 4) // evicts a
	get("a")
	get("c")
	get("d")
	var keys []string
	for e := c.ll.Front(); e != nil; e = e.Next() {
		keys = append(keys, e.Value.(*entry).key)
	}
	fmt.Println("order:", strings.Join(keys, " "))
}

