var table = []struct {
	v int
	s string
}{
	{1000, "M"}, {900, "CM"}, {500, "D"}, {400, "CD"}, {100, "C"}, {90, "XC"},
	{50, "L"}, {40, "XL"}, {10, "X"}, {9, "IX"}, {5, "V"}, {4, "IV"}, {1, "I"},
}

func ToRoman(n int) string {
	var b strings.Builder
	for _, t := range table {
		for n >= t.v {
			b.WriteString(t.s)
			n -= t.v
		}
	}
	return b.String()
}

var digit = map[rune]int{'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}

func FromRoman(s string) (int, error) {
	r := []rune(s)
	total := 0
	for i, c := range r {
		v, ok := digit[c]
		if !ok {
			return 0, fmt.Errorf("invalid roman digit %q", c)
		}
		if i+1 < len(r) && digit[r[i+1]] > v {
			total -= v
		} else {
			total += v
		}
	}
	return total, nil
}

func main() {
	var out []string
	for _, n := range []int{4, 9, 14, 1994, 2026, 3999} {
		out = append(out, ToRoman(n))
	}
	fmt.Println(strings.Join(out, " "))
	a, _ := FromRoman("MCMXCIV")
	b, _ := FromRoman("XLII")
	fmt.Println(a, b)
	_, err := FromRoman("12X")
	fmt.Println(err)
}

