func Encode(s string) string {
	var b strings.Builder
	r := []rune(s)
	for i := 0; i < len(r); {
		j := i
		for j < len(r) && r[j] == r[i] {
			j++
		}
		if n := j - i; n > 1 {
			b.WriteString(strconv.Itoa(n))
		}
		b.WriteRune(r[i])
		i = j
	}
	return b.String()
}

func Decode(s string) string {
	var b strings.Builder
	n := 0
	for _, c := range s {
		if unicode.IsDigit(c) {
			n = n*10 + int(c-'0')
			continue
		}
		b.WriteString(strings.Repeat(string(c), max(n, 1)))
		n = 0
	}
	return b.String()
}

func main() {
	fmt.Println(Encode("WWWWWWWWWWWWBWWWWWWWWWWWWBBBWWWWWWWWWWWWWWWWWWWWWWWWB"))
	fmt.Printf("%q\n", Encode("  hsqq qww  "))
	fmt.Println(Encode("ééégo"))
	fmt.Println(Decode("12WB12W3B24WB"))
	x := "aabcccccaaa"
	fmt.Println("round trip:", Decode(Encode(x)) == x)
}

