import (
	"fmt"
	"strings"
)

func Luhn(s string) bool {
	s = strings.ReplaceAll(s, " ", "")
	if len(s) < 2 {
		return false
	}
	sum := 0
	for i := range len(s) {
		c := s[len(s)-1-i]
		if c < '0' || c > '9' {
			return false
		}
		d := int(c - '0')
		if i%2 == 1 {
			d *= 2
			if d > 9 {
				d -= 9
			}
		}
		sum += d
	}
	return sum%10 == 0
}

func ISBN10(s string) bool {
	s = strings.ReplaceAll(s, "-", "")
	if len(s) != 10 {
		return false
	}
	sum := 0
	for i, c := range s {
		var d int
		switch {
		case c >= '0' && c <= '9':
			d = int(c - '0')
		case c == 'X' && i == 9:
			d = 10
		default:
			return false
		}
		sum += d * (10 - i)
	}
	return sum%11 == 0
}

func main() {
	for _, s := range []string{"4539 3195 0343 6467", "8273 1232 7352 0569", "0", "059a"} {
		fmt.Printf("%s: %v\n", s, Luhn(s))
	}
	for _, s := range []string{"3-598-21508-8", "3-598-21507-X", "3-598-21508-9", "3-598-2X507-9"} {
		fmt.Printf("%s: %v\n", s, ISBN10(s))
	}
}

