func Frequency(text string) map[rune]int {
	m := map[rune]int{}
	for _, r := range strings.ToLower(text) {
		if unicode.IsLetter(r) {
			m[r]++
		}
	}
	return m
}

func ConcurrentFrequency(texts []string) map[rune]int {
	parts := make(chan map[rune]int, len(texts))
	for _, t := range texts {
		go func() { parts <- Frequency(t) }()
	}
	total := map[rune]int{}
	for range texts {
		for r, n := range <-parts {
			total[r] += n
		}
	}
	return total
}

func main() {
	texts := []string{"Freude schöner Götterfunken", "Tochter aus Elysium,", "Wir betreten feuertrunken"}
	c := ConcurrentFrequency(texts)
	fmt.Printf("e=%d r=%d ö=%d t=%d\n", c['e'], c['r'], c['ö'], c['t'])
	fmt.Println("same:", maps.Equal(c, Frequency(strings.Join(texts, " "))))
}

