	N Dir = iota
	E
	S
	W
)

func (d Dir) String() string { return [...]string{"N", "E", "S", "W"}[d] }

type Robot struct {
	X, Y   int
	Facing Dir
}

func (r *Robot) Run(cmds string) error {
	for i, c := range cmds {
		switch c {
		case 'R':
			r.Facing = (r.Facing + 1) % 4
		case 'L':
			r.Facing = (r.Facing + 3) % 4
		case 'A':
			switch r.Facing {
			case N:
				r.Y++
			case E:
				r.X++
			case S:
				r.Y--
			case W:
				r.X--
			}
		default:
			return fmt.Errorf("bad command %q at %d", c, i)
		}
	}
	return nil
}

func (r Robot) String() string { return fmt.Sprintf("%d,%d %v", r.X, r.Y, r.Facing) }

func main() {
	a := Robot{7, 3, N}
	a.Run("RAALAL")
	fmt.Println(a)
	b := Robot{0, 0, E}
	b.Run("AAAALAARRRR")
	fmt.Println(b)
	fmt.Println(b.Run("AAXA"))
	fmt.Println(b)
}

