import (
	"bufio"
	"cmp"
	"fmt"
	"os"
	"slices"
	"strings"
)

type row struct {
	name             string
	mp, w, d, l, pts int
}

func main() {
	table := map[string]*row{}
	get := func(n string) *row {
		if table[n] == nil {
			table[n] = &row{name: n}
		}
		return table[n]
	}
	sc := bufio.NewScanner(os.Stdin)
	for ln := 1; sc.Scan(); ln++ {
		line := strings.TrimSpace(sc.Text())
		if line == "" || strings.HasPrefix(line, "#") {
			continue
		}
		f := strings.Split(line, ";")
		if len(f) != 3 || (f[2] != "win" && f[2] != "loss" && f[2] != "draw") {
			fmt.Printf("skipping line %d: %q\n", ln, line)
			continue
		}
		h, a := get(f[0]), get(f[1])
		h.mp++
		a.mp++
		switch f[2] {
		case "win":
			h.w, h.pts, a.l = h.w+1, h.pts+3, a.l+1
		case "loss":
			a.w, a.pts, h.l = a.w+1, a.pts+3, h.l+1
		case "draw":
			h.d, h.pts, a.d, a.pts = h.d+1, h.pts+1, a.d+1, a.pts+1
		}
	}
	rows := slices.Collect(func(yield func(*row) bool) {
		for _, r := range table {
			if !yield(r) {
				return
			}
		}
	})
	slices.SortFunc(rows, func(a, b *row) int {
		return cmp.Or(cmp.Compare(b.pts, a.pts), cmp.Compare(a.name, b.name))
	})
	fmt.Printf("%-30s | %2s | %2s | %2s | %2s | %2s\n", "Team", "MP", "W", "D", "L", "P")
	for _, r := range rows {
		fmt.Printf("%-30s | %2d | %2d | %2d | %2d | %2d\n", r.name, r.mp, r.w, r.d, r.l, r.pts)
	}
}

