import (
	"fmt"
	"sync"
)

type Account struct {
	mu      sync.Mutex
	balance int64
	closed  bool
}

func Open(initial int64) *Account {
	if initial < 0 {
		return nil
	}
	return &Account{balance: initial}
}

func (a *Account) Balance() (int64, bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return 0, false
	}
	return a.balance, true
}

func (a *Account) Deposit(amt int64) (int64, bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed || a.balance+amt < 0 {
		return a.balance, false
	}
	a.balance += amt
	return a.balance, true
}

func (a *Account) Close() (int64, bool) {
	a.mu.Lock()
	defer a.mu.Unlock()
	if a.closed {
		return 0, false
	}
	a.closed = true
	return a.balance, true
}

func main() {
	acc := Open(3000)
	var wg sync.WaitGroup
	for range 1000 {
		wg.Add(2)
		go func() { defer wg.Done(); acc.Deposit(5) }()
		go func() { defer wg.Done(); acc.Deposit(-3) }()
	}
	wg.Wait()
	b, _ := acc.Balance()
	fmt.Println("balance:", b)
	fmt.Println(acc.Deposit(-10000))
	fmt.Println(acc.Close())
	fmt.Println(acc.Close())
	fmt.Println(acc.Balance())
	fmt.Println(Open(-5) == nil)
}

