import (
	"encoding/json"
	"fmt"
	"slices"
	"strings"
)

func flatten(prefix string, v any, out map[string]string) {
	join := func(k string) string {
		if prefix == "" {
			return k
		}
		return prefix + "." + k
	}
	switch x := v.(type) {
	case map[string]any:
		if len(x) == 0 {
			out[prefix] = "{}"
		}
		for k, val := range x {
			flatten(join(k), val, out)
		}
	case []any:
		if len(x) == 0 {
			out[prefix] = "[]"
		}
		for i, val := range x {
			flatten(fmt.Sprintf("%s[%d]", prefix, i), val, out)
		}
	case string:
		out[prefix] = fmt.Sprintf("%q", x)
	default:
		out[prefix] = fmt.Sprint(x)
	}
}

func main() {
	src := `{"service":"api","port":8080,"tls":{"enabled":true,"ciphers":["a","b"]},
	 "replicas":[{"zone":"eu","weight":0.5},{"zone":"us","weight":1.5}],
	 "tags":[],"owner":null,"extra":{}}`
	var v any
	if err := json.NewDecoder(strings.NewReader(src)).Decode(&v); err != nil {
		panic(err)
	}
	out := map[string]string{}
	flatten("", v, out)
	keys := make([]string, 0, len(out))
	for k := range out {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	for _, k := range keys {
		fmt.Println(k, "=", out[k])
	}
}

