import (
	"fmt"
	"strings"
)

type Grid [][]bool

func Parse(rows ...string) Grid {
	g := make(Grid, len(rows))
	for r, row := range rows {
		g[r] = make([]bool, len(row))
		for c, ch := range row {
			g[r][c] = ch == '#'
		}
	}
	return g
}

func (g Grid) Neighbours(r, c int) int {
	n := 0
	for dr := -1; dr <= 1; dr++ {
		for dc := -1; dc <= 1; dc++ {
			if dr == 0 && dc == 0 {
				continue
			}
			rr, cc := r+dr, c+dc
			if rr >= 0 && rr < len(g) && cc >= 0 && cc < len(g[rr]) && g[rr][cc] {
				n++
			}
		}
	}
	return n
}

func (g Grid) Step() Grid {
	next := make(Grid, len(g))
	for r := range g {
		next[r] = make([]bool, len(g[r]))
		for c := range g[r] {
			n := g.Neighbours(r, c)
			next[r][c] = n == 3 || (g[r][c] && n == 2)
		}
	}
	return next
}

func (g Grid) String() string {
	lines := make([]string, len(g))
	for r, row := range g {
		var b strings.Builder
		for _, alive := range row {
			if alive {
				b.WriteByte('#')
			} else {
				b.WriteByte('.')
			}
		}
		lines[r] = b.String()
	}
	return strings.Join(lines, "\n")
}

func main() {
	g := Parse(".#....", "..#...", "###...", "......", "......", "......")
	fmt.Println("gen 0:")
	fmt.Println(g)
	for range 4 {
		g = g.Step()
	}
	fmt.Println("gen 4:")
	fmt.Println(g)
}

