import (
	"errors"
	"fmt"
	"math/bits"
	"strconv"
)

func ConvertBase(digits []int, from, to int) ([]int, error) {
	if from < 2 {
		return nil, errors.New("input base must be >= 2")
	}
	if to < 2 {
		return nil, errors.New("output base must be >= 2")
	}
	n := 0
	for _, d := range digits {
		if d < 0 || d >= from {
			return nil, errors.New("all digits must satisfy 0 <= d < input base")
		}
		n = n*from + d
	}
	if n == 0 {
		return []int{0}, nil
	}
	var out []int
	for ; n > 0; n /= to {
		out = append([]int{n % to}, out...)
	}
	return out, nil
}

func main() {
	for _, c := range []struct {
		d        []int
		from, to int
	}{
		{[]int{1, 0, 1, 0, 1, 0}, 2, 10},
		{[]int{4, 2}, 10, 2},
		{[]int{3, 46, 60}, 97, 73},
		{[]int{0, 0, 0}, 10, 2},
	} {
		out, _ := ConvertBase(c.d, c.from, c.to)
		fmt.Println(out)
	}
	_, err := ConvertBase([]int{1, 2}, 2, 10)
	fmt.Println(err)
	fmt.Println(strconv.FormatInt(255, 16), strconv.FormatInt(-10, 2), fmt.Sprintf("%08b", 13))
	fmt.Println(bits.OnesCount(255), bits.Len(1000), bits.TrailingZeros(48))
}

