import (
	"errors"
	"fmt"
	"strings"
)

type Builder struct {
	cols   []string
	table  string
	wheres []string
	args   []any
	limit  int
	err    error
}

func Select(cols ...string) *Builder { return &Builder{cols: cols} }

func (b *Builder) From(table string) *Builder {
	b.table = table
	return b
}

func (b *Builder) Where(cond string, args ...any) *Builder {
	b.wheres = append(b.wheres, cond)
	b.args = append(b.args, args...)
	return b
}

func (b *Builder) Limit(n int) *Builder {
	if n < 0 && b.err == nil {
		b.err = errors.New("limit must not be negative")
	}
	b.limit = n
	return b
}

func (b *Builder) Build() (string, []any, error) {
	if b.err != nil {
		return "", nil, b.err
	}
	if b.table == "" {
		return "", nil, errors.New("no table: call From")
	}
	var sb strings.Builder
	sb.WriteString("SELECT " + strings.Join(b.cols, ", ") + " FROM " + b.table)
	if len(b.wheres) > 0 {
		sb.WriteString(" WHERE " + strings.Join(b.wheres, " AND "))
	}
	if b.limit > 0 {
		fmt.Fprintf(&sb, " LIMIT %d", b.limit)
	}
	return sb.String(), b.args, nil
}

func main() {
	q, args, err := Select("name", "email").From("users").
		Where("age > ?", 30).Where("city = ?", "Cairo").Limit(10).Build()
	fmt.Println(q)
	fmt.Println(args, err)

	_, _, err = Select("id").From("users").Limit(-1).Build()
	fmt.Println("error:", err)

	_, _, err = Select("id").Build()
	fmt.Println("error:", err)
}

