import "fmt"

type Pricing func(cents int) int

func FullPrice(c int) int { return c }

func PercentOff(p int) Pricing {
	return func(c int) int { return c - c*p/100 }
}

func FlatOff(off int) Pricing {
	return func(c int) int { return max(0, c-off) }
}

func Chain(steps ...Pricing) Pricing {
	return func(c int) int {
		for _, s := range steps {
			c = s(c)
		}
		return c
	}
}

func Checkout(items []int, price Pricing) int {
	total := 0
	for _, it := range items {
		total += it
	}
	return price(total)
}

func main() {
	cart := []int{1999, 550, 1200} // cents
	plans := []struct {
		name  string
		price Pricing
	}{
		{"full price", FullPrice},
		{"10% off", PercentOff(10)},
		{"5.00 off", FlatOff(500)},
		{"10% then 5.00 off", Chain(PercentOff(10), FlatOff(500))},
	}
	for _, p := range plans {
		t := Checkout(cart, p.price)
		fmt.Printf("%-18s %d.%02d\n", p.name, t/100, t%100)
	}
}

