import (
	"errors"
	"fmt"
)

type Store interface {
	Get(key string) (string, error)
}

// The real, "slow" store.
type slow struct {
	data  map[string]string
	calls int
}

func (s *slow) Get(key string) (string, error) {
	s.calls++
	v, ok := s.data[key]
	if !ok {
		return "", errors.New("not found: " + key)
	}
	return v, nil
}

// Decorator 1: remember successful answers.
type cached struct {
	next Store
	memo map[string]string
}

func Cached(next Store) Store { return &cached{next: next, memo: map[string]string{}} }

func (c *cached) Get(key string) (string, error) {
	if v, ok := c.memo[key]; ok {
		return v, nil
	}
	v, err := c.next.Get(key)
	if err == nil {
		c.memo[key] = v
	}
	return v, err
}

// Decorator 2: print every call.
type logged struct{ next Store }

func Logged(next Store) Store { return logged{next} }

func (l logged) Get(key string) (string, error) {
	v, err := l.next.Get(key)
	fmt.Printf("  log: Get(%q) -> %q, err=%v\n", key, v, err)
	return v, err
}

func main() {
	real := &slow{data: map[string]string{"go": "gopher", "py": "snake"}}
	s := Logged(Cached(real))

	for _, k := range []string{"go", "go", "py", "go", "rust"} {
		s.Get(k)
	}
	fmt.Println("calls that reached the slow store:", real.calls)
}

