import "fmt"

type Handler func(data string)

type sub struct {
	id int
	fn Handler
}

type Bus struct {
	nextID int
	subs   map[string][]sub
}

func NewBus() *Bus { return &Bus{subs: map[string][]sub{}} }

// Subscribe registers fn for a topic and returns a function that removes it.
func (b *Bus) Subscribe(topic string, fn Handler) (unsubscribe func()) {
	b.nextID++
	id := b.nextID
	b.subs[topic] = append(b.subs[topic], sub{id, fn})
	return func() {
		list := b.subs[topic]
		for i, s := range list {
			if s.id == id {
				b.subs[topic] = append(list[:i:i], list[i+1:]...)
				return
			}
		}
	}
}

func (b *Bus) Publish(topic, data string) int {
	list := b.subs[topic]
	for _, s := range list {
		s.fn(data)
	}
	return len(list)
}

func main() {
	bus := NewBus()
	bus.Subscribe("order.placed", func(d string) { fmt.Println("  email: confirmation for", d) })
	stopAudit := bus.Subscribe("order.placed", func(d string) { fmt.Println("  audit:", d) })
	bus.Subscribe("order.shipped", func(d string) { fmt.Println("  email: on its way,", d) })

	fmt.Println("delivered to", bus.Publish("order.placed", "order 17"))
	stopAudit()
	fmt.Println("delivered to", bus.Publish("order.placed", "order 18"))
	fmt.Println("delivered to", bus.Publish("order.shipped", "order 17"))
	fmt.Println("delivered to", bus.Publish("order.lost", "order 99"))
}

