import "fmt"

type State int

const (
	New State = iota
	Paid
	Shipped
	Delivered
	Cancelled
)

func (s State) String() string {
	return [...]string{"New", "Paid", "Shipped", "Delivered", "Cancelled"}[s]
}

type Event string

const (
	Pay     Event = "pay"
	Ship    Event = "ship"
	Deliver Event = "deliver"
	Cancel  Event = "cancel"
)

type key struct {
	from State
	ev   Event
}

var table = map[key]State{
	{New, Pay}:         Paid,
	{New, Cancel}:      Cancelled,
	{Paid, Ship}:       Shipped,
	{Paid, Cancel}:     Cancelled,
	{Shipped, Deliver}: Delivered,
}

type Order struct {
	ID    int
	State State
}

func (o *Order) Apply(ev Event) error {
	next, ok := table[key{o.State, ev}]
	if !ok {
		return fmt.Errorf("order %d: cannot %s while %s", o.ID, ev, o.State)
	}
	o.State = next
	return nil
}

func main() {
	o := &Order{ID: 7}
	for _, ev := range []Event{Pay, Pay, Ship, Cancel, Deliver, Ship} {
		if err := o.Apply(ev); err != nil {
			fmt.Println("rejected:", err)
			continue
		}
		fmt.Printf("%-8s -> %s\n", ev, o.State)
	}
}

