package main

import (
	"fmt"
	"slices"
	"strings"
)

type Codec interface {
	Encode(s string) string
}

var codecs = map[string]Codec{}

func Register(name string, c Codec) {
	if _, dup := codecs[name]; dup {
		panic("codec registered twice: " + name)
	}
	codecs[name] = c
}

func Lookup(name string) (Codec, error) {
	c, ok := codecs[name]
	if !ok {
		return nil, fmt.Errorf("unknown codec %q (have: %s)", name, strings.Join(Names(), ", "))
	}
	return c, nil
}

func Names() []string {
	names := make([]string, 0, len(codecs))
	for n := range codecs {
		names = append(names, n)
	}
	slices.Sort(names)
	return names
}

// --- plug-ins: in a real program each would live in its own file or package ---

type upper struct{}

func (upper) Encode(s string) string { return strings.ToUpper(s) }
func init()                          { Register("upper", upper{}) }

type reverse struct{}

func (reverse) Encode(s string) string {
	r := []rune(s)
	slices.Reverse(r)
	return string(r)
}
func init() { Register("reverse", reverse{}) }

type rot13 struct{}

func (rot13) Encode(s string) string {
	return strings.Map(func(r rune) rune {
		switch {
		case r >= 'a' && r <= 'z':
			return 'a' + (r-'a'+13)%26
		case r >= 'A' && r <= 'Z':
			return 'A' + (r-'A'+13)%26
		}
		return r
	}, s)
}
func init() { Register("rot13", rot13{}) }

func main() {
	fmt.Println("registered:", Names())
	for _, name := range []string{"upper", "rot13", "reverse", "base99"} {
		c, err := Lookup(name)
		if err != nil {
			fmt.Println("error:", err)
			continue
		}
		fmt.Printf("%-8s %s\n", name, c.Encode("Hello, Gopher"))
	}
}

