}

func (c *DeleteLast) Do(d *Doc) {
	n := min(c.N, len(d.Text))
	c.removed = d.Text[len(d.Text)-n:]
	d.Text = d.Text[:len(d.Text)-n]
}
func (c *DeleteLast) Undo(d *Doc) { d.Text += c.removed }

type Editor struct {
	doc        Doc
	undo, redo []Command
}

func (e *Editor) Run(c Command) {
	c.Do(&e.doc)
	e.undo = append(e.undo, c)
	e.redo = nil
}

func (e *Editor) Undo() bool {
	if len(e.undo) == 0 {
		return false
	}
	c := e.undo[len(e.undo)-1]
	e.undo = e.undo[:len(e.undo)-1]
	c.Undo(&e.doc)
	e.redo = append(e.redo, c)
	return true
}

func (e *Editor) Redo() bool {
	if len(e.redo) == 0 {
		return false
	}
	c := e.redo[len(e.redo)-1]
	e.redo = e.redo[:len(e.redo)-1]
	c.Do(&e.doc)
	e.undo = append(e.undo, c)
	return true
}

func main() {
	e := &Editor{}
	show := func(label string) { fmt.Printf("%-8s %q\n", label, e.doc.Text) }

	e.Run(&Append{Text: "Hello"})
	show("append")
	e.Run(&Append{Text: ", Go"})
	show("append")
	e.Run(&DeleteLast{N: 4})
	show("delete")
	for range 4 {
		if e.Undo() {
			show("undo")
		} else {
			fmt.Println("undo     nothing to undo")
		}
	}
	for range 2 {
		e.Redo()
		show("redo")
	}
	e.Run(&Append{Text: "!"})
	show("append")
	if !e.Redo() {
		fmt.Println("redo     nothing to redo")
	}
}

