import "fmt"

type Ring[T any] struct {
	buf  []T
	head int
	size int
}

func NewRing[T any](capacity int) *Ring[T] {
	return &Ring[T]{buf: make([]T, capacity)}
}

// Push adds v. When full it overwrites the oldest item and reports true.
func (r *Ring[T]) Push(v T) (overwrote bool) {
	if r.size == len(r.buf) {
		r.buf[r.head] = v
		r.head = (r.head + 1) % len(r.buf)
		return true
	}
	r.buf[(r.head+r.size)%len(r.buf)] = v
	r.size++
	return false
}

// Pop removes and returns the oldest item.
func (r *Ring[T]) Pop() (T, bool) {
	var zero T
	if r.size == 0 {
		return zero, false
	}
	v := r.buf[r.head]
	r.buf[r.head] = zero // drop the reference so it can be collected
	r.head = (r.head + 1) % len(r.buf)
	r.size--
	return v, true
}

// Items returns the contents, oldest first.
func (r *Ring[T]) Items() []T {
	out := make([]T, 0, r.size)
	for i := range r.size {
		out = append(out, r.buf[(r.head+i)%len(r.buf)])
	}
	return out
}

func main() {
	r := NewRing[string](3)
	for _, line := range []string{"boot", "login", "query", "error", "retry"} {
		over := r.Push(line)
		fmt.Printf("push %-6s overwrote=%-5v items=%v raw=%q head=%d\n", line, over, r.Items(), r.buf, r.head)
	}
	v, ok := r.Pop()
	fmt.Println("pop:", v, ok, "left:", r.Items())
	r.Pop()
	r.Pop()
	v, ok = r.Pop()
	fmt.Printf("pop on empty: %q %v\n", v, ok)
}

