import "fmt"

type Heap[T any] struct {
	items []T
	less  func(a, b T) bool
}

func NewHeap[T any](less func(a, b T) bool) *Heap[T] { return &Heap[T]{less: less} }

func (h *Heap[T]) Len() int { return len(h.items) }

func (h *Heap[T]) Push(v T) {
	h.items = append(h.items, v)
	i := len(h.items) - 1
	for i > 0 { // sift up
		parent := (i - 1) / 2
		if !h.less(h.items[i], h.items[parent]) {
			break
		}
		h.items[i], h.items[parent] = h.items[parent], h.items[i]
		i = parent
	}
}

func (h *Heap[T]) Pop() (T, bool) {
	var zero T
	if len(h.items) == 0 {
		return zero, false
	}
	top := h.items[0]
	last := len(h.items) - 1
	h.items[0] = h.items[last]
	h.items[last] = zero
	h.items = h.items[:last]
	i := 0
	for { // sift down
		l, r, small := 2*i+1, 2*i+2, i
		if l < len(h.items) && h.less(h.items[l], h.items[small]) {
			small = l
		}
		if r < len(h.items) && h.less(h.items[r], h.items[small]) {
			small = r
		}
		if small == i {
			break
		}
		h.items[i], h.items[small] = h.items[small], h.items[i]
		i = small
	}
	return top, true
}

type Job struct {
	Priority int
	Name     string
}

func main() {
	h := NewHeap(func(a, b int) bool { return a < b })
	for _, v := range []int{5, 3, 8, 1, 4, 2} {
		h.Push(v)
		fmt.Println("push", v, "->", h.items)
	}
	fmt.Print("pop order:")
	for h.Len() > 0 {
		v, _ := h.Pop()
		fmt.Print(" ", v)
	}
	fmt.Println()

	jobs := NewHeap(func(a, b Job) bool { return a.Priority > b.Priority }) // max-heap
	jobs.Push(Job{1, "send newsletter"})
	jobs.Push(Job{9, "restore database"})
	jobs.Push(Job{5, "resize images"})
	for jobs.Len() > 0 {
		j, _ := jobs.Pop()
		fmt.Printf("%d %s\n", j.Priority, j.Name)
	}
}

