import (
	"fmt"
	"hash/fnv"
)

type Bloom struct {
	bits []uint64
	m    uint64 // number of bits
	k    int    // hashes per item
}

func NewBloom(mBits, k int) *Bloom {
	return &Bloom{bits: make([]uint64, (mBits+63)/64), m: uint64(mBits), k: k}
}

func (b *Bloom) positions(s string) []uint64 {
	h := fnv.New64a()
	h.Write([]byte(s))
	sum := h.Sum64()
	h1, h2 := sum&0xffffffff, sum>>32|1 // |1 keeps h2 odd, so steps never get stuck
	out := make([]uint64, b.k)
	for i := range out {
		out[i] = (h1 + uint64(i)*h2) % b.m
	}
	return out
}

func (b *Bloom) Add(s string) {
	for _, p := range b.positions(s) {
		b.bits[p/64] |= 1 << (p % 64)
	}
}

func (b *Bloom) Has(s string) bool {
	for _, p := range b.positions(s) {
		if b.bits[p/64]&(1<<(p%64)) == 0 {
			return false
		}
	}
	return true
}

func main() {
	f := NewBloom(1024, 3) // 1024 bits = 128 bytes
	for i := range 100 {
		f.Add(fmt.Sprintf("user%d", i))
	}

	missed := 0
	for i := range 100 {
		if !f.Has(fmt.Sprintf("user%d", i)) {
			missed++
		}
	}
	fmt.Println("added items reported missing:", missed)

	falsePos := 0
	for i := 100; i < 1100; i++ {
		if f.Has(fmt.Sprintf("user%d", i)) {
			falsePos++
		}
	}
	fmt.Printf("false positives: %d of 1000 never-added items (%.1f%%)\n", falsePos, float64(falsePos)/10)
	fmt.Println("memory used:", len(f.bits)*8, "bytes for 100 items")
}

