import "fmt"

type Fenwick struct{ tree []int }

func NewFenwick(n int) *Fenwick { return &Fenwick{tree: make([]int, n+1)} }

// Add adds delta to the item at 0-based index i.
func (f *Fenwick) Add(i, delta int) {
	for i++; i < len(f.tree); i += i & -i {
		f.tree[i] += delta
	}
}

// Prefix returns the sum of items [0, i) - the first i items.
func (f *Fenwick) Prefix(i int) int {
	sum := 0
	for ; i > 0; i -= i & -i {
		sum += f.tree[i]
	}
	return sum
}

// Sum returns the sum of items [l, r] inclusive, 0-based.
func (f *Fenwick) Sum(l, r int) int { return f.Prefix(r+1) - f.Prefix(l) }

func main() {
	data := []int{5, 2, 9, -3, 6, 1, 4, 7}
	f := NewFenwick(len(data))
	for i, v := range data {
		f.Add(i, v)
	}
	fmt.Println("data:      ", data)
	fmt.Println("tree cells:", f.tree[1:])
	fmt.Println("sum 0..7 =", f.Sum(0, 7))
	fmt.Println("sum 2..4 =", f.Sum(2, 4))

	f.Add(3, 10) // data[3] becomes 7
	fmt.Println("after adding 10 at index 3:")
	fmt.Println("sum 0..7 =", f.Sum(0, 7))
	fmt.Println("sum 2..4 =", f.Sum(2, 4))
	fmt.Println("sum 4..7 =", f.Sum(4, 7))

	for _, i := range []int{1, 6, 8, 12} {
		fmt.Printf("i=%2d binary=%04b lowest bit i&-i=%d\n", i, i, i&-i)
	}
}

package main

import (
	"fmt"
	"math"
)

type SegTree struct {
	n    int
	tree []int
}

func NewSegTree(data []int) *SegTree {
	s := &SegTree{n: len(data), tree: make([]int, 4*len(data))}
	s.build(1, 0, s.n-1, data)
	return s
}

func (s *SegTree) build(node, lo, hi int, data []int) {
	if lo == hi {
		s.tree[node] = data[lo]
		return
	}
	mid := (lo + hi) / 2
	s.build(2*node, lo, mid, data)
	s.build(2*node+1, mid+1, hi, data)
	s.tree[node] = min(s.tree[2*node], s.tree[2*node+1])
}

// Update sets item i to v.
func (s *SegTree) Update(i, v int) { s.update(1, 0, s.n-1, i, v) }

func (s *SegTree) update(node, lo, hi, i, v int) {
	if lo == hi {
		s.tree[node] = v
		return
	}
	mid := (lo + hi) / 2
	if i <= mid {
		s.update(2*node, lo, mid, i, v)
	} else {
		s.update(2*node+1, mid+1, hi, i, v)
	}
	s.tree[node] = min(s.tree[2*node], s.tree[2*node+1])
}

// Min returns the smallest item in [l, r] inclusive.
func (s *SegTree) Min(l, r int) int { return s.query(1, 0, s.n-1, l, r) }

func (s *SegTree) query(node, lo, hi, l, r int) int {
	if r < lo || hi < l {
		return math.MaxInt // outside: the identity for min
	}
	if l <= lo && hi <= r {
		return s.tree[node] // completely inside
	}
	mid := (lo + hi) / 2
	return min(s.query(2*node, lo, mid, l, r), s.query(2*node+1, mid+1, hi, l, r))
}

func main() {
	temps := []int{21, 19, 24, 17, 22, 26, 18, 23}
	st := NewSegTree(temps)
	fmt.Println("temps:", temps)
	fmt.Println("min 0..7 =", st.Min(0, 7))
	fmt.Println("min 0..2 =", st.Min(0, 2))
	fmt.Println("min 4..7 =", st.Min(4, 7))
	fmt.Println("min 5..5 =", st.Min(5, 5))

	st.Update(3, 30) // the coldest reading is corrected
	fmt.Println("after setting index 3 to 30:")
	fmt.Println("min 0..7 =", st.Min(0, 7))
	fmt.Println("min 2..5 =", st.Min(2, 5))
}

