import "fmt"

type node struct {
	key         int
	height      int
	left, right *node
}

func height(n *node) int {
	if n == nil {
		return 0
	}
	return n.height
}

func fix(n *node)         { n.height = 1 + max(height(n.left), height(n.right)) }
func balance(n *node) int { return height(n.left) - height(n.right) }

func rotateRight(z *node) *node {
	y := z.left
	z.left, y.right = y.right, z
	fix(z)
	fix(y)
	return y
}

func rotateLeft(z *node) *node {
	y := z.right
	z.right, y.left = y.left, z
	fix(z)
	fix(y)
	return y
}

func insert(n *node, key int) *node {
	if n == nil {
		return &node{key: key, height: 1}
	}
	switch {
	case key < n.key:
		n.left = insert(n.left, key)
	case key > n.key:
		n.right = insert(n.right, key)
	default:
		return n // already present
	}
	fix(n)
	switch b := balance(n); {
	case b > 1 && key < n.left.key: // left-left
		return rotateRight(n)
	case b > 1: // left-right
		n.left = rotateLeft(n.left)
		return rotateRight(n)
	case b < -1 && key > n.right.key: // right-right
		return rotateLeft(n)
	case b < -1: // right-left
		n.right = rotateRight(n.right)
		return rotateLeft(n)
	}
	return n
}

func inOrder(n *node, visit func(int)) {
	if n == nil {
		return
	}
	inOrder(n.left, visit)
	visit(n.key)
	inOrder(n.right, visit)
}

func show(n *node, indent string) {
	if n == nil {
		return
	}
	show(n.right, indent+"    ")
	fmt.Printf("%s%d\n", indent, n.key)
	show(n.left, indent+"    ")
}

func main() {
	var root *node
	for key := 1; key <= 7; key++ { // sorted input: the worst case for a plain BST
		root = insert(root, key)
	}
	fmt.Println("tree turned on its side (root at the left):")
	show(root, "")
	fmt.Println("root:", root.key, "height:", root.height)

	var big *node
	for key := 1; key <= 1000; key++ {
		big = insert(big, key)
	}
	fmt.Println("1000 sorted keys -> height", big.height, "(a plain BST would have height 1000)")

	var keys []int
	var mixed *node
	for _, k := range []int{50, 20, 60, 10, 30, 25, 20} {
		mixed = insert(mixed, k)
	}
	inOrder(mixed, func(k int) { keys = append(keys, k) })
	fmt.Println("in-order walk is sorted:", keys)
}

package main

import (
	"fmt"
	"math/rand/v2"
)

const maxLevel = 8

type node struct {
	key  int
	next []*node // next[i] is the following node on level i
}

type SkipList struct {
	head  *node
	level int // levels currently in use
	rng   *rand.Rand
	steps int // nodes visited by the last search (for the demo)
}

func New() *SkipList {
	return &SkipList{head: &node{next: make([]*node, maxLevel)}, level: 1, rng: rand.New(rand.NewPCG(1, 2))}
}

func (s *SkipList) randomLevel() int {
	lvl := 1
	for lvl < maxLevel && s.rng.IntN(2) == 0 {
		lvl++
	}
	return lvl
}

func (s *SkipList) Insert(key int) {
	update := make([]*node, maxLevel)
	x := s.head
	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
		}
		update[i] = x
	}
	if nx := x.next[0]; nx != nil && nx.key == key {
		return // already present
	}
	lvl := s.randomLevel()
	for i := s.level; i < lvl; i++ {
		update[i] = s.head
	}
	s.level = max(s.level, lvl)
	n := &node{key: key, next: make([]*node, lvl)}
	for i := range lvl {
		n.next[i] = update[i].next[i]
		update[i].next[i] = n
	}
}

func (s *SkipList) Contains(key int) bool {
	s.steps = 0
	x := s.head
	for i := s.level - 1; i >= 0; i-- {
		for x.next[i] != nil && x.next[i].key < key {
			x = x.next[i]
			s.steps++
		}
	}
	x = x.next[0]
	return x != nil && x.key == key
}

func main() {
	s := New()
	for _, k := range []int{30, 10, 50, 20, 40, 5, 60, 35} {
		s.Insert(k)
	}
	for i := s.level - 1; i >= 0; i-- {
		fmt.Printf("level %d:", i)
		for x := s.head.next[i]; x != nil; x = x.next[i] {
			fmt.Print(" ", x.key)
		}
		fmt.Println()
	}
	for _, k := range []int{40, 45} {
		fmt.Printf("Contains(%d) = %v\n", k, s.Contains(k))
	}

	big := New()
	for k := range 10000 {
		big.Insert(k)
	}
	big.Contains(9999)
	fmt.Println("10000 keys: finding the last one visited", big.steps, "nodes; a plain list visits 9999")
}

