import "fmt"

// WindowMax returns the maximum of each window of k consecutive items.
func WindowMax(a []int, k int) []int {
	var out []int
	var dq []int // indexes; a[dq[0]] is the largest in the window
	for i, v := range a {
		for len(dq) > 0 && a[dq[len(dq)-1]] <= v {
			dq = dq[:len(dq)-1] // older and not larger: useless now
		}
		dq = append(dq, i)
		if dq[0] <= i-k {
			dq = dq[1:] // slid out of the window
		}
		if i >= k-1 {
			out = append(out, a[dq[0]])
		}
	}
	return out
}

// The obvious O(n*k) version, used to check the fast one.
func slowWindowMax(a []int, k int) []int {
	var out []int
	for i := 0; i+k <= len(a); i++ {
		m := a[i]
		for _, v := range a[i : i+k] {
			m = max(m, v)
		}
		out = append(out, m)
	}
	return out
}

func main() {
	load := []int{3, 1, 4, 1, 5, 9, 2, 6, 5, 3, 5}
	fmt.Println("input:    ", load)
	fast := WindowMax(load, 3)
	fmt.Println("window 3: ", fast)
	fmt.Println("slow way: ", slowWindowMax(load, 3))
	fmt.Println("window 1: ", WindowMax(load, 1))
	fmt.Println("window 11:", WindowMax(load, 11))

	// Trace the deque for the first few steps.
	var dq []int
	for i, v := range load[:6] {
		for len(dq) > 0 && load[dq[len(dq)-1]] <= v {
			dq = dq[:len(dq)-1]
		}
		dq = append(dq, i)
		if dq[0] <= i-3 {
			dq = dq[1:]
		}
		fmt.Printf("i=%d value=%d deque indexes=%v\n", i, v, dq)
	}
}

package main

import (
	"fmt"
	"slices"
)

type entry struct {
	value, count, tick int
}

type LFU struct {
	cap   int
	tick  int
	items map[int]*entry
}

func NewLFU(capacity int) *LFU { return &LFU{cap: capacity, items: map[int]*entry{}} }

func (c *LFU) touch(e *entry) {
	c.tick++
	e.count++
	e.tick = c.tick
}

func (c *LFU) Get(key int) (int, bool) {
	e, ok := c.items[key]
	if !ok {
		return 0, false
	}
	c.touch(e)
	return e.value, true
}

func (c *LFU) Put(key, value int) {
	if e, ok := c.items[key]; ok {
		e.value = value
		c.touch(e)
		return
	}
	if len(c.items) >= c.cap {
		victim, first := 0, true
		for k, e := range c.items {
			v := c.items[victim]
			if first || e.count < v.count || (e.count == v.count && e.tick < v.tick) {
				victim, first = k, false
			}
		}
		delete(c.items, victim)
		fmt.Println("evicted", victim)
	}
	e := &entry{value: value}
	c.items[key] = e
	c.touch(e)
}

func main() {
	c := NewLFU(2)
	get := func(k int) {
		v, ok := c.Get(k)
		fmt.Printf("get %d: %d %v\n", k, v, ok)
	}
	c.Put(1, 10)
	c.Put(2, 20)
	get(1)
	c.Put(3, 30)
	get(2)
	get(3)
	c.Put(4, 40)
	get(1)
	get(3)
	get(4)

	var keys []int
	for k := range c.items {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	fmt.Println("keys:", keys)
}

package main

import (
	"fmt"
	"strconv"
	"strings"
)

// Stage 1 - lexer: text to tokens. Here a token is just a string.
func lex(src string) []string {
	return strings.Fields(strings.ReplaceAll(src, "+", " + "))
}

// Stage 2 - parser: tokens to a tree.
type Node struct {
	Value       int   // used when Left and Right are nil
	Left, Right *Node // used for "+"
}

func parse(tokens []string) (*Node, error) {
	var tree *Node
	for i, tok := range tokens {
		if i%2 == 1 {
			if tok != "+" {
				return nil, fmt.Errorf("expected + but found %q", tok)
			}
			continue
		}
		n, err := strconv.Atoi(tok)
		if err != nil {
			return nil, fmt.Errorf("expected a number but found %q", tok)
		}
		leaf := &Node{Value: n}
		if tree == nil {
			tree = leaf
		} else {
			tree = &Node{Left: tree, Right: leaf}
		}
	}
	if tree == nil || len(tokens)%2 == 0 {
		return nil, fmt.Errorf("incomplete expression")
	}
	return tree, nil
}

// Stage 3 - evaluator: walk the tree.
func eval(n *Node) int {
	if n.Left == nil {
		return n.Value
	}
	return eval(n.Left) + eval(n.Right)
}

func main() {
	for _, src := range []string{"1 + 2", "10+20 + 12", "7", "1 + + 2", "4 +"} {
		tokens := lex(src)
		tree, err := parse(tokens)
		if err != nil {
			fmt.Printf("%-12q tokens=%q error: %v\n", src, tokens, err)
			continue
		}
		fmt.Printf("%-12q tokens=%q = %d\n", src, tokens, eval(tree))
	}
}

