	RPAREN  Kind = "RPAREN"
	ILLEGAL Kind = "ILLEGAL"
	EOF     Kind = "EOF"
)

type Token struct {
	Kind Kind
	Text string
	Col  int // 1-based column where the token starts
}

var single = map[byte]Kind{
	'+': PLUS, '-': MINUS, '*': STAR, '/': SLASH, '=': ASSIGN, '(': LPAREN, ')': RPAREN,
}

func isDigit(c byte) bool  { return c >= '0' && c <= '9' }
func isLetter(c byte) bool { return c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c == '_' }

func Lex(src string) []Token {
	var out []Token
	pos := 0
	for pos < len(src) {
		c := src[pos]
		start := pos
		switch {
		case c == ' ' || c == '\t':
			pos++
			continue
		case isDigit(c):
			for pos < len(src) && isDigit(src[pos]) {
				pos++
			}
			out = append(out, Token{NUMBER, src[start:pos], start + 1})
		case isLetter(c):
			for pos < len(src) && (isLetter(src[pos]) || isDigit(src[pos])) {
				pos++
			}
			out = append(out, Token{IDENT, src[start:pos], start + 1})
		default:
			kind, ok := single[c]
			if !ok {
				kind = ILLEGAL
			}
			pos++
			out = append(out, Token{kind, src[start:pos], start + 1})
		}
	}
	return append(out, Token{EOF, "", pos + 1})
}

func main() {
	for _, src := range []string{"price = (2 + 30) * 4", "count1/x_2 - 7", "3 $ 4"} {
		fmt.Printf("source: %s\n", src)
		for _, t := range Lex(src) {
			fmt.Printf("  col %2d  %-7s %q\n", t.Col, t.Kind, t.Text)
		}
	}
}

