import (
	"fmt"
	"strings"
)

// A minimal lexer: numbers and single-character operators.
func lex(src string) []string {
	var out []string
	for i := 0; i < len(src); {
		c := src[i]
		switch {
		case c == ' ':
			i++
		case c >= '0' && c <= '9':
			j := i
			for j < len(src) && src[j] >= '0' && src[j] <= '9' {
				j++
			}
			out = append(out, src[i:j])
			i = j
		default:
			out = append(out, string(c))
			i++
		}
	}
	return out
}

type Expr interface{ String() string }

type Num struct{ Text string }
type Unary struct {
	Op string
	X  Expr
}
type Binary struct {
	Op   string
	L, R Expr
}

func (n Num) String() string    { return n.Text }
func (u Unary) String() string  { return "(" + u.Op + u.X.String() + ")" }
func (b Binary) String() string { return "(" + b.L.String() + " " + b.Op + " " + b.R.String() + ")" }

var power = map[string]int{"+": 10, "-": 10, "*": 20, "/": 20, "^": 30}
var rightAssoc = map[string]bool{"^": true}

type parseError string

type parser struct {
	toks []string
	pos  int
}

func (p *parser) peek() string {
	if p.pos < len(p.toks) {
		return p.toks[p.pos]
	}
	return "" // end of input
}

func (p *parser) next() string {
	t := p.peek()
	p.pos++
	return t
}

func (p *parser) parsePrefix() Expr {
	t := p.next()
	switch {
	case t == "":
		panic(parseError("unexpected end of input"))
	case t == "(":
		e := p.parseExpr(0)
		if got := p.next(); got != ")" {
			panic(parseError(fmt.Sprintf("expected ) but found %q", got)))
		}
		return e
	case t == "-":
		return Unary{"-", p.parseExpr(25)} // tighter than * and /, looser than ^
	case t[0] >= '0' && t[0] <= '9':
		return Num{t}
	}
	panic(parseError(fmt.Sprintf("unexpected %q", t)))
}

func (p *parser) parseExpr(minPower int) Expr {
	left := p.parsePrefix()
	for power[p.peek()] > minPower {
		op := p.next()
		rp := power[op]
		if rightAssoc[op] {
			rp--
		}
		left = Binary{op, left, p.parseExpr(rp)}
	}
	return left
}

func Parse(src string) (e Expr, err error) {
	defer func() {
		if r := recover(); r != nil {
			pe, ok := r.(parseError)
			if !ok {
				panic(r) // a real bug: let it through
			}
			err = fmt.Errorf("parse error: %s", string(pe))
		}
	}()
	p := &parser{toks: lex(src)}
	e = p.parseExpr(0)
	if p.peek() != "" {
		panic(parseError(fmt.Sprintf("unexpected %q after expression", p.peek())))
	}
	return e, nil
}

func main() {
	for _, src := range []string{
		"1 + 2 * 3", "8 - 3 - 2", "2 ^ 3 ^ 2", "(1 + 2) * 3", "-2 * 3", "-2 ^ 2",
		"1 + 2 * 3 - 4 / 2", "1 +", "(1 + 2", "1 2",
	} {
		e, err := Parse(src)
		if err != nil {
			fmt.Printf("%-18s %v\n", src, err)
			continue
		}
		fmt.Printf("%-18s %s\n", src, strings.TrimSpace(e.String()))
	}
}

