import "fmt"

// ----- the tree -----
type Node interface{}

type (
	Num    struct{ V int }
	Var    struct{ Name string }
	Binary struct {
		Op   string
		L, R Node
	}
	Let struct {
		Name        string
		Value, Body Node
	}
	Fn struct {
		Param string
		Body  Node
	}
	Call struct{ Fn, Arg Node }
	If   struct{ Cond, Then, Else Node }
)

// ----- run-time values -----
type Value any

type Closure struct {
	Param string
	Body  Node
	Env   *Env // where the function was created
}

type Env struct {
	vars   map[string]Value
	parent *Env
}

func NewEnv(parent *Env) *Env { return &Env{vars: map[string]Value{}, parent: parent} }

func (e *Env) Get(name string) Value {
	for env := e; env != nil; env = env.parent {
		if v, ok := env.vars[name]; ok {
			return v
		}
	}
	panic("undefined variable: " + name)
}

func Eval(n Node, env *Env) Value {
	switch n := n.(type) {
	case Num:
		return n.V
	case Var:
		return env.Get(n.Name)
	case Binary:
		l, r := Eval(n.L, env).(int), Eval(n.R, env).(int)
		switch n.Op {
		case "+":
			return l + r
		case "-":
			return l - r
		case "*":
			return l * r
		case "<":
			if l < r {
				return 1
			}
			return 0
		}
		panic("unknown operator " + n.Op)
	case Let:
		inner := NewEnv(env)
		if _, isFn := n.Value.(Fn); isFn {
			inner.vars[n.Name] = Eval(n.Value, inner) // the function can see its own name
		} else {
			inner.vars[n.Name] = Eval(n.Value, env) // "x = x + 1" reads the OUTER x
		}
		return Eval(n.Body, inner)
	case Fn:
		return Closure{n.Param, n.Body, env}
	case Call:
		fn := Eval(n.Fn, env).(Closure)
		arg := Eval(n.Arg, env)
		callEnv := NewEnv(fn.Env) // parent = where it was DEFINED
		callEnv.vars[fn.Param] = arg
		return Eval(fn.Body, callEnv)
	case If:
		if Eval(n.Cond, env).(int) != 0 {
			return Eval(n.Then, env)
		}
		return Eval(n.Else, env)
	}
	panic(fmt.Sprintf("unknown node %T", n))
}

func main() {
	global := NewEnv(nil)

	// (2 + 3) * 4
	fmt.Println(Eval(Binary{"*", Binary{"+", Num{2}, Num{3}}, Num{4}}, global))

	// let x = 10 in (let x = x + 1 in x * 2) + x      -> inner x hides outer x
	fmt.Println(Eval(Let{"x", Num{10},
		Binary{"+", Let{"x", Binary{"+", Var{"x"}, Num{1}}, Binary{"*", Var{"x"}, Num{2}}}, Var{"x"}}}, global))

	// let makeAdder = fn(n) { fn(x) { x + n } } in
	// let add5 = makeAdder(5) in add5(10)
	adder := Let{"makeAdder", Fn{"n", Fn{"x", Binary{"+", Var{"x"}, Var{"n"}}}},
		Let{"add5", Call{Var{"makeAdder"}, Num{5}}, Call{Var{"add5"}, Num{10}}}}
	fmt.Println(Eval(adder, global))

	// let fact = fn(n) { if n < 2 then 1 else n * fact(n - 1) } in fact(10)
	fact := Let{"fact", Fn{"n", If{Binary{"<", Var{"n"}, Num{2}}, Num{1},
		Binary{"*", Var{"n"}, Call{Var{"fact"}, Binary{"-", Var{"n"}, Num{1}}}}}},
		Call{Var{"fact"}, Num{10}}}
	fmt.Println(Eval(fact, global))
}

