import "fmt"

// ----- the tree (built by hand; a parser would produce it) -----
type Node interface{}
type (
	Num    struct{ V int }
	Var    struct{ Name string }
	Binary struct {
		Op   byte
		L, R Node
	}
	Assign struct {
		Name string
		X    Node
	}
	Print struct{ X Node }
)

// ----- bytecode -----
type Op byte

const (
	PUSH Op = iota
	LOAD
	STORE
	ADD
	SUB
	MUL
	PRINT
)

var names = [...]string{"PUSH", "LOAD", "STORE", "ADD", "SUB", "MUL", "PRINT"}

type Instr struct {
	Op  Op
	Arg int
}

func (i Instr) String() string {
	if i.Op <= STORE {
		return fmt.Sprintf("%s %d", names[i.Op], i.Arg)
	}
	return names[i.Op]
}

// ----- compiler -----
type Compiler struct {
	code  []Instr
	slots map[string]int
}

func (c *Compiler) slot(name string) int {
	if i, ok := c.slots[name]; ok {
		return i
	}
	c.slots[name] = len(c.slots)
	return c.slots[name]
}

func (c *Compiler) emit(op Op, arg int) { c.code = append(c.code, Instr{op, arg}) }

func (c *Compiler) Compile(n Node) {
	switch n := n.(type) {
	case Num:
		c.emit(PUSH, n.V)
	case Var:
		c.emit(LOAD, c.slot(n.Name))
	case Binary:
		c.Compile(n.L)
		c.Compile(n.R)
		c.emit(map[byte]Op{'+': ADD, '-': SUB, '*': MUL}[n.Op], 0)
	case Assign:
		c.Compile(n.X)
		c.emit(STORE, c.slot(n.Name))
	case Print:
		c.Compile(n.X)
		c.emit(PRINT, 0)
	}
}

// ----- virtual machine -----
func Run(code []Instr, nvars int, trace bool) {
	vars := make([]int, nvars)
	var stack []int
	pop := func() int {
		v := stack[len(stack)-1]
		stack = stack[:len(stack)-1]
		return v
	}
	for pc := 0; pc < len(code); pc++ {
		in := code[pc]
		switch in.Op {
		case PUSH:
			stack = append(stack, in.Arg)
		case LOAD:
			stack = append(stack, vars[in.Arg])
		case STORE:
			vars[in.Arg] = pop()
		case ADD, SUB, MUL:
			b, a := pop(), pop() // b was pushed last
			switch in.Op {
			case ADD:
				stack = append(stack, a+b)
			case SUB:
				stack = append(stack, a-b)
			case MUL:
				stack = append(stack, a*b)
			}
		case PRINT:
			fmt.Println("  output:", pop())
		}
		if trace {
			fmt.Printf("  %2d %-8v stack=%v\n", pc, in, stack)
		}
	}
}

func main() {
	// x = (2 + 3) * 4
	// y = x - 5
	// print y * x
	program := []Node{
		Assign{"x", Binary{'*', Binary{'+', Num{2}, Num{3}}, Num{4}}},
		Assign{"y", Binary{'-', Var{"x"}, Num{5}}},
		Print{Binary{'*', Var{"y"}, Var{"x"}}},
	}
	c := &Compiler{slots: map[string]int{}}
	for _, stmt := range program {
		c.Compile(stmt)
	}
	fmt.Println("compiled to", len(c.code), "instructions, variables:", len(c.slots))
	Run(c.code, len(c.slots), true)
}

