import "fmt"

type Node interface{ String() string }

type Num struct{ V int }
type Var struct{ Name string }
type Binary struct {
	Op   byte
	L, R Node
}

func (n Num) String() string    { return fmt.Sprint(n.V) }
func (v Var) String() string    { return v.Name }
func (b Binary) String() string { return fmt.Sprintf("(%v %c %v)", b.L, b.Op, b.R) }

func isNum(n Node, v int) bool {
	num, ok := n.(Num)
	return ok && num.V == v
}

func Fold(n Node) Node {
	b, ok := n.(Binary)
	if !ok {
		return n
	}
	l, r := Fold(b.L), Fold(b.R)
	ln, lok := l.(Num)
	rn, rok := r.(Num)
	if lok && rok {
		switch b.Op {
		case '+':
			return Num{ln.V + rn.V}
		case '-':
			return Num{ln.V - rn.V}
		case '*':
			return Num{ln.V * rn.V}
		case '/':
			if rn.V != 0 {
				return Num{ln.V / rn.V}
			}
		}
	}
	switch {
	case b.Op == '+' && isNum(r, 0), b.Op == '*' && isNum(r, 1):
		return l
	case b.Op == '+' && isNum(l, 0), b.Op == '*' && isNum(l, 1):
		return r
	case b.Op == '*' && (isNum(l, 0) || isNum(r, 0)):
		return Num{0}
	}
	return Binary{b.Op, l, r}
}

func main() {
	x, y := Var{"x"}, Var{"y"}
	exprs := []Node{
		Binary{'*', Binary{'+', Num{2}, Num{3}}, x},
		Binary{'*', Binary{'+', x, Num{0}}, Binary{'*', Num{1}, y}},
		Binary{'-', Binary{'*', Num{4}, Num{5}}, Binary{'/', Num{6}, Num{2}}},
		Binary{'*', x, Binary{'-', Num{2}, Num{2}}},
		Binary{'+', Binary{'+', x, Num{1}}, Binary{'*', Num{2}, Num{3}}},
		Binary{'/', Num{8}, Binary{'-', Num{3}, Num{3}}},
	}
	for _, e := range exprs {
		fmt.Printf("%v  ->  %v\n", e, Fold(e))
	}
}

