import (
	"bufio"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
)

type DB struct {
	f    *os.File
	data map[string]string
}

func Open(path string) (*DB, error) {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return nil, err
	}
	db := &DB{f: f, data: map[string]string{}}
	sc := bufio.NewScanner(f) // replay the log
	for sc.Scan() {
		parts := strings.Split(sc.Text(), "\t")
		switch {
		case parts[0] == "set" && len(parts) == 3:
			db.data[parts[1]] = parts[2]
		case parts[0] == "del" && len(parts) == 2:
			delete(db.data, parts[1])
		}
	}
	return db, sc.Err()
}

func (db *DB) write(line string) error {
	if _, err := db.f.WriteString(line + "\n"); err != nil {
		return err
	}
	return db.f.Sync() // durable before we report success
}

func (db *DB) Set(key, value string) error {
	if err := db.write("set\t" + key + "\t" + value); err != nil {
		return err
	}
	db.data[key] = value
	return nil
}

func (db *DB) Delete(key string) error {
	if err := db.write("del\t" + key); err != nil {
		return err
	}
	delete(db.data, key)
	return nil
}

func (db *DB) Get(key string) (string, bool) {
	v, ok := db.data[key]
	return v, ok
}

func (db *DB) Close() error { return db.f.Close() }

func main() {
	dir, _ := os.MkdirTemp("", "logdb-*")
	defer os.RemoveAll(dir)
	path := filepath.Join(dir, "data.log")

	db, err := Open(path)
	if err != nil {
		fmt.Println("open:", err)
		return
	}
	db.Set("name", "Ada")
	db.Set("city", "Cairo")
	db.Set("name", "Grace")
	db.Delete("city")
	db.Set("lang", "Go")
	db.Close() // the program "stops" here

	raw, _ := os.ReadFile(path)
	fmt.Print("the file on disk:\n", strings.ReplaceAll(string(raw), "\t", " | "))

	db, _ = Open(path) // a new run: state is rebuilt from the file
	defer db.Close()
	keys := make([]string, 0, len(db.data))
	for k := range db.data {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	fmt.Println("after restart:")
	for _, k := range keys {
		fmt.Printf("  %s = %s\n", k, db.data[k])
	}
	_, ok := db.Get("city")
	fmt.Println("city present:", ok)
}

