import (
	"encoding/binary"
	"fmt"
	"hash/crc32"
)

const headerSize = 12

func encode(key, value string) []byte {
	buf := make([]byte, headerSize+len(key)+len(value))
	binary.LittleEndian.PutUint32(buf[4:], uint32(len(key)))
	binary.LittleEndian.PutUint32(buf[8:], uint32(len(value)))
	copy(buf[headerSize:], key)
	copy(buf[headerSize+len(key):], value)
	// The checksum covers everything after itself.
	binary.LittleEndian.PutUint32(buf[0:], crc32.ChecksumIEEE(buf[4:]))
	return buf
}

type Record struct{ Key, Value string }

// recoverLog returns the good records, how many bytes they occupy,
// and why reading stopped.
func recoverLog(data []byte) (recs []Record, good int, why string) {
	for good < len(data) {
		rest := data[good:]
		if len(rest) < headerSize {
			return recs, good, "torn header"
		}
		sum := binary.LittleEndian.Uint32(rest[0:])
		klen := int(binary.LittleEndian.Uint32(rest[4:]))
		vlen := int(binary.LittleEndian.Uint32(rest[8:]))
		size := headerSize + klen + vlen
		if klen < 0 || vlen < 0 || size > len(rest) {
			return recs, good, "torn record"
		}
		if crc32.ChecksumIEEE(rest[4:size]) != sum {
			return recs, good, "checksum mismatch"
		}
		recs = append(recs, Record{string(rest[headerSize : headerSize+klen]), string(rest[headerSize+klen : size])})
		good += size
	}
	return recs, good, "clean end"
}

func report(name string, data []byte) {
	recs, good, why := recoverLog(data)
	fmt.Printf("%-22s %d bytes, %d good (%s), drop %d bytes\n", name+":", len(data), good, why, len(data)-good)
	for _, r := range recs {
		fmt.Printf("    %q = %q\n", r.Key, r.Value)
	}
}

func main() {
	var log []byte
	log = append(log, encode("name", "Ada")...)
	log = append(log, encode("note", "line one\nline two\ttabbed")...)
	log = append(log, encode("city", "Cairo")...)

	report("intact log", log)

	torn := log[:len(log)-3] // power failed 3 bytes before the end
	report("torn last record", torn)

	flipped := append([]byte(nil), log...)
	flipped[40] ^= 0x01 // one bit changes inside the second record's value
	report("bit flip in record 2", flipped)
}

package main

import (
	"encoding/binary"
	"fmt"
	"os"
	"path/filepath"
	"slices"
)

type loc struct {
	off int64 // where the VALUE starts in the file
	n   int   // its length
}

type DB struct {
	path  string
	f     *os.File
	size  int64
	index map[string]loc
}

func Open(path string) (*DB, error) {
	f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE|os.O_APPEND, 0o644)
	if err != nil {
		return nil, err
	}
	return &DB{path: path, f: f, index: map[string]loc{}}, nil
}

func record(key, value string) []byte {
	buf := make([]byte, 8, 8+len(key)+len(value))
	binary.LittleEndian.PutUint32(buf[0:], uint32(len(key)))
	binary.LittleEndian.PutUint32(buf[4:], uint32(len(value)))
	return append(append(buf, key...), value...)
}

func (db *DB) Set(key, value string) error {
	rec := record(key, value)
	if _, err := db.f.Write(rec); err != nil {
		return err
	}
	db.index[key] = loc{off: db.size + 8 + int64(len(key)), n: len(value)}
	db.size += int64(len(rec))
	return nil
}

func (db *DB) Get(key string) (string, error) {
	l, ok := db.index[key]
	if !ok {
		return "", fmt.Errorf("key %q not found", key)
	}
	buf := make([]byte, l.n)
	if _, err := db.f.ReadAt(buf, l.off); err != nil {
		return "", err
	}
	return string(buf), nil
}

func (db *DB) Compact() error {
	tmp := db.path + ".tmp"
	fresh, err := Open(tmp)
	if err != nil {
		return err
	}
	keys := make([]string, 0, len(db.index))
	for k := range db.index {
		keys = append(keys, k)
	}
	slices.Sort(keys)
	for _, k := range keys {
		v, err := db.Get(k)
		if err != nil {
			return err
		}
		if err := fresh.Set(k, v); err != nil {
			return err
		}
	}
	if err := fresh.f.Sync(); err != nil {
		return err
	}
	if err := os.Rename(tmp, db.path); err != nil { // atomic swap
		return err
	}
	db.f.Close()
	db.f, db.size, db.index = fresh.f, fresh.size, fresh.index
	return nil
}

func main() {
	dir, _ := os.MkdirTemp("", "bitcask-*")
	defer os.RemoveAll(dir)
	db, err := Open(filepath.Join(dir, "data.log"))
	if err != nil {
		fmt.Println("open:", err)
		return
	}
	defer db.f.Close()

	for i := range 1000 {
		db.Set("counter", fmt.Sprint(i)) // the same key, 1000 times
	}
	db.Set("name", "Ada")
	db.Set("name", "Grace")

	v, _ := db.Get("counter")
	fmt.Println("counter =", v, "at", db.index["counter"])
	fmt.Println("file size before compaction:", db.size, "bytes for", len(db.index), "keys")

	if err := db.Compact(); err != nil {
		fmt.Println("compact:", err)
		return
	}
	fmt.Println("file size after compaction: ", db.size, "bytes")
	v, _ = db.Get("counter")
	n, _ := db.Get("name")
	fmt.Println("counter =", v, "at", db.index["counter"], "| name =", n)
	_, err = db.Get("missing")
	fmt.Println("error:", err)
}

