	"sort"
)

const every = 16 // one index entry per 16 records

type indexEntry struct {
	key string
	off int
}

type SSTable struct {
	data  []byte
	index []indexEntry
}

type KV struct{ Key, Value string }

// Build expects pairs already sorted by key.
func Build(pairs []KV) *SSTable {
	t := &SSTable{}
	for i, p := range pairs {
		if i%every == 0 {
			t.index = append(t.index, indexEntry{p.Key, len(t.data)})
		}
		t.data = binary.LittleEndian.AppendUint16(t.data, uint16(len(p.Key)))
		t.data = binary.LittleEndian.AppendUint16(t.data, uint16(len(p.Value)))
		t.data = append(t.data, p.Key...)
		t.data = append(t.data, p.Value...)
	}
	return t
}

// Get returns the value and how many records it had to read.
func (t *SSTable) Get(key string) (value string, found bool, scanned int) {
	// first index entry whose key is greater than the target
	i := sort.Search(len(t.index), func(i int) bool { return t.index[i].key > key })
	if i == 0 {
		return "", false, 0 // smaller than every key in the table
	}
	off := t.index[i-1].off
	for off < len(t.data) && scanned < every {
		klen := int(binary.LittleEndian.Uint16(t.data[off:]))
		vlen := int(binary.LittleEndian.Uint16(t.data[off+2:]))
		k := string(t.data[off+4 : off+4+klen])
		scanned++
		if k == key {
			return string(t.data[off+4+klen : off+4+klen+vlen]), true, scanned
		}
		if k > key {
			break // sorted: it cannot be further on
		}
		off += 4 + klen + vlen
	}
	return "", false, scanned
}

func main() {
	var pairs []KV
	for i := 0; i < 1000; i += 2 { // even numbers only
		pairs = append(pairs, KV{fmt.Sprintf("key%04d", i), fmt.Sprintf("value-%d", i)})
	}
	t := Build(pairs)
	fmt.Printf("%d records, %d bytes on disk, %d index entries in memory\n", len(pairs), len(t.data), len(t.index))

	for _, k := range []string{"key0000", "key0500", "key0998", "key0501", "key9999", "aaa"} {
		v, ok, n := t.Get(k)
		fmt.Printf("Get(%s) = %-10q found=%-5v records read: %d\n", k, v, ok, n)
	}
}

package main

import (
	"cmp"
	"fmt"
	"slices"
)

type entry struct {
	key, value string
	deleted    bool // a tombstone
}

type LSM struct {
	mem   map[string]entry
	limit int
	runs  [][]entry // runs[0] is the newest
}

func New(limit int) *LSM { return &LSM{mem: map[string]entry{}, limit: limit} }

func (l *LSM) put(e entry) {
	l.mem[e.key] = e
	if len(l.mem) >= l.limit {
		l.Flush()
	}
}

func (l *LSM) Set(key, value string) { l.put(entry{key: key, value: value}) }
func (l *LSM) Delete(key string)     { l.put(entry{key: key, deleted: true}) }

func (l *LSM) Flush() {
	if len(l.mem) == 0 {
		return
	}
	run := make([]entry, 0, len(l.mem))
	for _, e := range l.mem {
		run = append(run, e)
	}
	slices.SortFunc(run, func(a, b entry) int { return cmp.Compare(a.key, b.key) })
	l.runs = append([][]entry{run}, l.runs...)
	l.mem = map[string]entry{}
}

// Get also reports where the answer was found.
func (l *LSM) Get(key string) (string, bool, string) {
	if e, ok := l.mem[key]; ok {
		return e.value, !e.deleted, "memtable"
	}
	for i, run := range l.runs {
		pos, ok := slices.BinarySearchFunc(run, key, func(e entry, k string) int { return cmp.Compare(e.key, k) })
		if ok {
			return run[pos].value, !run[pos].deleted, fmt.Sprintf("run %d", i)
		}
	}
	return "", false, "nowhere"
}

// Compact merges every run into one, keeping only the newest version
// of each key and dropping tombstones.
func (l *LSM) Compact() {
	newest := map[string]entry{}
	for i := len(l.runs) - 1; i >= 0; i-- { // oldest first, so newer overwrite
		for _, e := range l.runs[i] {
			newest[e.key] = e
		}
	}
	var merged []entry
	for _, e := range newest {
		if !e.deleted {
			merged = append(merged, e)
		}
	}
	slices.SortFunc(merged, func(a, b entry) int { return cmp.Compare(a.key, b.key) })
	l.runs = [][]entry{merged}
}

func (l *LSM) show(title string) {
	fmt.Println(title)
	fmt.Println("  memtable entries:", len(l.mem))
	for i, run := range l.runs {
		fmt.Printf("  run %d:", i)
		for _, e := range run {
			if e.deleted {
				fmt.Printf(" %s=<deleted>", e.key)
			} else {
				fmt.Printf(" %s=%s", e.key, e.value)
			}
		}
		fmt.Println()
	}
}

func main() {
	db := New(3) // flush after 3 entries
	db.Set("a", "1")
	db.Set("b", "2")
	db.Set("c", "3") // flush -> first run
	db.Set("a", "10")
	db.Delete("b")
	db.Set("d", "4") // flush -> second run
	db.Set("e", "5")
	db.show("before compaction:")

	for _, k := range []string{"a", "b", "c", "e", "z"} {
		v, ok, where := db.Get(k)
		fmt.Printf("  Get(%s) = %q found=%-5v (%s)\n", k, v, ok, where)
	}

	db.Flush()
	db.Compact()
	db.show("after flush and compaction:")
}

package main

import (
	"errors"
	"fmt"
)

type version struct {
	ts    int
	value int
}

type Store struct {
	clock    int
	versions map[string][]version // oldest first
}

var ErrConflict = errors.New("write conflict: another transaction committed first")

type Tx struct {
	s      *Store
	start  int
	writes map[string]int
}

func NewStore() *Store { return &Store{versions: map[string][]version{}} }

func (s *Store) Begin() *Tx { return &Tx{s: s, start: s.clock, writes: map[string]int{}} }

func (tx *Tx) Get(key string) (int, bool) {
	if v, ok := tx.writes[key]; ok {
		return v, true // a transaction sees its own writes
	}
	vs := tx.s.versions[key]
	for i := len(vs) - 1; i >= 0; i-- { // newest first
		if vs[i].ts <= tx.start {
			return vs[i].value, true
		}
	}
	return 0, false
}

func (tx *Tx) Set(key string, value int) { tx.writes[key] = value }

func (tx *Tx) Commit() error {
	for key := range tx.writes {
		vs := tx.s.versions[key]
		if len(vs) > 0 && vs[len(vs)-1].ts > tx.start {
			return ErrConflict
		}
	}
	tx.s.clock++
	for key, value := range tx.writes {
		tx.s.versions[key] = append(tx.s.versions[key], version{tx.s.clock, value})
	}
	return nil
}

func main() {
	s := NewStore()
	setup := s.Begin()
	setup.Set("alice", 100)
	setup.Set("bob", 50)
	fmt.Println("setup commit:", setup.Commit())

	// 1. A long-running report keeps a stable view.
	report := s.Begin()
	transfer := s.Begin()
	a, _ := transfer.Get("alice")
	b, _ := transfer.Get("bob")
	transfer.Set("alice", a-30)
	transfer.Set("bob", b+30)
	fmt.Println("transfer commit:", transfer.Commit())

	ra, _ := report.Get("alice")
	rb, _ := report.Get("bob")
	fmt.Println("report (began before the transfer) sees:", ra, rb, "total", ra+rb)
	now := s.Begin()
	na, _ := now.Get("alice")
	nb, _ := now.Get("bob")
	fmt.Println("a new transaction sees:                 ", na, nb, "total", na+nb)

	// 2. Two transactions change the same key: the first to commit wins.
	t1, t2 := s.Begin(), s.Begin()
	v1, _ := t1.Get("alice")
	v2, _ := t2.Get("alice")
	t1.Set("alice", v1+10)
	t2.Set("alice", v2+500)
	fmt.Println("t1 commit:", t1.Commit())
	fmt.Println("t2 commit:", t2.Commit())

	// 3. The loser retries from the start and now succeeds.
	t3 := s.Begin()
	v3, _ := t3.Get("alice")
	t3.Set("alice", v3+500)
	fmt.Println("t2 retried commit:", t3.Commit())

	fmt.Println("version history of alice:", s.versions["alice"])
}

package main

import (
	"fmt"
	"iter"
)

type Row struct {
	Name   string
	Dept   string
	Salary int
}

func Scan(rows []Row, scanned *int) iter.Seq[Row] {
	return func(yield func(Row) bool) {
		for _, r := range rows {
			*scanned++
			if !yield(r) {
				return
			}
		}
	}
}

func Filter(in iter.Seq[Row], keep func(Row) bool) iter.Seq[Row] {
	return func(yield func(Row) bool) {
		for r := range in {
			if keep(r) && !yield(r) {
				return
			}
		}
	}
}

func Limit(in iter.Seq[Row], n int) iter.Seq[Row] {
	return func(yield func(Row) bool) {
		if n <= 0 {
			return
		}
		count := 0
		for r := range in {
			if !yield(r) {
				return
			}
			if count++; count == n {
				return
			}
		}
	}
}

func main() {
	employees := []Row{
		{"Ada", "eng", 120}, {"Bob", "sales", 90}, {"Cleo", "eng", 95}, {"Dan", "eng", 130},
		{"Eve", "ops", 110}, {"Finn", "eng", 150}, {"Gus", "eng", 125},
	}
	wellPaidEng := func(r Row) bool { return r.Dept == "eng" && r.Salary > 100 }

	scanned := 0
	for r := range Limit(Filter(Scan(employees, &scanned), wellPaidEng), 2) {
		fmt.Println(r.Name, r.Salary)
	}
	fmt.Println("rows scanned:", scanned)

	scanned = 0
	for r := range Filter(Scan(employees, &scanned), wellPaidEng) {
		fmt.Println(r.Name, r.Salary)
	}
	fmt.Println("rows scanned:", scanned)
}

package main

import (
	"errors"
	"fmt"
)

var errTimeout = errors.New("timeout: no reply")

type Server struct {
	balance    int
	done       map[string]int // idempotency key -> saved reply
	idempotent bool
}

func (s *Server) Charge(key string, amount int) int {
	if s.idempotent {
		if reply, ok := s.done[key]; ok {
			return reply // already done: just repeat the answer
		}
	}
	s.balance -= amount
	if s.idempotent {
		s.done[key] = s.balance
	}
	return s.balance
}

// A scripted network: each call uses up the next fault.
type Network struct {
	faults []string // "ok", "request lost" or "reply lost"
	srv    *Server
}

func (n *Network) Send(key string, amount int) (int, error) {
	fault := n.faults[0]
	n.faults = n.faults[1:]
	if fault == "request lost" {
		return 0, errTimeout
	}
	reply := n.srv.Charge(key, amount) // the server does the work...
	if fault == "reply lost" {
		return 0, errTimeout // ...but the client never hears about it
	}
	return reply, nil
}

func chargeWithRetry(n *Network, key string, amount int) {
	for attempt := 1; attempt <= 3; attempt++ {
		reply, err := n.Send(key, amount)
		if err != nil {
			fmt.Printf("    %s attempt %d: %v, retrying\n", key, attempt, err)
			continue
		}
		fmt.Printf("    %s attempt %d: ok, server says balance is %d\n", key, attempt, reply)
		return
	}
}

func run(idempotent bool) {
	srv := &Server{balance: 100, done: map[string]int{}, idempotent: idempotent}
	net := &Network{srv: srv, faults: []string{"reply lost", "ok", "request lost", "ok", "ok"}}
	chargeWithRetry(net, "pay-1", 30)
	chargeWithRetry(net, "pay-2", 20)
	chargeWithRetry(net, "pay-3", 10)
	fmt.Printf("  final balance: %d (correct is 40)\n", srv.balance)
}

func main() {
	fmt.Println("server WITHOUT idempotency keys:")
	run(false)
	fmt.Println("server WITH idempotency keys:")
	run(true)
}

package main

import (
	"crypto/sha256"
	"encoding/binary"
	"fmt"
	"sort"
)

func hash(s string) uint64 {
	sum := sha256.Sum256([]byte(s))
	return binary.BigEndian.Uint64(sum[:8])
}

type point struct {
	hash uint64
	node string
}

type Ring struct {
	points []point
	vnodes int
}

func NewRing(vnodes int, nodes ...string) *Ring {
	r := &Ring{vnodes: vnodes}
	for _, n := range nodes {
		r.Add(n)
	}
	return r
}

func (r *Ring) Add(node string) {
	for i := range r.vnodes {
		r.points = append(r.points, point{hash(fmt.Sprintf("%s#%d", node, i)), node})
	}
	sort.Slice(r.points, func(i, j int) bool { return r.points[i].hash < r.points[j].hash })
}

func (r *Ring) Lookup(key string) string {
	h := hash(key)
	i := sort.Search(len(r.points), func(i int) bool { return r.points[i].hash >= h })
	if i == len(r.points) {
		i = 0 // wrap around the ring
	}
	return r.points[i].node
}

func modLookup(key string, nodes []string) string {
	return nodes[hash(key)%uint64(len(nodes))]
}

func main() {
	const total = 10000
	keys := make([]string, total)
	for i := range keys {
		keys[i] = fmt.Sprintf("user:%d", i)
	}
	four := []string{"A", "B", "C", "D"}
	five := append(four[:4:4], "E")

	moved := 0
	for _, k := range keys {
		if modLookup(k, four) != modLookup(k, five) {
			moved++
		}
	}
	fmt.Printf("hash %% N:           adding a 5th server moves %d%% of keys\n", moved*100/total)

	ring := NewRing(200, four...)
	before := make([]string, total)
	for i, k := range keys {
		before[i] = ring.Lookup(k)
	}
	ring.Add("E")
	moved = 0
	load := map[string]int{}
	for i, k := range keys {
		now := ring.Lookup(k)
		load[now]++
		if now != before[i] {
			moved++
		}
	}
	fmt.Printf("consistent hashing: adding a 5th server moves %d%% of keys\n", moved*100/total)
	fmt.Print("share of keys per server:")
	for _, n := range five {
		fmt.Printf(" %s=%d%%", n, load[n]*100/total)
	}
	fmt.Println()

	one := NewRing(1, five...)
	load = map[string]int{}
	for _, k := range keys {
		load[one.Lookup(k)]++
	}
	fmt.Print("with only 1 point each:  ")
	for _, n := range five {
		fmt.Printf(" %s=%d%%", n, load[n]*100/total)
	}
	fmt.Println()
}

package main

import "fmt"

const (
	A = iota
	B
	C
)

type Vector [3]int

type Node struct {
	id      int
	lamport int
	vec     Vector
}

type Message struct {
	lamport int
	vec     Vector
}

func (n *Node) Local() {
	n.lamport++
	n.vec[n.id]++
}

func (n *Node) Send() Message {
	n.Local()
	return Message{n.lamport, n.vec}
}

func (n *Node) Receive(m Message) {
	n.lamport = max(n.lamport, m.lamport) + 1
	for i := range n.vec {
		n.vec[i] = max(n.vec[i], m.vec[i])
	}
	n.vec[n.id]++
}

func compare(v, w Vector) string {
	less, greater := false, false
	for i := range v {
		if v[i] < w[i] {
			less = true
		}
		if v[i] > w[i] {
			greater = true
		}
	}
	switch {
	case less && greater:
		return "CONCURRENT"
	case less:
		return "BEFORE"
	case greater:
		return "AFTER"
	}
	return "EQUAL"
}

func main() {
	a, b, c := &Node{id: A}, &Node{id: B}, &Node{id: C}
	type snap struct {
		name    string
		lamport int
		vec     Vector
	}
	var events []snap
	record := func(name string, n *Node) {
		events = append(events, snap{name, n.lamport, n.vec})
		fmt.Printf("%-22s lamport=%d vector=%v\n", name, n.lamport, n.vec)
	}

	m1 := a.Send()
	record("A sends m1", a)
	c.Local()
	record("C local edit", c)
	b.Receive(m1)
	record("B receives m1", b)
	m2 := b.Send()
	record("B sends m2", b)
	c.Receive(m2)
	record("C receives m2", c)
	a.Local()
	record("A local edit", a)

	fmt.Println()
	pairs := [][2]int{{0, 2}, {0, 1}, {1, 4}, {3, 5}}
	for _, p := range pairs {
		x, y := events[p[0]], events[p[1]]
		fmt.Printf("%-14s vs %-14s -> %-10s (lamport %d vs %d)\n", x.name, y.name, compare(x.vec, y.vec), x.lamport, y.lamport)
	}
}

package main

import "fmt"

type GCounter map[string]int

func (g GCounter) Inc(replica string, n int) { g[replica] += n }

func (g GCounter) Value() int {
	total := 0
	for _, n := range g {
		total += n
	}
	return total
}

func (g GCounter) Merge(other GCounter) {
	for replica, n := range other {
		g[replica] = max(g[replica], n)
	}
}

type PNCounter struct {
	id   string
	p, n GCounter
}

func NewPN(id string) *PNCounter { return &PNCounter{id, GCounter{}, GCounter{}} }

func (c *PNCounter) Add(n int) {
	if n >= 0 {
		c.p.Inc(c.id, n)
	} else {
		c.n.Inc(c.id, -n)
	}
}
func (c *PNCounter) Value() int { return c.p.Value() - c.n.Value() }
func (c *PNCounter) Merge(o *PNCounter) {
	c.p.Merge(o.p)
	c.n.Merge(o.n)
}

func main() {
	// Three replicas of a "stock level" counter, working while disconnected.
	cairo, paris, tokyo := NewPN("cairo"), NewPN("paris"), NewPN("tokyo")
	cairo.Add(10) // delivery arrives
	paris.Add(-3) // three sold
	tokyo.Add(5)
	tokyo.Add(-4)
	cairo.Add(-1)
	fmt.Println("while disconnected:", cairo.Value(), paris.Value(), tokyo.Value())

	// Merges happen in a messy order, some of them twice.
	paris.Merge(cairo)
	tokyo.Merge(paris)
	tokyo.Merge(paris) // a repeat changes nothing
	cairo.Merge(tokyo)
	paris.Merge(tokyo)
	fmt.Println("after merging:     ", cairo.Value(), paris.Value(), tokyo.Value())
	fmt.Println("cairo's view of the increments:", cairo.p["cairo"], cairo.p["paris"], cairo.p["tokyo"])
	fmt.Println("cairo's view of the decrements:", cairo.n["cairo"], cairo.n["paris"], cairo.n["tokyo"])

	// Why adding is the wrong merge.
	a, b := GCounter{"a": 3}, GCounter{"a": 3, "b": 2}
	a.Merge(b)
	a.Merge(b)
	fmt.Println("max-merge twice:", a.Value(), "| naive add-merge twice would give", 3+5+5)
}

package main

import "fmt"

type versioned struct {
	version int
	value   string
}

type Cluster struct {
	replicas []versioned
	version  int
}

// Write stores the value on the reachable replicas. It succeeds only
// if at least w of them confirm.
func (c *Cluster) Write(value string, w int, reachable ...int) bool {
	if len(reachable) < w {
		return false
	}
	c.version++
	for _, i := range reachable {
		c.replicas[i] = versioned{c.version, value}
	}
	return true
}

// Read asks the given replicas and returns the newest answer,
// repairing any replica that was behind.
func (c *Cluster) Read(r int, ask ...int) (string, bool) {
	if len(ask) < r {
		return "", false
	}
	newest := versioned{}
	for _, i := range ask {
		if c.replicas[i].version > newest.version {
			newest = c.replicas[i]
		}
	}
	for _, i := range ask {
		if c.replicas[i].version < newest.version {
			fmt.Printf("    read repair: replica %d updated to version %d\n", i, newest.version)
			c.replicas[i] = newest
		}
	}
	return newest.value, true
}

func (c *Cluster) show() {
	fmt.Print("    replicas:")
	for i, r := range c.replicas {
		fmt.Printf("  [%d] v%d %q", i, r.version, r.value)
	}
	fmt.Println()
}

func main() {
	fmt.Println("N=3 W=2 R=2 (R + W > N):")
	c := &Cluster{replicas: make([]versioned, 3)}
	c.Write("blue", 2, 0, 1, 2)
	ok := c.Write("green", 2, 0, 1) // replica 2 is down and misses it
	fmt.Println("  write green confirmed:", ok)
	c.show()
	v, _ := c.Read(2, 1, 2) // includes the stale replica
	fmt.Println("  read from replicas 1 and 2:", v)
	c.show()
	ok = c.Write("red", 2, 2) // only one replica reachable
	fmt.Println("  write red with one replica up confirmed:", ok)

	fmt.Println("N=3 W=1 R=1 (R + W = 2, not > N):")
	c = &Cluster{replicas: make([]versioned, 3)}
	c.Write("blue", 1, 0, 1, 2)
	c.Write("green", 1, 0) // confirmed by one replica only
	c.show()
	v, _ = c.Read(1, 2)
	fmt.Println("  read from replica 2:", v, " <- stale: the confirmed write is missed")
}

package main

import "fmt"

type Node struct {
	name     string
	term     int
	votedFor string // who this node voted for in its current term
	role     string
}

// RequestVote is called on a node by a candidate.
func (n *Node) RequestVote(candidate string, term int) bool {
	if term < n.term {
		return false // a request from the past
	}
	if term > n.term {
		n.term, n.votedFor, n.role = term, "", "follower" // newer term: forget the old vote
	}
	if n.votedFor == "" || n.votedFor == candidate {
		n.votedFor = candidate
		return true
	}
	return false // already voted for someone else this term
}

// SeeTerm is called whenever a node receives any message: a higher
// term means this node is out of date and must step down.
func (n *Node) SeeTerm(term int) {
	if term > n.term {
		n.term, n.votedFor, n.role = term, "", "follower"
	}
}

func StartElection(c *Node, cluster []*Node, reachable map[string]bool) {
	c.term++
	c.role, c.votedFor = "candidate", c.name
	votes := 1 // its own
	fmt.Printf("%s times out, starts election for term %d\n", c.name, c.term)
	for _, n := range cluster {
		if n == c || !reachable[n.name] {
			continue
		}
		granted := n.RequestVote(c.name, c.term)
		fmt.Printf("    %s -> %s: vote granted = %v\n", n.name, c.name, granted)
		if granted {
			votes++
		}
	}
	if votes > len(cluster)/2 {
		c.role = "leader"
		fmt.Printf("    %s wins with %d of %d votes: LEADER of term %d\n", c.name, votes, len(cluster), c.term)
		return
	}
	fmt.Printf("    %s has only %d of %d votes: no leader this term\n", c.name, votes, len(cluster))
}

func main() {
	a, b, c, d, e := &Node{name: "A", role: "follower"}, &Node{name: "B", role: "follower"},
		&Node{name: "C", role: "follower"}, &Node{name: "D", role: "follower"}, &Node{name: "E", role: "follower"}
	cluster := []*Node{a, b, c, d, e}
	all := map[string]bool{"A": true, "B": true, "C": true, "D": true, "E": true}

	// 1. A normal election.
	StartElection(b, cluster, all)

	// 2. The leader B crashes. C and D time out at the same moment:
	//    C reaches only A, D reaches only E. A split vote.
	fmt.Println("-- B crashes --")
	StartElection(c, cluster, map[string]bool{"A": true})
	StartElection(d, cluster, map[string]bool{"E": true})

	// 3. D's random timeout fires first next time.
	StartElection(d, cluster, map[string]bool{"A": true, "C": true, "E": true})

	// 4. B comes back, still believing it is in term 1, and asks for votes
	//    with its old term number.
	fmt.Println("-- B returns with a stale term --")
	fmt.Println("    A grants B a vote for term 1:", a.RequestVote("B", 1))
	b.SeeTerm(a.term) // A's reply carries term 3
	fmt.Println("    B sees term", b.term, "in the reply and becomes a", b.role)

	for _, n := range cluster {
		fmt.Printf("%s: term %d, %s\n", n.name, n.term, n.role)
	}
}

package main

import (
	"errors"
	"fmt"
	"time"
)

var ErrOpen = errors.New("circuit open: call skipped")

type Breaker struct {
	threshold int
	cooldown  time.Duration
	now       func() time.Time

	state    string // "closed", "open" or "half-open"
	failures int
	openedAt time.Time
}

func NewBreaker(threshold int, cooldown time.Duration, now func() time.Time) *Breaker {
	return &Breaker{threshold: threshold, cooldown: cooldown, now: now, state: "closed"}
}

func (b *Breaker) Call(fn func() error) error {
	if b.state == "open" {
		if b.now().Sub(b.openedAt) < b.cooldown {
			return ErrOpen
		}
		b.state = "half-open" // cooldown over: allow one trial
	}
	err := fn()
	if err == nil {
		b.state, b.failures = "closed", 0
		return nil
	}
	b.failures++
	if b.state == "half-open" || b.failures >= b.threshold {
		b.state, b.openedAt = "open", b.now()
	}
	return err
}

func main() {
	clock := time.Date(2026, 1, 1, 12, 0, 0, 0, time.UTC)
	now := func() time.Time { return clock }
	b := NewBreaker(3, 10*time.Second, now)

	healthy := true
	calls := 0
	service := func() error {
		calls++
		if !healthy {
			return errors.New("service B: 503 unavailable")
		}
		return nil
	}
	try := func(note string) {
		err := b.Call(service)
		fmt.Printf("%-28s err=%-32v state=%-9s real calls so far: %d\n", note, err, b.state, calls)
	}

	try("B healthy")
	healthy = false
	try("B fails (1)")
	try("B fails (2)")
	try("B fails (3) -> trips")
	try("skipped")
	try("skipped")
	clock = clock.Add(11 * time.Second)
	try("after cooldown: trial fails")
	try("skipped")
	clock = clock.Add(11 * time.Second)
	healthy = true
	try("after cooldown: trial works")
	try("B healthy")
}

