import (
	"fmt"
	"math/rand/v2"
)

func MergeSort[T any](a []T, less func(x, y T) bool) []T {
	if len(a) < 2 {
		return a
	}
	mid := len(a) / 2
	left, right := MergeSort(a[:mid], less), MergeSort(a[mid:], less)
	out := make([]T, 0, len(a))
	i, j := 0, 0
	for i < len(left) && j < len(right) {
		if !less(right[j], left[i]) { // ties take from the left: stable
			out = append(out, left[i])
			i++
		} else {
			out = append(out, right[j])
			j++
		}
	}
	out = append(out, left[i:]...)
	return append(out, right[j:]...)
}

func QuickSort[T any](a []T, less func(x, y T) bool, middlePivot bool) {
	if len(a) < 2 {
		return
	}
	last := len(a) - 1
	if middlePivot {
		a[len(a)/2], a[last] = a[last], a[len(a)/2]
	}
	pivot := a[last]
	i := 0
	for j := range last { // partition
		if less(a[j], pivot) {
			a[i], a[j] = a[j], a[i]
			i++
		}
	}
	a[i], a[last] = a[last], a[i] // pivot into its final place
	QuickSort(a[:i], less, middlePivot)
	QuickSort(a[i+1:], less, middlePivot)
}

type Player struct {
	Name  string
	Score int
}

func main() {
	fmt.Println(MergeSort([]int{5, 2, 9, 1, 5, 6}, func(x, y int) bool { return x < y }))
	q := []int{5, 2, 9, 1, 5, 6}
	QuickSort(q, func(x, y int) bool { return x < y }, true)
	fmt.Println(q)

	count := 0
	counting := func(x, y int) bool { count++; return x < y }
	rng := rand.New(rand.NewPCG(1, 2))
	random := make([]int, 1000)
	sorted := make([]int, 1000)
	for i := range random {
		random[i], sorted[i] = rng.IntN(100000), i
	}
	run := func(name string, sort func([]int)) {
		for _, in := range []struct {
			kind string
			data []int
		}{{"random", random}, {"sorted", sorted}} {
			count = 0
			sort(append([]int(nil), in.data...))
			fmt.Printf("%-28s %-7s input: %6d comparisons\n", name, in.kind, count)
		}
	}
	run("merge sort", func(a []int) { MergeSort(a, counting) })
	run("quicksort, middle pivot", func(a []int) { QuickSort(a, counting, true) })
	run("quicksort, last-item pivot", func(a []int) { QuickSort(a, counting, false) })

	// Stability: players are in name order; sort by score.
	players := []Player{{"Ada", 90}, {"Bob", 75}, {"Cleo", 90}, {"Dan", 75}, {"Eve", 90}}
	byScore := func(x, y Player) bool { return x.Score > y.Score }
	fmt.Println("merge sort (stable):", MergeSort(players, byScore))
	qs := append([]Player(nil), players...)
	QuickSort(qs, byScore, true)
	fmt.Println("quicksort (unstable):", qs)
}

