import (
	"fmt"
	"strings"
)

func failureTable(p string) []int {
	table := make([]int, len(p))
	k := 0
	for i := 1; i < len(p); i++ {
		for k > 0 && p[i] != p[k] {
			k = table[k-1]
		}
		if p[i] == p[k] {
			k++
		}
		table[i] = k
	}
	return table
}

// Search returns every position where pattern starts in text, and
// the number of character comparisons made.
func Search(text, pattern string) (found []int, comparisons int) {
	table := failureTable(pattern)
	k := 0
	for i := 0; i < len(text); i++ {
		for k > 0 {
			comparisons++
			if text[i] == pattern[k] {
				break
			}
			k = table[k-1]
		}
		if k == 0 {
			comparisons++
		}
		if text[i] == pattern[k] {
			k++
		}
		if k == len(pattern) {
			found = append(found, i-k+1)
			k = table[k-1]
		}
	}
	return found, comparisons
}

func naive(text, pattern string) (found []int, comparisons int) {
	for i := 0; i+len(pattern) <= len(text); i++ {
		j := 0
		for j < len(pattern) {
			comparisons++
			if text[i+j] != pattern[j] {
				break
			}
			j++
		}
		if j == len(pattern) {
			found = append(found, i)
		}
	}
	return found, comparisons
}

func main() {
	fmt.Println("table for ababc:  ", failureTable("ababc"))
	fmt.Println("table for aabaaab:", failureTable("aabaaab"))

	found, _ := Search("abababcabababc", "ababc")
	fmt.Println("ababc in abababcabababc at:", found)
	found, _ = Search("aaaa", "aa")
	fmt.Println("aa in aaaa at (overlapping):", found)
	found, _ = Search("gopher", "xyz")
	fmt.Println("xyz in gopher:", found)

	text := strings.Repeat("a", 2000) + "b"
	pattern := strings.Repeat("a", 50) + "b"
	f1, c1 := naive(text, pattern)
	f2, c2 := Search(text, pattern)
	fmt.Println("worst case, 2001-character text, 51-character pattern:")
	fmt.Printf("  naive: found at %v after %d comparisons\n", f1, c1)
	fmt.Printf("  KMP:   found at %v after %d comparisons\n", f2, c2)
}

