import (
	"cmp"
	"fmt"
	"slices"
)

type Edge struct {
	A, B   string
	Weight int
}

type UnionFind struct{ parent map[string]string }

func (u *UnionFind) Find(x string) string {
	if u.parent[x] == "" {
		u.parent[x] = x
	}
	if u.parent[x] != x {
		u.parent[x] = u.Find(u.parent[x]) // path compression
	}
	return u.parent[x]
}

// Union merges the groups of a and b; it reports false if they were
// already in the same group.
func (u *UnionFind) Union(a, b string) bool {
	ra, rb := u.Find(a), u.Find(b)
	if ra == rb {
		return false
	}
	u.parent[ra] = rb
	return true
}

func Kruskal(edges []Edge) (tree []Edge, total int) {
	sorted := slices.Clone(edges)
	slices.SortFunc(sorted, func(x, y Edge) int {
		return cmp.Or(cmp.Compare(x.Weight, y.Weight), cmp.Compare(x.A+x.B, y.A+y.B))
	})
	uf := &UnionFind{parent: map[string]string{}}
	for _, e := range sorted {
		if uf.Union(e.A, e.B) {
			tree = append(tree, e)
			total += e.Weight
			fmt.Printf("  take %s-%s (%d)\n", e.A, e.B, e.Weight)
		} else {
			fmt.Printf("  skip %s-%s (%d): already connected\n", e.A, e.B, e.Weight)
		}
	}
	return tree, total
}

func main() {
	edges := []Edge{
		{"Aswan", "Luxor", 7}, {"Aswan", "Qena", 9}, {"Luxor", "Qena", 2},
		{"Luxor", "Sohag", 8}, {"Qena", "Sohag", 5}, {"Sohag", "Asyut", 4},
		{"Qena", "Asyut", 10}, {"Asyut", "Minya", 6}, {"Sohag", "Minya", 11},
		{"Minya", "Cairo", 12}, {"Asyut", "Cairo", 15},
	}
	all := 0
	for _, e := range edges {
		all += e.Weight
	}
	tree, total := Kruskal(edges)
	fmt.Printf("links built: %d of %d, cost %d (every link would cost %d)\n", len(tree), len(edges), total, all)
}

