import (
	"fmt"
	"sort"
)

type Item struct {
	Name          string
	Weight, Value int
}

func Knapsack(items []Item, capacity int) int {
	best := make([]int, capacity+1)
	for _, it := range items {
		for w := capacity; w >= it.Weight; w-- { // downwards: each item once
			best[w] = max(best[w], best[w-it.Weight]+it.Value)
		}
	}
	return best[capacity]
}

// The greedy idea, for comparison: best value per kilogram first.
func greedy(items []Item, capacity int) int {
	sorted := append([]Item(nil), items...)
	sort.Slice(sorted, func(i, j int) bool {
		return sorted[i].Value*sorted[j].Weight > sorted[j].Value*sorted[i].Weight
	})
	total := 0
	for _, it := range sorted {
		if it.Weight <= capacity {
			capacity -= it.Weight
			total += it.Value
		}
	}
	return total
}

func LIS(nums []int) int {
	var tails []int
	for _, x := range nums {
		i := sort.SearchInts(tails, x)
		if i == len(tails) {
			tails = append(tails, x)
		} else {
			tails[i] = x
		}
		fmt.Printf("  after %3d: tails = %v\n", x, tails)
	}
	return len(tails)
}

func main() {
	items := []Item{
		{"laptop", 3, 2000}, {"camera", 1, 1500}, {"tablet", 2, 1400}, {"guitar", 4, 3000},
	}
	for _, capacity := range []int{4, 5, 7} {
		fmt.Printf("capacity %d: best value %d (greedy would get %d)\n", capacity, Knapsack(items, capacity), greedy(items, capacity))
	}

	nums := []int{10, 9, 2, 5, 3, 7, 101, 18}
	fmt.Println("numbers:", nums)
	fmt.Println("longest increasing subsequence length:", LIS(nums))
}

package main

import (
	"container/heap"
	"fmt"
)

type P struct{ r, c int }

type item struct {
	p    P
	f, g int
}

type queue []item

func (q queue) Len() int { return len(q) }
func (q queue) Less(i, j int) bool {
	if q[i].f != q[j].f {
		return q[i].f < q[j].f
	}
	return q[i].g > q[j].g
}
func (q queue) Swap(i, j int) { q[i], q[j] = q[j], q[i] }
func (q *queue) Push(x any)   { *q = append(*q, x.(item)) }
func (q *queue) Pop() any {
	old := *q
	it := old[len(old)-1]
	*q = old[:len(old)-1]
	return it
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

func Search(grid []string, start, goal P, useHeuristic bool) (path []P, expanded int) {
	h := func(p P) int {
		if !useHeuristic {
			return 0 // Dijkstra
		}
		return abs(p.r-goal.r) + abs(p.c-goal.c)
	}
	best := map[P]int{start: 0}
	from := map[P]P{}
	open := &queue{{start, h(start), 0}}
	for open.Len() > 0 {
		cur := heap.Pop(open).(item)
		if cur.g > best[cur.p] {
			continue // an outdated entry
		}
		expanded++
		if cur.p == goal {
			break
		}
		for _, d := range []P{{0, 1}, {1, 0}, {0, -1}, {-1, 0}} {
			n := P{cur.p.r + d.r, cur.p.c + d.c}
			if n.r < 0 || n.r >= len(grid) || n.c < 0 || n.c >= len(grid[0]) || grid[n.r][n.c] == '#' {
				continue
			}
			g := cur.g + 1
			if old, seen := best[n]; !seen || g < old {
				best[n], from[n] = g, cur.p
				heap.Push(open, item{n, g + h(n), g})
			}
		}
	}
	if _, ok := best[goal]; !ok {
		return nil, expanded
	}
	for p := goal; p != start; p = from[p] {
		path = append(path, p)
	}
	return path, expanded
}

func main() {
	grid := []string{
		"S.........",
		".####.....",
		"....#.....",
		".##.#.###.",
		".#..#...#.",
		".#.####.#G",
		".#......#.",
		"..........",
	}
	var start, goal P
	for r, row := range grid {
		for c, ch := range row {
			switch ch {
			case 'S':
				start = P{r, c}
			case 'G':
				goal = P{r, c}
			}
		}
	}
	dPath, dExpanded := Search(grid, start, goal, false)
	aPath, aExpanded := Search(grid, start, goal, true)
	fmt.Printf("Dijkstra: path length %d, positions expanded %d\n", len(dPath), dExpanded)
	fmt.Printf("A*:       path length %d, positions expanded %d\n", len(aPath), aExpanded)

	out := make([][]byte, len(grid))
	for r := range grid {
		out[r] = []byte(grid[r])
	}
	for _, p := range aPath[1:] { // aPath[0] is the goal itself
		out[p.r][p.c] = '*'
	}
	for _, row := range out {
		fmt.Println(string(row))
	}
}

package main

import "fmt"

func GCD(a, b int) int {
	for b != 0 {
		a, b = b, a%b
	}
	return a
}

func LCM(a, b int) int { return a / GCD(a, b) * b }

func Primes(n int) []int {
	composite := make([]bool, n+1)
	var primes []int
	for p := 2; p <= n; p++ {
		if composite[p] {
			continue
		}
		primes = append(primes, p)
		for m := p * p; m <= n; m += p {
			composite[m] = true
		}
	}
	return primes
}

func ModPow(base, exp, mod int) int {
	result := 1
	base %= mod
	for exp > 0 {
		if exp%2 == 1 {
			result = result * base % mod
		}
		base = base * base % mod
		exp /= 2
	}
	return result
}

func main() {
	fmt.Println("gcd(1071, 462) =", GCD(1071, 462))
	fmt.Println("lcm(4, 6) =", LCM(4, 6))
	fmt.Println("lcm(21, 6) =", LCM(21, 6))
	fmt.Println("primes up to 50:", Primes(50))
	fmt.Println("primes below 100000:", len(Primes(99999)))
	fmt.Println("2^10 mod 1000 =", ModPow(2, 10, 1000))
	fmt.Println("3^200 mod 13 =", ModPow(3, 200, 13))
	fmt.Println("2^1000000007 mod 1000000007 =", ModPow(2, 1000000007, 1000000007))
}

package main

import (
	"bufio"
	"fmt"
	"io"
	"net"
	"strconv"
	"strings"
)

func respond(w io.Writer, code int, reason, body string) {
	fmt.Fprintf(w, "HTTP/1.1 %d %s\r\nContent-Type: text/plain\r\nContent-Length: %d\r\nConnection: close\r\n\r\n%s",
		code, reason, len(body), body)
}

func handle(conn net.Conn) {
	defer conn.Close()
	r := bufio.NewReader(conn)

	line, err := r.ReadString('\n') // request line
	if err != nil {
		return
	}
	parts := strings.Fields(line)
	if len(parts) != 3 {
		respond(conn, 400, "Bad Request", "malformed request line\n")
		return
	}
	method, target := parts[0], parts[1]

	headers := map[string]string{}
	for {
		h, err := r.ReadString('\n')
		if err != nil {
			return
		}
		h = strings.TrimRight(h, "\r\n")
		if h == "" {
			break // the empty line: headers are finished
		}
		name, value, _ := strings.Cut(h, ":")
		headers[strings.ToLower(name)] = strings.TrimSpace(value)
	}

	var body []byte
	if n, _ := strconv.Atoi(headers["content-length"]); n > 0 {
		body = make([]byte, n)
		if _, err := io.ReadFull(r, body); err != nil {
			return
		}
	}

	path, query, _ := strings.Cut(target, "?")
	switch {
	case method == "GET" && path == "/hello":
		name := strings.TrimPrefix(query, "name=")
		if name == "" {
			name = "world"
		}
		respond(conn, 200, "OK", "hello, "+name+"\n")
	case method == "POST" && path == "/shout":
		respond(conn, 200, "OK", strings.ToUpper(string(body))+"\n")
	default:
		respond(conn, 404, "Not Found", "no such page: "+path+"\n")
	}
}

func show(prefix, raw string) {
	text := strings.TrimRight(strings.ReplaceAll(raw, "\r\n", "\n"), "\n")
	for _, line := range strings.Split(text, "\n") {
		fmt.Println(prefix, line)
	}
}

func roundTrip(addr, request string) {
	conn, err := net.Dial("tcp", addr)
	if err != nil {
		fmt.Println("dial:", err)
		return
	}
	defer conn.Close()
	io.WriteString(conn, request)
	reply, _ := io.ReadAll(conn) // the server closes when it is done
	show(">>", request)
	show("<<", string(reply))
	fmt.Println()
}

func main() {
	ln, err := net.Listen("tcp", "127.0.0.1:0")
	if err != nil {
		fmt.Println("listen:", err)
		return
	}
	defer ln.Close()
	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return // listener closed
			}
			go handle(conn)
		}
	}()

	addr := ln.Addr().String()
	roundTrip(addr, "GET /hello?name=Ada HTTP/1.1\r\nHost: example.com\r\nConnection: close\r\n\r\n")
	body := "go is fun"
	roundTrip(addr, "POST /shout HTTP/1.1\r\nHost: example.com\r\nContent-Length: "+strconv.Itoa(len(body))+"\r\n\r\n"+body)
	roundTrip(addr, "GET /missing HTTP/1.1\r\nHost: example.com\r\n\r\n")
	roundTrip(addr, "HELLO\r\n\r\n")
}

package main

import (
	"fmt"
	"io"
	"net/http"
	"net/http/httptest"
	"net/http/httputil"
	"net/url"
	"sync"
)

type Backend struct {
	name    string
	url     *url.URL
	proxy   *httputil.ReverseProxy
	healthy bool
}

type Balancer struct {
	mu       sync.Mutex
	backends []*Backend
	next     int
}

func (lb *Balancer) Add(name, rawURL string) {
	u, err := url.Parse(rawURL)
	if err != nil {
		panic(err)
	}
	lb.backends = append(lb.backends, &Backend{name, u, httputil.NewSingleHostReverseProxy(u), true})
}

// pick returns the next healthy backend in round-robin order.
func (lb *Balancer) pick() *Backend {
	lb.mu.Lock()
	defer lb.mu.Unlock()
	for range lb.backends {
		b := lb.backends[lb.next%len(lb.backends)]
		lb.next++
		if b.healthy {
			return b
		}
	}
	return nil
}

func (lb *Balancer) ServeHTTP(w http.ResponseWriter, r *http.Request) {
	b := lb.pick()
	if b == nil {
		http.Error(w, "no healthy backend", http.StatusServiceUnavailable)
		return
	}
	b.proxy.ServeHTTP(w, r)
}

// Check asks every backend for /healthz and records the result.
func (lb *Balancer) Check() {
	for _, b := range lb.backends {
		resp, err := http.Get(b.url.String() + "/healthz")
		ok := err == nil && resp.StatusCode == http.StatusOK
		if err == nil {
			resp.Body.Close()
		}
		lb.mu.Lock()
		b.healthy = ok
		lb.mu.Unlock()
		fmt.Printf("  health check %s: healthy=%v\n", b.name, ok)
	}
}

func newBackend(name string) *httptest.Server {
	mux := http.NewServeMux()
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) { fmt.Fprint(w, "ok") })
	mux.HandleFunc("GET /", func(w http.ResponseWriter, r *http.Request) {
		fmt.Fprintf(w, "%s served %s", name, r.URL.Path)
	})
	return httptest.NewServer(mux)
}

func main() {
	lb := &Balancer{}
	var servers []*httptest.Server
	for _, name := range []string{"backend-1", "backend-2", "backend-3"} {
		s := newBackend(name)
		servers = append(servers, s)
		lb.Add(name, s.URL)
	}
	front := httptest.NewServer(lb)
	defer front.Close()

	get := func(path string) {
		resp, err := http.Get(front.URL + path)
		if err != nil {
			fmt.Println("  error:", err)
			return
		}
		defer resp.Body.Close()
		body, _ := io.ReadAll(resp.Body)
		fmt.Printf("  GET %-8s -> %d %s\n", path, resp.StatusCode, string(body))
	}

	fmt.Println("three healthy backends:")
	for _, p := range []string{"/a", "/b", "/c", "/d"} {
		get(p)
	}

	fmt.Println("backend-2 goes down:")
	servers[1].Close()
	lb.Check()
	for _, p := range []string{"/e", "/f", "/g", "/h"} {
		get(p)
	}

	fmt.Println("everything goes down:")
	servers[0].Close()
	servers[2].Close()
	lb.Check()
	get("/i")
}

package main

import (
	"errors"
	"fmt"
	"net"
	"net/rpc"
)

type Args struct{ A, B int }

type Calc struct{}

func (c *Calc) Multiply(args Args, reply *int) error {
	*reply = args.A * args.B
	return nil
}

func (c *Calc) Divide(args Args, reply *int) error {
	if args.B == 0 {
		return errors.New("divide by zero")
	}
	*reply = args.A / args.B
	return nil
}

type Stats struct {
	Sum, Count int
	Mean       float64
}

func (c *Calc) Summarise(nums []int, reply *Stats) error {
	for _, n := range nums {
		reply.Sum += n
	}
	reply.Count = len(nums)
	if reply.Count > 0 {
		reply.Mean = float64(reply.Sum) / float64(reply.Count)
	}
	return nil
}

func main() {
	server := rpc.NewServer()
	if err := server.Register(new(Calc)); err != nil {
		fmt.Println("register:", err)
		return
	}
	clientEnd, serverEnd := net.Pipe()
	go server.ServeConn(serverEnd)
	client := rpc.NewClient(clientEnd)
	defer client.Close()

	var product int
	err := client.Call("Calc.Multiply", Args{6, 7}, &product)
	fmt.Println("Multiply(6, 7) =", product, "err:", err)

	var quotient int
	err = client.Call("Calc.Divide", Args{1, 0}, &quotient)
	fmt.Printf("Divide(1, 0) err: %v (type %T)\n", err, err)

	var st Stats
	err = client.Call("Calc.Summarise", []int{4, 8, 15, 16, 23, 42}, &st)
	fmt.Printf("Summarise -> %+v err: %v\n", st, err)

	// Two calls in flight at once.
	var x, y int
	c1 := client.Go("Calc.Multiply", Args{3, 4}, &x, nil)
	c2 := client.Go("Calc.Multiply", Args{5, 6}, &y, nil)
	<-c1.Done
	<-c2.Done
	fmt.Println("async results:", x, y, "errors:", c1.Error, c2.Error)

	err = client.Call("Calc.Sqrt", Args{9, 0}, &product)
	fmt.Println("unknown method err:", err)
}

package main

import (
	"encoding/binary"
	"fmt"
	"strings"
)

func encodeName(name string) []byte {
	var out []byte
	for _, label := range strings.Split(name, ".") {
		out = append(out, byte(len(label)))
		out = append(out, label...)
	}
	return append(out, 0)
}

// Query builds a question for the A record of name.
func Query(id uint16, name string) []byte {
	msg := make([]byte, 12)
	binary.BigEndian.PutUint16(msg[0:], id)
	binary.BigEndian.PutUint16(msg[2:], 0x0100) // flags: recursion desired
	binary.BigEndian.PutUint16(msg[4:], 1)      // QDCOUNT
	msg = append(msg, encodeName(name)...)
	msg = binary.BigEndian.AppendUint16(msg, 1) // type A
	msg = binary.BigEndian.AppendUint16(msg, 1) // class IN
	return msg
}

// fakeServer answers any query with one A record.
func fakeServer(query []byte, ip [4]byte, ttl uint32) []byte {
	msg := append([]byte(nil), query...)
	binary.BigEndian.PutUint16(msg[2:], 0x8180) // flags: response
	binary.BigEndian.PutUint16(msg[6:], 1)      // ANCOUNT
	msg = append(msg, 0xC0, 0x0C)               // name: pointer to offset 12
	msg = binary.BigEndian.AppendUint16(msg, 1) // type A
	msg = binary.BigEndian.AppendUint16(msg, 1) // class IN
	msg = binary.BigEndian.AppendUint32(msg, ttl)
	msg = binary.BigEndian.AppendUint16(msg, 4) // data length
	return append(msg, ip[:]...)
}

// readName decodes a name starting at off and returns it with the
// offset just past it.
func readName(msg []byte, off int) (string, int) {
	var labels []string
	for {
		n := int(msg[off])
		switch {
		case n == 0:
			return strings.Join(labels, "."), off + 1
		case n&0xC0 == 0xC0: // compression pointer
			ptr := int(binary.BigEndian.Uint16(msg[off:]) & 0x3FFF)
			rest, _ := readName(msg, ptr)
			return strings.Join(append(labels, rest), "."), off + 2
		}
		labels = append(labels, string(msg[off+1:off+1+n]))
		off += 1 + n
	}
}

func Parse(msg []byte) {
	id := binary.BigEndian.Uint16(msg[0:])
	flags := binary.BigEndian.Uint16(msg[2:])
	questions := int(binary.BigEndian.Uint16(msg[4:]))
	answers := int(binary.BigEndian.Uint16(msg[6:]))
	fmt.Printf("  id=%d response=%v questions=%d answers=%d\n", id, flags&0x8000 != 0, questions, answers)
	off := 12
	for range questions {
		var name string
		name, off = readName(msg, off)
		fmt.Printf("  question: %s type=%d\n", name, binary.BigEndian.Uint16(msg[off:]))
		off += 4 // type and class
	}
	for range answers {
		var name string
		name, off = readName(msg, off)
		ttl := binary.BigEndian.Uint32(msg[off+4:])
		n := int(binary.BigEndian.Uint16(msg[off+8:]))
		data := msg[off+10 : off+10+n]
		fmt.Printf("  answer:   %s -> %d.%d.%d.%d (ttl %ds)\n", name, data[0], data[1], data[2], data[3], ttl)
		off += 10 + n
	}
}

func main() {
	q := Query(4660, "www.example.com")
	fmt.Printf("query, %d bytes:\n  % x\n", len(q), q)
	Parse(q)

	reply := fakeServer(q, [4]byte{192, 0, 2, 10}, 300)
	fmt.Printf("reply, %d bytes:\n  % x\n", len(reply), reply)
	Parse(reply)
}

package main

import (
	"fmt"
	"sync"
	"sync/atomic"
)

type Conn struct{ id int }

type Pool struct {
	idle  chan *Conn
	mu    sync.Mutex
	open  int // connections that exist (idle or lent out)
	max   int
	dials int // how many times we had to open a new one
}

func NewPool(max int) *Pool { return &Pool{idle: make(chan *Conn, max), max: max} }

func (p *Pool) Get() *Conn {
	select {
	case c := <-p.idle: // 1. reuse an idle connection
		return c
	default:
	}
	p.mu.Lock()
	if p.open < p.max { // 2. room to open a new one
		p.open++
		p.dials++
		c := &Conn{id: p.dials}
		p.mu.Unlock()
		return c
	}
	p.mu.Unlock()
	return <-p.idle // 3. wait for someone to Put one back
}

func (p *Pool) Put(c *Conn) { p.idle <- c }

func main() {
	p := NewPool(3)
	a, b := p.Get(), p.Get()
	fmt.Println("borrowed connections", a.id, "and", b.id, "- dials so far:", p.dials)
	p.Put(a)
	c := p.Get()
	fmt.Println("after returning", a.id, "the next Get reuses", c.id, "- dials so far:", p.dials)
	d := p.Get()
	fmt.Println("no idle one left, so a third is opened:", d.id, "- dials so far:", p.dials)
	p.Put(b)
	p.Put(c)
	p.Put(d)

	// 50 jobs share the 3 connections.
	var wg sync.WaitGroup
	var inUse, peak, done atomic.Int32
	for range 50 {
		wg.Add(1)
		go func() {
			defer wg.Done()
			conn := p.Get()
			n := inUse.Add(1)
			for {
				old := peak.Load()
				if n <= old || peak.CompareAndSwap(old, n) {
					break
				}
			}
			done.Add(1) // "use" the connection
			inUse.Add(-1)
			p.Put(conn)
		}()
	}
	wg.Wait()
	fmt.Println("jobs finished:", done.Load())
	fmt.Println("total dials:", p.dials, "(without a pool: 53)")
	fmt.Println("never more than 3 in use at once:", peak.Load() <= 3)
}

package main

import (
	"bufio"
	"errors"
	"fmt"
	"io"
	"strconv"
	"strings"
)

func Encode(args ...string) string {
	var b strings.Builder
	fmt.Fprintf(&b, "*%d\r\n", len(args))
	for _, a := range args {
		fmt.Fprintf(&b, "$%d\r\n%s\r\n", len(a), a)
	}
	return b.String()
}

func Decode(r *bufio.Reader) (any, error) {
	line, err := r.ReadString('\n')
	if err != nil {
		return nil, err
	}
	line = strings.TrimSuffix(line, "\r\n")
	if line == "" {
		return nil, errors.New("empty line")
	}
	kind, rest := line[0], line[1:]
	switch kind {
	case '+':
		return rest, nil
	case '-':
		return errors.New(rest), nil
	case ':':
		return strconv.Atoi(rest)
	case '$':
		n, err := strconv.Atoi(rest)
		if err != nil {
			return nil, err
		}
		if n < 0 {
			return nil, nil
		}
		buf := make([]byte, n+2)
		if _, err := io.ReadFull(r, buf); err != nil {
			return nil, err
		}
		return string(buf[:n]), nil
	case '*':
		n, err := strconv.Atoi(rest)
		if err != nil {
			return nil, err
		}
		items := make([]any, 0, n)
		for range n {
			v, err := Decode(r)
			if err != nil {
				return nil, err
			}
			items = append(items, v)
		}
		return items, nil
	}
	return nil, fmt.Errorf("unknown type byte %q", kind)
}

func describe(v any) string {
	switch v := v.(type) {
	case nil:
		return "nil"
	case string:
		return fmt.Sprintf("string %q", v)
	case int:
		return fmt.Sprintf("int %d", v)
	case error:
		return fmt.Sprintf("error %q", v.Error())
	case []any:
		parts := make([]string, len(v))
		for i, item := range v {
			parts[i] = describe(item)
		}
		return "array [" + strings.Join(parts, ", ") + "]"
	}
	return fmt.Sprintf("unexpected %T", v)
}

func main() {
	fmt.Printf("%q\n", Encode("SET", "name", "Ada"))
	fmt.Printf("%q\n", Encode("GET", "name"))

	input := "+OK\r\n:42\r\n$5\r\nhello\r\n$-1\r\n-ERR unknown command\r\n" +
		"*3\r\n$1\r\na\r\n:7\r\n*2\r\n+x\r\n$-1\r\n"
	r := bufio.NewReader(strings.NewReader(input))
	for {
		v, err := Decode(r)
		if err == io.EOF {
			break
		}
		if err != nil {
			fmt.Println("decode error:", err)
			break
		}
		fmt.Println(describe(v))
	}
}

